# ---------------------------------------------------------------------------
# r28-d · ARREGLAR EL TEXTO QUE VIENE ROTO (lo mejor que se puede)
#
# Hay PDF (sobre todo escaneados con OCR viejo) que devuelven el texto así:
#      E S T U D I O   S O B R E   L A   V I C T O R I A
# o con las palabras partidas por el salto de línea: «investi-\nmento». Eso hace
# que la búsqueda no encuentre lo que el usuario ve en la pantalla.
# Aquí se junta: letras sueltas seguidas (3 o más) forman la palabra, y los
# guiones de fin de línea se quitan. Es lo que hace legible y buscable su
# «Tomo 14/17 Digital».
# ---------------------------------------------------------------------------
_LETRA = "A-Za-zÁÉÍÓÚÜÑáéíóúüñ"
_RE_LETRAS_SUELTAS = re.compile(
    rf"(?<![{_LETRA}\w])((?:[{_LETRA}][ \t.]{{1,2}}){{3,}}[{_LETRA}])(?![{_LETRA}\w])")


def esta_letra_a_letra(texto: str) -> bool:
    """
    ¿Este texto viene «letra a letra»? (el caso de los Tomos escaneados):
        E S T U D I O   B I B L I C O   D E   M A S …
    Se nota porque casi todas las «palabras» son de una sola letra.
    """
    trozos = (texto or "").split()
    if len(trozos) < 9:
        return False
    sueltas = sum(1 for t in trozos if len(t) == 1 and t.isalpha())
    return sueltas / len(trozos) > 0.34


def texto_por_posiciones(pagina) -> str:
    """
    Reconstruye la página usando LA POSICIÓN REAL DE CADA TROZO DE TEXTO.

    Es la solución buena para sus Tomos escaneados: el lector devuelve
    «E S T U D I O B I B L I C O» porque no sabe dónde acaba una palabra, pero
    el PDF sí guarda la coordenada exacta de cada letra. Aquí se miran esas
    coordenadas: si entre dos trozos hay un hueco claramente mayor que el hueco
    normal de esa misma línea, ahí había un ESPACIO; si no, van juntos.
    Devuelve "" si no se pudo mirar la página de esta forma.
    """
    piezas = []
    medida = {"tamano": 10.0}

    def antes(operador, operandos, cm, tm):
        try:
            op = operador.decode("latin-1") if isinstance(operador, bytes) else str(operador)
        except Exception:
            return
        if op == "Tf" and len(operandos) >= 2:
            try:
                medida["tamano"] = abs(float(operandos[1])) or 10.0
            except (TypeError, ValueError):
                pass
            return
        if op not in ("Tj", "TJ", "'", '"') or not tm or len(tm) < 6:
            return
        texto = ""
        for o in operandos:
            if isinstance(o, bytes):
                texto += o.decode("latin-1", "replace")
            elif isinstance(o, str):
                texto += o
            elif isinstance(o, (list, tuple)):
                for e in o:
                    if isinstance(e, bytes):
                        texto += e.decode("latin-1", "replace")
                    elif isinstance(e, str):
                        texto += e
        if texto.strip():
            try:
                piezas.append((round(float(tm[5]), 1), float(tm[4]), texto, medida["tamano"]))
            except (TypeError, ValueError):
                pass

    try:
        pagina.extract_text(visitor_operand_before=antes)
    except Exception:
        return ""
    if not piezas:
        return ""

    lineas = {}
    for y, x, t, tam in piezas:
        lineas.setdefault(y, []).append((x, t, tam))

    salida = []
    for y in sorted(lineas, reverse=True):
        fila = sorted(lineas[y], key=lambda f: f[0])
        huecos = []
        for i in range(1, len(fila)):
            ancho_ant = 0.5 * fila[i - 1][2] * len(fila[i - 1][1])
            huecos.append(max(0.0, fila[i][0] - (fila[i - 1][0] + ancho_ant)))
        corte = None
        if huecos:
            ordenados = sorted(huecos)
            chico = ordenados[max(0, int(len(ordenados) * 0.2) - 1)]     # hueco normal
            corte = max(chico * 1.8, chico + 1.0)
        texto_linea = ""
        for i, (x, t, tam) in enumerate(fila):
            if i and corte is not None and huecos[i - 1] >= corte:
                texto_linea += " "                       # aquí había una palabra nueva
            texto_linea += t
        limpia = re.sub(r"[ \t]{2,}", " ", texto_linea).strip()
        if limpia:
            salida.append(limpia)
    return "\n".join(salida)


def reconstruir_palabras(con_huecos: str) -> str:
    """
    Reconstruye las palabras a partir de un texto sacado con las POSICIONES
    (modo «layout»), donde lo que separa las LETRAS son huecos pequeños y lo que
    separa las PALABRAS son huecos grandes:
        E  S  T  U  D  I  O        B  I  B  L  I  C  O
        └── hueco pequeño: letra ──┘└─ hueco grande: palabra ─┘
    Devuelve «ESTUDIO BIBLICO». Si el texto no viene así, lo devuelve igual.
    """
    lineas = []
    for linea in (con_huecos or "").split("\n"):
        if not linea.strip():
            continue
        trozos = re.split(r"( +)", linea)
        huecos = [len(t) for t in trozos if t and not t.strip()]
        if not huecos:
            lineas.append(re.sub(r" {2,}", " ", linea).strip())
            continue
        # El hueco de las LETRAS es el más pequeño que se repite; el de las
        # PALABRAS es claramente más grande. Se calculan aquí (no se dan por
        # hechos): en sus Tomos cada página tiene sus propias medidas.
        huecos.sort()
        chico = huecos[0]
        for h in huecos:
            if h <= chico * 1.6:
                chico = h
            else:
                break
        corte = max(chico * 1.7, chico + 1.5)
        hay_corte = huecos[-1] >= corte
        partes = []
        for trozo in trozos:
            if not trozo:
                continue
            if trozo.strip():
                partes.append(trozo)
            elif hay_corte and len(trozo) >= corte:
                partes.append(" ")             # hueco grande: entre PALABRAS
            elif len(trozo) > chico:
                partes.append(" ")             # algo más grande de lo normal: palabra
            else:
                partes.append("")              # hueco normal: entre LETRAS → se junta
        juntado = "".join(partes)
        if juntado.strip():
            lineas.append(re.sub(r" {2,}", " ", juntado).strip())
    return "\n".join(lineas)


def arreglar_texto_extraido(t: str) -> str:
    """
    Junta lo que el OCR (o la fuente del PDF) dejó separado:
      «E S T U D I O» → «ESTUDIO» · «investi-\nmento» → «investimento»
    No toca los acentos ni las palabras normales.
    """
    if not t:
        return t
    # los huecos de 2 o más espacios son CORTES DE PALABRA: se marcan para no
    # perderlos al juntar las letras (y se restauran al final).
    t = re.sub(r"[ \t]{2,}", "\u0001", t)

    def _junta(m):
        return "".join(re.findall(rf"[{_LETRA}0-9]", m.group(1)))

    # letras sueltas separadas por UN solo espacio: se juntan
    t = re.sub(rf"(?<![{_LETRA}0-9])((?:[{_LETRA}0-9][ \t]){{1,}}[{_LETRA}0-9])(?![{_LETRA}0-9])",
               _junta, t)
    t = t.replace("\u0001", " ")
    # palabras cortadas al final de la línea con guion
    t = re.sub(rf"([{_LETRA}])-\n([{_LETRA}])", r"\1\2", t)
    return t


def encabezado_de(paginas) -> str:
    """
    El TÍTULO QUE EL PROPIO PDF TRAE ARRIBA («encabezado» de la primera página):
    es el nombre que el usuario reconoce, aunque el archivo se llame «doc1234.pdf».
    Se devuelve solo si parece un título (letras de verdad, no un número de página).
    """
    if not paginas:
        return ""
    for p in paginas[:2]:
        for linea in (p.get("texto") or "").split("\n"):
            ln = " ".join(linea.split()).strip(" .,-–—|·")
            if not (6 <= len(ln) <= 130):
                continue
            letras = sum(1 for c in ln if c.isalpha())
            if letras < 0.55 * len(ln):          # «1», «12 de 376», «— III —»…
                continue
            bajo = ln.lower()
            if bajo.startswith(("página", "page", "http", "www", "índice", "indice")):
                continue
            return ln
    return ""


def normalizar_espacios(t: str) -> str:
    """Colapsa espacios/saltos repetidos sin destruir los saltos entre párrafos."""
    t = t.replace("\r\n", "\n").replace("\r", "\n")
    t = re.sub(r"[ \t\u00a0]+", " ", t)
    t = re.sub(r"\n{3,}", "\n\n", t)
    t = arreglar_texto_extraido(t)              # r28-d · junta lo que venga roto
    lineas = [ln.strip() for ln in t.split("\n")]
    return "\n".join(lineas).strip()


def tipo_archivo(nombre: str) -> str:
    ext = os.path.splitext(nombre)[1].lower()
    if ext in EXT_PDF:
        return "PDF"
    if ext in EXT_WPD:
        return "WordPerfect"
    if ext in EXT_DOCX:
        return "Word"
    if ext in EXT_DOC:
        return "Word 97-2003"
    if ext in EXT_ODT:
        return "OpenDocument"
    if ext in EXT_RTF:
        return "RTF"
    if ext in EXT_PPTX:
        return "PowerPoint"
    if ext in EXT_XLSX:
        return "Excel"
    if ext in EXT_TXT:
        return "Texto"
    return ext.lstrip(".").upper() or "Archivo"


# Cuando falta el lector de PDF (pypdf) TODOS los PDF fallarían y la biblioteca se
# llenaría de tarjetas "error". Para evitarlo, los extractores avisan con este error
# especial y la indexación se detiene con un mensaje claro en vez de marcar los
# documentos uno por uno.
FALTA_LECTOR_PDF = "FALTA_LECTOR_PDF"


def estado_lector_pdf() -> dict:
    """¿Está disponible el lector de PDF? (y qué versión)."""
    try:
        import pypdf
        return {"disponible": True, "version": getattr(pypdf, "__version__", "?"), "mensaje": ""}
    except ImportError as e:
        return {"disponible": False, "version": "",
                "mensaje": ("Falta el lector de PDF (pypdf). Sin él no se puede leer ningún PDF: "
                            "la aplicación lo instala sola al abrir; si no puede, revisa la conexión "
                            "a internet o ejecuta:  python -m pip install pypdf")}


def falta_lector_pdf(archivo: str) -> bool:
    """¿Este archivo necesita el lector de PDF y no está disponible?"""
    return os.path.splitext(archivo)[1].lower() in EXT_PDF and not estado_lector_pdf()["disponible"]


def ruta_io(ruta: str) -> str:
    """
    Ruta lista para abrir en este sistema.

    En Windows, cuando la ruta se acerca al límite de 260 caracteres, se le pone el
    prefijo de ruta larga: así la aplicación puede leer archivos en carpetas muy
    anidadas (sin ese prefijo, Windows falla y los archivos "desaparecen" del escaneo).
    """
    if os.name != "nt":
        return ruta
    try:
        ruta = os.path.abspath(ruta)
        if len(ruta) >= 240 and not ruta.startswith("\\\\?\\"):
            if ruta.startswith("\\\\"):
                return "\\\\?\\UNC\\" + ruta[2:]
            return "\\\\?\\" + ruta
    except Exception:
        pass
    return ruta


ATRIBUTOS_NUBE = 0x400000 | 0x1000      # solo en la nube (OneDrive) | fuera de línea


def solo_en_la_nube(archivo) -> bool:
    """
    ¿El archivo está "solo en la nube" (OneDrive sin descargar)?

    Windows lo dice en los atributos del archivo: no está en este equipo, solo
    aparece la ficha. Se puede leer su nombre pero no su contenido.
    """
    if os.name != "nt":
        return False
    try:
        if hasattr(archivo, "stat"):
            atributos = archivo.stat(follow_symlinks=True).st_file_attributes
        else:
            atributos = os.stat(ruta_io(str(archivo))).st_file_attributes
    except Exception:
        return False
    return bool(atributos & ATRIBUTOS_NUBE)


# Notas de GUÍA que vienen con el paquete (no son documentos del usuario y no
# tienen que aparecer en su biblioteca): «PONGA AQUI SUS DOCUMENTOS.txt»,
# «LEEME - esto es su biblioteca.txt»…
NOTAS_DEL_PAQUETE = ("ponga aqui", "ponga aquí", "leeme -", "léeme -", "leame -")


def es_nota_del_paquete(nombre: str) -> bool:
    bajo = (nombre or "").strip().lower()
    return bajo.startswith(NOTAS_DEL_PAQUETE)


def es_soportado(nombre: str) -> bool:
    # r28: las notas de guía del paquete NO cuentan como documentos.
    if es_nota_del_paquete(nombre):
        return False
    return os.path.splitext(nombre)[1].lower() in set(EXTENSIONES_SOPORTADAS)


# ---------------------------------------------------------------- PDF

def _silenciar_pypdf():
    """Los avisos internos de pypdf ("Object 9999 0 not defined.") no le sirven al usuario."""
    try:
        import logging
        logging.getLogger("pypdf").setLevel(logging.ERROR)
    except Exception:
        pass


def _metadatos_pdf(lector) -> dict:
    meta = {}
    try:
        info = lector.metadata or {}
        meta["titulo"] = (info.get("/Title") or "").strip() or None
        meta["autor"] = (info.get("/Author") or "").strip() or None
        fecha = (info.get("/CreationDate") or "")
        m = re.search(r"(19|20)\d{2}", str(fecha))
        if m:
            meta["anio"] = m.group(0)
    except Exception:
        pass
    return meta


def _resolver(lector, ref):
    """Devuelve el objeto de una referencia indirecta (o el objeto tal cual)."""
    from pypdf.generic import IndirectObject
    try:
        return lector.get_object(ref) if isinstance(ref, IndirectObject) else ref
    except Exception:
        return None


def _paginas_sueltas(lector, datos: bytes = b"", maximo=20000):
    """
    Busca las páginas por TODO el archivo, sin fiarse del árbol /Pages.

    Es la reparación principal: cuando el catálogo o el árbol están dañados, las
    páginas siguen existiendo como objetos sueltos dentro del archivo. Los números
    de objeto se sacan del propio texto del archivo (la tabla de posiciones puede
    estar inservible) y también de la tabla si está bien.
    """
    from pypdf.generic import DictionaryObject, IndirectObject
    numeros = set()
    for m in re.finditer(rb"(?m)^\s*(\d+)\s+(\d+)\s+obj\b", datos[:400 * 1024 * 1024]):
        try:
            numeros.add((int(m.group(1)), int(m.group(2))))
        except Exception:
            continue
        if len(numeros) >= maximo:
            break
    try:
        for n in range(1, min(len(lector.xref), maximo) + 1):
            numeros.add((n, 0))
    except Exception:
        pass

    paginas = []
    for num, gen in sorted(numeros):
        try:
            ref = IndirectObject(num, gen, lector)
            obj = lector.get_object(ref)
        except Exception:
            continue
        if isinstance(obj, DictionaryObject) and obj.get("/Type") == "/Page":
            paginas.append((obj, ref))
    return paginas


def _texto_de_pagina(lector, nodo, ref=None):
    """Texto de una página encontrada a mano (soporta las dos formas de pypdf)."""
    try:
        from pypdf._page import PageObject
    except Exception:
        PageObject = None
    intentos = []
    if PageObject is not None:
        if ref is not None:
            intentos.append(lambda: PageObject(lector, ref))
        intentos.append(lambda: PageObject(lector))
    for crear in intentos:
        try:
            pag = crear()
            pag.update(nodo)
            texto = normalizar_espacios(pag.extract_text() or "")
            if texto:
                return texto
        except Exception:
            continue
    return ""


def _decodificar_cadena_pdf(cruda: str) -> str:
    r"""Convierte una cadena de PDF (con escapes \( \) \\ \ddd) a texto."""
    salida = []
    i = 0
    while i < len(cruda):
        c = cruda[i]
        if c != "\\":
            salida.append(c)
            i += 1
            continue
        i += 1
        if i >= len(cruda):
            break
        e = cruda[i]
        if e in "()\\":
            salida.append(e)
            i += 1
        elif e == "n":
            salida.append("\n")
            i += 1
        elif e == "r":
            salida.append("\r")
            i += 1
        elif e == "t":
            salida.append("\t")
            i += 1
        elif e.isdigit():                      # \ddd  (código octal)
            octal = cruda[i:i + 3]
            j = 0
            while j < len(octal) and octal[j].isdigit() and j < 3:
                j += 1
            try:
                salida.append(chr(int(octal[:j], 8)))
            except Exception:
                pass
            i += j
        elif e == "\n":                        # salto de línea escapado: se ignora
            i += 1
        else:
            salida.append(e)
            i += 1
    return "".join(salida)


_RE_CADENA_TEXTO = re.compile(r"\((?:\\.|[^\\()])*\)\s*(?:Tj|TJ|'|\")")
_RE_HEX_TEXTO = re.compile(r"<([0-9A-Fa-f\s]{2,})>\s*(?:Tj|TJ|'|\")")


def _texto_de_operadores_pdf(crudo: bytes) -> str:
    """Saca el texto legible de un content stream de PDF (Tj / TJ)."""
    try:
        texto = crudo.decode("latin-1")
    except Exception:
        return ""
    if "Tj" not in texto and "TJ" not in texto:
        return ""
    partes = []
    for m in _RE_CADENA_TEXTO.finditer(texto):
        cadena = m.group(0)
        ini = cadena.index("(")
        fin = cadena.rindex(")")
        partes.append(_decodificar_cadena_pdf(cadena[ini + 1:fin]))
    for m in _RE_HEX_TEXTO.finditer(texto):
        hexa = re.sub(r"\s", "", m.group(1))
        if len(hexa) % 2:
            hexa += "0"
        try:
            datos = bytes.fromhex(hexa)
        except Exception:
            continue
        if datos.startswith(b"\xfe\xff"):
            datos = datos[2:]
            partes.append(datos.decode("utf-16-be", errors="replace"))
        else:
            partes.append(datos.decode("latin-1", errors="replace"))
    return " ".join(p for p in partes if p.strip())


def _textos_crudos_de_pdf(datos: bytes, maximo=4000):
    """
    Último recurso: sacar el texto de los content streams del archivo, sin usar
    la estructura del PDF (sirve incluso si el catálogo está destruido).
    """
    trozos = []
    for m in re.finditer(rb"stream\r?\n", datos):
        ini = m.end()
        fin = datos.find(b"endstream", ini)
        if fin == -1 or fin - ini > 40 * 1024 * 1024:
            continue
        crudo = datos[ini:fin]
        plano = None
        if not crudo.lstrip()[:5] == b"BT":
            for intento in (crudo, crudo.strip(b"\r\n")):
                try:
                    plano = zlib.decompress(intento)
                    break
                except Exception:
                    continue
        if plano is None:
            plano = crudo
        texto = _texto_de_operadores_pdf(plano)
        if texto.strip():
            trozos.append(normalizar_espacios(texto))
        if len(trozos) >= maximo:
            break
    return trozos


def extraer_pdf(ruta: str):
    """
    Devuelve (paginas, metadatos, aviso).

    Si el PDF está dañado se intenta reparar por tres caminos antes de darlo por
    perdido, porque el texto suele seguir dentro del archivo (esto es lo que
    pasaba con los PDF que salían con "Invalid object in /Pages").
    """
    try:
        from pypdf import PdfReader
    except ImportError:
        raise ValueError(FALTA_LECTOR_PDF + ": falta el lector de PDF (pypdf); la aplicación lo "
                         "instala sola al abrir, o ejecuta: python -m pip install pypdf")

    _silenciar_pypdf()
    try:
        tamano = os.path.getsize(ruta_io(ruta))
    except OSError:
        tamano = 0
    if tamano == 0:
        if solo_en_la_nube(ruta):
            raise ValueError("está SOLO EN LA NUBE (OneDrive) y Windows no lo tiene descargado: "
                             "haz clic derecho sobre la carpeta en OneDrive → «Mantener siempre en "
                             "este dispositivo» y vuelve a indexar")
        raise ValueError("EmptyFileError: el archivo está vacío (0 bytes) — hay que volver a copiarlo")
    datos = None

    aviso = None
    meta = {}
    paginas = []
    primer_error = None

    # ---------- intento 1: lectura normal ----------
    archivo = None
    try:
        archivo = open(ruta_io(ruta), "rb")
        lector = PdfReader(archivo, strict=False)
        if lector.is_encrypted:
            try:
                lector.decrypt("")
            except Exception:
                raise ValueError("El PDF está cifrado y protegido con contraseña")
        meta = _metadatos_pdf(lector)
        try:
            for i, pag in enumerate(lector.pages, 1):
                try:
                    texto = pag.extract_text() or ""
                except Exception:
                    texto = ""
                # r28-d · PDF escaneado con el texto «letra a letra» (sus Tomos):
                # se vuelve a leer por POSICIONES, que es lo que devuelve los
                # espacios de verdad: «ESTUDIO BIBLICO…» otra vez buscable.
                if esta_letra_a_letra(texto):
                    texto = _arreglar_letra_a_letra(pag, texto)
                paginas.append({"pagina": i, "texto": normalizar_espacios(texto)})
        except Exception as e:
            if not paginas:
                raise
            aviso = (f"PDF con estructura dañada: se guardaron {len(paginas)} página(s) "
                     f"de las que se pudieron leer. Detalle: {e}")
    except Exception as e:
        primer_error = e
        paginas = []
    finally:
        try:
            if archivo is not None:
                archivo.close()          # pypdf lee del archivo, así que se cierra al terminar
        except Exception:
            pass

    # a partir de aquí hace falta el archivo completo en memoria (solo si hay que reparar)
    if not paginas and tamano < 400 * 1024 * 1024:
        try:
            datos = open(ruta_io(ruta), "rb").read()
        except OSError:
            datos = b""

    # ---------- intento 2: buscar las páginas sueltas en el archivo ----------
    if not paginas and datos:
        try:
            lector = PdfReader(io.BytesIO(datos), strict=False)
            if lector.is_encrypted:
                try:
                    lector.decrypt("")
                except Exception:
                    pass
            if not meta:
                meta = _metadatos_pdf(lector)
            sueltas = _paginas_sueltas(lector, datos)
            for i, (nodo, ref) in enumerate(sueltas, 1):
                texto = _texto_de_pagina(lector, nodo, ref)
                if texto:
                    paginas.append({"pagina": i, "texto": texto})
            if paginas:
                detalle = f" ({primer_error})" if primer_error else ""
                aviso = (f"PDF reparado: el índice interno del archivo estaba dañado{detalle} "
                         f"y se leyeron sus {len(paginas)} página(s) buscándolas dentro del "
                         "archivo. El documento entra normal a la biblioteca.")
        except Exception:
            paginas = []

    # ---------- intento 3: sacar el texto de los content streams ----------
    if not paginas and datos:
        trozos = _textos_crudos_de_pdf(datos)
        if trozos:
            for i, t in enumerate(trozos, 1):
                paginas.append({"pagina": i, "texto": t})
            aviso = (f"PDF reparado leyendo el texto directamente del archivo "
                     f"(estructura dañada: {primer_error}). Se recuperaron {len(trozos)} bloque(s) de texto.")

    if not paginas:
        raise ValueError(f"No se pudo leer el PDF (archivo dañado o protegido): {primer_error}")

    total_car = sum(len(p["texto"]) for p in paginas)
    if aviso is None and paginas and total_car < 25 * len(paginas):
        aviso = ("PDF escaneado (imagen): no tiene capa de texto. Se puede ver y archivar, "
                 "pero para buscarlo por contenido necesita OCR.")
    if total_car == 0:
        aviso = ("PDF sin texto legible (probablemente escaneado como imagen): "
                 "queda archivado y se puede abrir, pero no se puede buscar por contenido.")
    return paginas, meta, aviso


# ---------------------------------------------------------------- DOCX / PPTX / XLSX

def _texto_de_xml(raiz, etiqueta_p, etiqueta_t):
    """Recorre párrafos de un XML OOXML y arma el texto."""
    partes = []
    for p in raiz.iter(etiqueta_p):
        trozos = []
        for nodo in p.iter():
            if nodo.tag == etiqueta_t and nodo.text:
                trozos.append(nodo.text)
            elif nodo.tag in (W + "tab", "{http://schemas.openxmlformats.org/drawingml/2006/main}tab"):
                trozos.append(" ")
            elif nodo.tag in (W + "br", "{http://schemas.openxmlformats.org/drawingml/2006/main}br"):
                trozos.append("\n")
        linea = "".join(trozos).strip()
        if linea:
            partes.append(linea)
    return "\n".join(partes)


def extraer_docx(ruta: str):
    from zipfile import ZipFile

    meta = {}
    with ZipFile(ruta_io(ruta)) as z:
        nombres = z.namelist()
        xml = z.read("word/document.xml") if "word/document.xml" in nombres else None
        if xml is None:
            raise ValueError("El archivo no parece un documento Word válido (.docx)")
        try:
            raiz = ET.fromstring(xml)
            texto = _texto_de_xml(raiz, W + "p", W + "t")
        except ET.ParseError:
            # Word "raro" (generado por herramientas antiguas): se saca el texto a mano
            # quitando las etiquetas, así el documento NO se pierde.
            crudo = xml.decode("utf-8", errors="replace")
            crudo = re.sub(r"<w:p[ >]", "\n<w:p ", crudo)
            texto = re.sub(r"<[^>]+>", " ", crudo)
            texto = re.sub(r"[ \t]+", " ", texto)
            texto = "\n".join(l.strip() for l in texto.split("\n") if l.strip())
        # Propiedades del documento
        try:
            if "docProps/core.xml" in nombres:
                c = ET.fromstring(z.read("docProps/core.xml"))
                t = c.findtext(DC + "title")
                a = c.findtext(DC + "creator")
                f = c.findtext(DC + "created") or c.findtext(DC + "modified")
                if t:
                    meta["titulo"] = t.strip()
                if a:
                    meta["autor"] = a.strip()
                if f and len(f) >= 4:
                    meta["anio"] = f[:4]
        except Exception:
            pass

    # Word no guarda "páginas"; se estiman ~3.000 caracteres por página para orientar al usuario
    return _paginar_por_bloques(texto), meta, None


def extraer_pptx(ruta: str):
    P = "{http://schemas.openxmlformats.org/presentationml/2006/main}"
    A = "{http://schemas.openxmlformats.org/drawingml/2006/main}"
    paginas = []
    with zipfile.ZipFile(ruta_io(ruta)) as z:
        diapos = sorted(
            [n for n in z.namelist() if re.match(r"ppt/slides/slide\d+\.xml$", n)],
            key=lambda s: int(re.search(r"(\d+)", s.split("/")[-1]).group(1)),
        )
        for i, n in enumerate(diapos, 1):
            raiz = ET.fromstring(z.read(n))
            textos = [t.text.strip() for t in raiz.iter(A + "t") if t.text and t.text.strip()]
            paginas.append({"pagina": i, "texto": normalizar_espacios("\n".join(textos))})
    return paginas, {}, None


def extraer_xlsx(ruta: str):
    S = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"
    with zipfile.ZipFile(ruta_io(ruta)) as z:
        compartidos = []
        if "xl/sharedStrings.xml" in z.namelist():
            raiz = ET.fromstring(z.read("xl/sharedStrings.xml"))
            for si in raiz.iter(S + "si"):
                compartidos.append("".join(t.text or "" for t in si.iter(S + "t")))
        paginas = []
        hojas = sorted([n for n in z.namelist() if re.match(r"xl/worksheets/sheet\d+\.xml$", n)])
        for i, n in enumerate(hojas, 1):
            raiz = ET.fromstring(z.read(n))
            filas = []
            for fila in raiz.iter(S + "row"):
                valores = []
                for c in fila.iter(S + "c"):
                    v = c.find(S + "v")
                    if c.get("t") == "inlineStr":          # texto escrito dentro de la celda
                        textos = [t.text or "" for t in c.iter(S + "t")]
                        if textos:
                            valores.append("".join(textos))
                        continue
                    if v is None or v.text is None:
                        continue
                    if c.get("t") == "s":                  # índice a la tabla de textos compartidos
                        try:
                            valores.append(compartidos[int(v.text)])
                        except Exception:
                            valores.append(v.text)
                    else:
                        valores.append(v.text)
                if valores:
                    filas.append(" | ".join(valores))
            paginas.append({"pagina": i, "texto": normalizar_espacios("\n".join(filas))})
    return paginas, {}, None


# ---------------------------------------------------------------- ODT

def extraer_odt(ruta: str):
    with zipfile.ZipFile(ruta_io(ruta)) as z:
        raiz = ET.fromstring(z.read("content.xml"))
        lineas = []
        for nodo in raiz.iter():
            if nodo.tag in (ODF_T + "p", ODF_T + "h"):
                txt = "".join(nodo.itertext()).strip()
                if txt:
                    lineas.append(txt)
        texto = "\n".join(lineas)
        meta = {}
        try:
            if "meta.xml" in z.namelist():
                mr = ET.fromstring(z.read("meta.xml"))
                tit = mr.findtext(".//" + ODF_DC + "title")
                aut = mr.findtext(".//" + ODF_DC + "creator")
                if tit:
                    meta["titulo"] = tit.strip()
                if aut:
                    meta["autor"] = aut.strip()
        except Exception:
            pass
    return _paginar_por_bloques(texto), meta, None


# ---------------------------------------------------------------- texto plano / RTF

def texto_legible_de_binario(datos: bytes) -> str:
    r"""
    Saca el TEXTO que se pueda leer de un archivo binario antiguo (WordPerfect).

    Dentro del .wpd el texto va en claro entre códigos de control. Aquí se corta
    por los bytes que no son letra (se cambian por espacios) y se conservan los
    trozos con palabras de verdad: así el usuario lee el documento en vez de la
    basura que salía antes.
    """
    crudo = datos.decode("cp1252", errors="replace")
    # los códigos de control se vuelven espacios (los saltos de línea se respetan)
    crudo = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]", " ", crudo)
    trozos = []
    for linea in crudo.split("\n"):
        limpia = re.sub(r"[^\w\sáéíóúüñÁÉÍÓÚÜÑ¿¡.,;:()\-«»\"'/@%$#*+=&°ºª]{1,}", " ", linea,
                        flags=re.UNICODE)
        limpia = " ".join(limpia.split())
        # se queda con las líneas que parecen texto (varias palabras seguidas)
        if len(limpia) >= 6 and len(re.findall(r"[A-Za-zÁÉÍÓÚÜÑñáéíóúü]{2,}", limpia)) >= 2:
            # fuera las firmas del formato («ÿÿWPC», «WPC», «WP»…): se recortan
            # del principio y se sigue con el texto de verdad
            limpia = re.sub(r"^[ÿ\ufffd]+", "", limpia)
            limpia = re.sub(r"^W[Pp][CcSs]?[\d.]*\s*", "", limpia)
            limpia = re.sub(r"^[\s\d.]+", "", limpia)
            if len(limpia) >= 6 and len(re.findall(r"[A-Za-zÁÉÍÓÚÜÑñáéíóúü]{2,}", limpia)) >= 2:
                trozos.append(limpia)
    return "\n".join(trozos)


def extraer_wpd(ruta: str):
    r"""
    WordPerfect (.wpd/.wps/.wpt). Si el archivo fuera en realidad un PDF (a veces
    los renombran), se lee como PDF. Si no, se saca el texto legible.
    """
    datos = open(ruta_io(ruta), "rb").read()
    if datos[:5] == b"%PDF-":
        return extraer_pdf(ruta)
    texto = texto_legible_de_binario(datos)
    if not texto.strip():
        return [{"pagina": 1, "texto": ""}], {}, ("Este archivo de WordPerfect no tiene texto "
                                                  "que se pueda leer: seguramente sea un escaneo "
                                                  "guardado en ese formato.")
    return _paginar_por_bloques(texto), {}, None


def extraer_texto_plano(ruta: str):
    datos = open(ruta_io(ruta), "rb").read()
    texto = None
    for cod in ("utf-8-sig", "utf-8", "cp1252", "latin-1"):
        try:
            texto = datos.decode(cod)
            break
        except UnicodeDecodeError:
            continue
    if texto is None:
        texto = datos.decode("utf-8", errors="replace")
    # Quita etiquetas si es HTML
    if os.path.splitext(ruta)[1].lower() in (".html", ".htm"):
        texto = re.sub(r"(?s)<(script|style).*?</\1>", " ", texto)
        texto = re.sub(r"(?s)<[^>]+>", " ", texto)
    return _paginar_por_bloques(normalizar_espacios(texto)), {}, None


def extraer_rtf(ruta: str):
    crudo = open(ruta_io(ruta), "rb").read().decode("latin-1", errors="replace")
    # Deshace el escape \'hh (acentos en Windows-1252)
    crudo = re.sub(r"\\'([0-9a-fA-F]{2})", lambda m: bytes([int(m.group(1), 16)]).decode("cp1252", "replace"), crudo)
    crudo = re.sub(r"\\u(-?\d+)\??", lambda m: chr(int(m.group(1)) % 65536), crudo)
    crudo = re.sub(r"\\par[d]?", "\n", crudo)
    crudo = re.sub(r"\\tab", "\t", crudo)
    crudo = re.sub(r"\\\{|\\\}|\\\\", " ", crudo)
    crudo = re.sub(r"\\[a-zA-Z]+-?\d* ?", "", crudo)   # grupos de control restantes
    crudo = crudo.replace("{", " ").replace("}", " ")
    return _paginar_por_bloques(normalizar_espacios(crudo)), {}, None


# ---------------------------------------------------------------- DOC antiguo

def _buscador_ejecutable(nombres):
    for n in nombres:
        ruta = shutil.which(n)
        if ruta:
            return ruta
    return None


def extraer_doc_antiguo(ruta: str):
    """Word 97-2003 (.doc): formato binario. Se intenta convertir con LibreOffice."""
    soffice = _buscador_ejecutable(["soffice", "libreoffice", "soffice.exe"])
    if soffice:
        with tempfile.TemporaryDirectory() as tmp:
            subprocess.run(
                [soffice, "--headless", "--convert-to", "txt:Text (encoded):UTF8", "--outdir", tmp, ruta],
                check=True, capture_output=True, timeout=180,
            )
            salida = os.path.join(tmp, os.path.splitext(os.path.basename(ruta))[0] + ".txt")
            if os.path.exists(salida):
                paginas, meta, _ = extraer_texto_plano(salida)
                return paginas, meta, "Documento .doc convertido automáticamente con LibreOffice."

    antiword = _buscador_ejecutable(["antiword", "antiword.exe"])
    if antiword:
        r = subprocess.run([antiword, ruta], capture_output=True, timeout=120)
        if r.returncode == 0 and r.stdout:
            texto = r.stdout.decode("utf-8", errors="replace")
            return _paginar_por_bloques(normalizar_espacios(texto)), {}, "Documento .doc leído con antiword."

    raise ValueError(
        "Formato Word antiguo (.doc). No se pudo leer el contenido. "
        "Solución: ábrelo en Word y guárdalo como .docx (Archivo > Guardar como), "
        "o instala LibreOffice para conversión automática."
    )


# ---------------------------------------------------------------- paginado auxiliar

def _paginar_por_bloques(texto: str, tamano: int = 3000):
    """Para formatos sin páginas reales (Word, texto): divide en bloques de ~3000 caracteres."""
    texto = normalizar_espacios(texto)
    if not texto:
        return [{"pagina": 1, "texto": ""}]
    paginas = []
    lineas = texto.split("\n")
    buf, n = [], 0
    for ln in lineas:
        buf.append(ln)
        n += len(ln) + 1
        if n >= tamano:
            paginas.append({"pagina": len(paginas) + 1, "texto": "\n".join(buf)})
            buf, n = [], 0
    if buf:
        paginas.append({"pagina": len(paginas) + 1, "texto": "\n".join(buf)})
    return paginas


# ---------------------------------------------------------------- fachada

def extraer(ruta: str):
    """
    Extrae el contenido de cualquier archivo soportado.
    Devuelve dict: {paginas, titulo, autor, anio, aviso}
    """
    ext = os.path.splitext(ruta)[1].lower()
    if ext in EXT_PDF:
        paginas, meta, aviso = extraer_pdf(ruta)
    elif ext in EXT_DOCX:
        paginas, meta, aviso = extraer_docx(ruta)
    elif ext in EXT_DOC:
        paginas, meta, aviso = extraer_doc_antiguo(ruta)
    elif ext in EXT_ODT:
        paginas, meta, aviso = extraer_odt(ruta)
    elif ext in EXT_PPTX:
        paginas, meta, aviso = extraer_pptx(ruta)
    elif ext in EXT_XLSX:
        paginas, meta, aviso = extraer_xlsx(ruta)
    elif ext in EXT_RTF:
        paginas, meta, aviso = extraer_rtf(ruta)
    elif ext in EXT_TXT:
        paginas, meta, aviso = extraer_texto_plano(ruta)
    elif ext in EXT_WPD:
        paginas, meta, aviso = extraer_wpd(ruta)
    else:
        raise ValueError(f"Extensión no soportada: {ext}")

    total = sum(len(p["texto"]) for p in paginas)
    return {
        "paginas": paginas,
        "encabezado": encabezado_de(paginas),        # r28-d · el título de arriba del PDF
        "titulo": meta.get("titulo"),
        "autor": meta.get("autor"),
        "anio": meta.get("anio"),
        "aviso": aviso,
        "caracteres": total,
    }


def palabras_creibles(texto: str, maximo: int = 26) -> bool:
    """
    ¿Este texto arreglado tiene palabras de verdad? Se usa para no cambiar un
    problema por otro: si al juntar letras queda un «chorizo» sin espacios
    («ESTUDIOBIBLICOSOBRELAVICTORIA»), eso NO es mejor que lo que había.
    """
    if not texto:
        return False
    for linea in texto.split("\n"):
        for palabra in linea.split():
            if len(palabra) > maximo:
                return False
    return True


def _arreglar_letra_a_letra(pagina, texto_normal: str) -> str:
    """
    Cuando la página viene «letra a letra», se prueban dos formas de arreglarla y
    se devuelve la primera que quede bien:
        1) por las POSICIONES reales de cada letra (la buena),
        2) releyendo la página en modo «layout» y juntando por el tamaño del hueco.
    Si ninguna lo arregla, se devuelve lo que había (nunca se empeora).
    """
    try:
        por_posiciones = texto_por_posiciones(pagina)
        if (por_posiciones and not esta_letra_a_letra(por_posiciones)
                and palabras_creibles(por_posiciones)):
            return por_posiciones
    except Exception:
        pass
    try:
        con_huecos = pagina.extract_text(extraction_mode="layout") or ""
        arreglado = reconstruir_palabras(con_huecos)
        if (arreglado and not esta_letra_a_letra(arreglado)
                and palabras_creibles(arreglado) and " " in arreglado.strip()):
            return arreglado
    except Exception:
        pass
    return texto_normal


def texto_de_pagina(ruta: str, pagina: int) -> str:
    """
    Lee, AQUÍ Y AHORA, el texto de una página concreta de un PDF.

    Es para cuando el usuario abre el texto de una página y sale vacío: en vez de
    decirle «no hay nada», se lo leemos del PDF en el momento (y el indexador lo
    guardará para la próxima). Devuelve "" si esa página no tiene texto (escaneo).
    """
    ext = os.path.splitext(ruta)[1].lower()
    try:
        if ext in EXT_PDF:
            from pypdf import PdfReader
            _silenciar_pypdf()
            with open(ruta_io(ruta), "rb") as fh:
                lector = PdfReader(fh, strict=False)
                if lector.is_encrypted:
                    try:
                        lector.decrypt("")
                    except Exception:
                        return ""
                if not (1 <= int(pagina) <= len(lector.pages)):
                    return ""
                pag_obj = lector.pages[int(pagina) - 1]
                texto = pag_obj.extract_text() or ""
                if esta_letra_a_letra(texto):
                    texto = _arreglar_letra_a_letra(pag_obj, texto)
                return normalizar_espacios(texto)
        # otros formatos: se extrae entero y se devuelve «la página» que haya
        datos = extraer(ruta)
        for p in datos.get("paginas") or []:
            if int(p.get("pagina") or 0) == int(pagina):
                return p.get("texto") or ""
        paginas = datos.get("paginas") or []
        if paginas and int(pagina) <= len(paginas):
            return paginas[int(pagina) - 1].get("texto") or ""
    except Exception:
        return ""
    return ""


def titulo_aparente(paginas, nombre_archivo: str) -> str:
    """Toma como título la primera línea 'decente' del documento."""
    for p in paginas[:2]:
        for linea in p["texto"].split("\n"):
            ln = linea.strip()
            if 6 <= len(ln) <= 120 and not ln.lower().startswith(("página", "page", "http")):
                return ln
    return os.path.splitext(nombre_archivo)[0].replace("_", " ").replace("-", " ").title()



