# ================================================================================

"""
Trabajador de indexación.

Cada archivo se lee en un PROCESO aparte para aprovechar todos los núcleos del
procesador (varios PDF/Word a la vez). Ese es el cambio que hace que una
biblioteca de 3.000 documentos pase de horas a minutos.

Este módulo NO abre la base de datos ni el servidor: solo lee el archivo y
devuelve el texto para que el proceso principal lo guarde.
"""


import hashlib
import os



def md5_archivo(ruta: str, bloque: int = 1 << 20) -> str:
    h = hashlib.md5()
    with open(ruta, "rb") as f:
        while True:
            datos = f.read(bloque)
            if not datos:
                break
            h.update(datos)
    return h.hexdigest()


def preparar_archivo(tarea):
    """
    Lee UN archivo y devuelve su contenido.

    tarea = (ruta, calcular_md5)

    Devuelve un diccionario sencillo (se puede enviar entre procesos):
      {"ruta", "ok": True, "paginas", "titulo", "autor", "anio", "aviso",
       "caracteres", "paginas_total", "tamano", "modificado", "md5"}
    o
      {"ruta", "ok": False, "error": "…", "tamano", "modificado"}
    """
    ruta, calcular_md5 = tarea
    salida = {"ruta": ruta, "ok": False, "error": "", "tamano": 0, "modificado": 0,
              "md5": "", "caracteres": 0, "paginas": []}
    try:
        st = os.stat(ruta)
        salida["tamano"] = st.st_size
        salida["modificado"] = st.st_mtime
    except OSError as e:
        salida["error"] = f"No se pudo leer el archivo ({e})"
        return salida

    try:
        datos = extraer(ruta)
    except Exception as e:
        salida["error"] = f"{type(e).__name__}: {e}".strip()
        return salida

    salida.update({
        "ok": True,
        "paginas": datos["paginas"],
        "paginas_total": len(datos["paginas"]),
        "titulo": datos.get("titulo"),
        "autor": datos.get("autor"),
        "anio": datos.get("anio"),
        "aviso": datos.get("aviso"),
        "caracteres": datos.get("caracteres", 0),
    })
    if calcular_md5:
        try:
            salida["md5"] = md5_archivo(ruta)
        except Exception:
            salida["md5"] = ""
    return salida



