# ================================================================================

"""
Rescate de la biblioteca: buscar la biblioteca ANTERIOR (índice y carpetas) cuando
se abre una copia nueva de la aplicación, y copiar los ajustes/índice de vuelta.

Qué problema resuelve: si la aplicación se abre desde OTRA carpeta (por ejemplo
al descargar de nuevo el archivo, o desde el ZIP), crea su propia carpeta `datos`
vacía: la biblioteca se ve vacía y parece que "se borró todo". En realidad todo
sigue en la carpeta `datos` de la copia anterior; aquí la buscamos y la traemos.
"""
import json
import os
import shutil
import sqlite3
import time

NOMBRES = ("bibliotecadigital", "biblioteca digital", "bibliotecadigital_windows")


def ruta_marca(casa: str = "") -> str:
    """Archivo (en la carpeta personal del usuario) que recuerda la última biblioteca."""
    casa = casa or os.path.expanduser("~")
    return os.path.join(casa, ".biblioteca_digital_ultima.json")


def marca_guardar(datos: str, documentos: int, carpetas=None, casa: str = "") -> str:
    """
    Deja apuntada, en la carpeta personal del usuario, cuál es la biblioteca que
    se está usando. Así, si mañana se abre OTRA copia de la aplicación (en otra
    carpeta), esa copia lee esta nota y sabe dónde están los documentos.
    """
    ruta = ruta_marca(casa)
    try:
        info = {"datos": os.path.abspath(datos), "documentos": int(documentos or 0),
                "carpetas": list(carpetas or []), "cuando": time.strftime("%d/%m/%Y %H:%M")}
        with open(ruta, "w", encoding="utf-8") as f:
            json.dump(info, f, ensure_ascii=False, indent=2)
        return ruta
    except OSError:
        return ""


def marca_leer(casa: str = "") -> dict:
    """Lee la nota de la última biblioteca usada ({} si no hay o no se puede leer)."""
    try:
        with open(ruta_marca(casa), encoding="utf-8") as f:
            d = json.load(f)
        if d.get("datos") and os.path.isdir(d["datos"]):
            return d
    except Exception:
        pass
    return {}


def resumen_de(datos: str) -> dict:
    """Lee (sin tocar el índice) qué hay en una carpeta `datos`."""
    db = os.path.join(datos, "biblioteca.db")
    aj = os.path.join(datos, "ajustes.json")
    info = {"datos": os.path.abspath(datos), "documentos": 0, "carpetas": [],
            "tamano": 0, "ultima": "", "tiene_db": False, "tiene_ajustes": False,
            "modificado": ""}
    if os.path.exists(db):
        info["tiene_db"] = True
        try:
            info["tamano"] = os.path.getsize(db)
            info["modificado"] = time.strftime("%d/%m/%Y %H:%M",
                                               time.localtime(os.path.getmtime(db)))
        except OSError:
            pass
        try:
            con = sqlite3.connect(f"file:{db}?mode=ro", uri=True, timeout=5)
            try:
                info["documentos"] = con.execute("SELECT COUNT(*) FROM documentos").fetchone()[0] or 0
                fila = con.execute("SELECT MAX(indexado) FROM documentos").fetchone()
                info["ultima"] = (fila[0] if fila and fila[0] else "")
                info["con_texto"] = con.execute(
                    "SELECT COUNT(*) FROM documentos WHERE estado='ok'").fetchone()[0] or 0
            finally:
                con.close()
        except Exception as e:
            info["error"] = str(e)[:120]
    if os.path.exists(aj):
        info["tiene_ajustes"] = True
        try:
            with open(aj, encoding="utf-8") as f:
                a = json.load(f)
            info["carpetas"] = [c for c in (a.get("carpetas") or []) if c]
            info["nombre"] = a.get("nombre_biblioteca") or ""
        except Exception:
            pass
    return info


def _carpetas_candidatas(raiz_app: str):
    """Lugares donde puede estar la biblioteca anterior."""
    raiz_app = os.path.abspath(raiz_app)
    casa = os.path.expanduser("~")
    candidatas = []

    def agregar(ruta):
        if ruta and ruta not in candidatas:
            candidatas.append(ruta)

    # la propia carpeta de la aplicación y sus carpetas madres
    actual = raiz_app
    for _ in range(4):
        agregar(actual)
        padre = os.path.dirname(actual)
        if padre == actual:
            break
        actual = padre
    # carpetas típicas del usuario
    for nombre in ("Desktop", "Escritorio", "Documents", "Documentos", "Downloads",
                   "Descargas", "OneDrive", "OneDrive/Documents", "OneDrive/Documentos"):
        agregar(os.path.join(casa, nombre))
    # unidades y carpetas conocidas
    if os.name == "nt":
        letras = "CDEFGHIJKLMNOPQRSTUVWXYZ"
    else:
        letras = ""
    for letra in letras:
        raiz = f"{letra}:\\"
        if os.path.exists(raiz):
            agregar(raiz)
            agregar(os.path.join(raiz, "BibliotecaDigital"))
    agregar(os.path.join(casa, "BibliotecaDigital"))

    # dentro de esos lugares, cualquier carpeta cuyo nombre parezca la aplicación
    for base in list(candidatas):
        try:
            with os.scandir(base) as it:
                for e in it:
                    try:
                        nombre = e.name.lower()
                        if not e.is_dir(follow_symlinks=False):
                            continue
                        if any(n in nombre for n in NOMBRES) or "bibliotec" in nombre:
                            agregar(e.path)
                            for nombre2 in ("datos",):
                                agregar(os.path.join(e.path, nombre2))
                    except OSError:
                        continue
        except OSError:
            continue
    return candidatas


def bibliotecas_anteriores(raiz_app: str, datos_actual: str):
    """
    Busca bibliotecas anteriores: devuelve las que tienen índice o carpetas
    guardadas, ordenadas por cantidad de documentos (las más grandes primero).
    """
    datos_actual = os.path.normcase(os.path.abspath(datos_actual))
    encontradas, vistos = [], set()
    lugares = list(_carpetas_candidatas(raiz_app))
    # también la propia carpeta de datos (por si se llama distinto)
    lugares.append(os.path.join(raiz_app, "datos"))
    lugares.append(os.path.join(os.path.dirname(raiz_app), "datos"))
    # y, si existe, la última biblioteca usada en este equipo (nota del usuario)
    apuntada = (marca_leer().get("datos") or "")
    if apuntada:
        lugares.append(apuntada)
        lugares.append(os.path.dirname(apuntada))
    for lugar in lugares:
        for datos in (lugar, os.path.join(lugar, "datos")):
            clave = os.path.normcase(os.path.abspath(datos))
            if clave in vistos or clave == datos_actual:
                continue
            if not (os.path.exists(os.path.join(datos, "biblioteca.db"))
                    or os.path.exists(os.path.join(datos, "ajustes.json"))):
                continue
            vistos.add(clave)
            info = resumen_de(datos)
            if info["documentos"] or info["carpetas"]:
                info["es_actual"] = False
                encontradas.append(info)
    encontradas.sort(key=lambda x: (-x["documentos"], x["datos"]))
    return encontradas[:12]


def _cuantos(ruta_db: str) -> int:
    """Cuántos documentos tiene un índice (-1 si no se puede leer)."""
    try:
        con = sqlite3.connect(f"file:{ruta_db}?mode=ro", uri=True, timeout=10)
        try:
            return con.execute("SELECT COUNT(*) FROM documentos").fetchone()[0] or 0
        finally:
            con.close()
    except Exception:
        return -1


def _copiar_indice(origen: str, destino: str) -> bool:
    """
    Copia CONSISTENTE del índice con la herramienta propia de SQLite (así entra
    lo que quedó en el archivo -wal). Se copia primero a un archivo temporal y
    solo al final se reemplaza, para que la biblioteca actual nunca quede a
    medias. IMPORTANTE: la aplicación debe tener su índice cerrado antes.
    """
    temporal = destino + ".nuevo"
    hecho = False
    try:
        con_o = sqlite3.connect(f"file:{origen}?mode=ro", uri=True, timeout=20)
        con_d = sqlite3.connect(temporal)
        try:
            con_o.backup(con_d)
            hecho = True
        finally:
            con_d.close()
            con_o.close()
    except Exception:
        hecho = False
    if not hecho:
        try:
            shutil.copy2(origen, temporal)
            hecho = True
        except OSError:
            hecho = False
    if not hecho:
        return False
    try:
        os.replace(temporal, destino)
    except OSError:
        return False
    # restos de la biblioteca que había antes (ya no hay conexión abierta)
    for sufijo in ("-wal", "-shm"):
        resto = destino + sufijo
        if os.path.exists(resto):
            try:
                os.remove(resto)
            except OSError:
                pass
    return True


def adoptar(datos_origen: str, datos_destino: str, respaldo_destino: str = ""):
    """
    Trae a la biblioteca actual el índice y las carpetas de la biblioteca anterior.

    Antes de reemplazar nada guarda una copia de la biblioteca actual, para no
    perder nada. Devuelve un resumen de lo que se copió.
    """
    datos_origen = os.path.abspath(datos_origen)
    datos_destino = os.path.abspath(datos_destino)
    hecho = {"indice": False, "carpetas": [], "documentos": 0, "respaldo": "",
             "origen": datos_origen}
    os.makedirs(datos_destino, exist_ok=True)
    os.makedirs(respaldo_destino or os.path.join(datos_destino, "copias"), exist_ok=True)

    destino_db = os.path.join(datos_destino, "biblioteca.db")
    origen_db = os.path.join(datos_origen, "biblioteca.db")
    if os.path.exists(destino_db) and _cuantos(destino_db) > 0:
        antes = os.path.join(respaldo_destino or os.path.join(datos_destino, "copias"),
                             f"antes-de-recuperar-{time.strftime('%Y%m%d-%H%M%S')}.db")
        if _copiar_indice(destino_db, antes):
            hecho["respaldo"] = antes
    if os.path.exists(origen_db):
        hecho["indice"] = _copiar_indice(origen_db, destino_db)
        hecho["documentos"] = resumen_de(datos_origen)["documentos"]

    origen_aj = os.path.join(datos_origen, "ajustes.json")
    # no se acumulan copias de «antes de recuperar»: se conservan las 3 últimas
    carpeta_respaldos = respaldo_destino or os.path.join(datos_destino, "copias")
    try:
        antes = sorted([f for f in os.listdir(carpeta_respaldos) if f.startswith("antes-de-recuperar-")],
                       reverse=True)
        for viejo in antes[3:]:
            os.remove(os.path.join(carpeta_respaldos, viejo))
    except OSError:
        pass

    if os.path.exists(origen_aj):
        try:
            with open(origen_aj, encoding="utf-8") as f:
                a = json.load(f)
            hecho["carpetas"] = [c for c in (a.get("carpetas") or []) if c]
            hecho["ajustes"] = {k: v for k, v in a.items() if k != "carpetas"}
        except Exception:
            pass
    return hecho



