"""
Capa de datos: SQLite con búsqueda de texto completo (FTS5).

- Tabla `documentos`  : ficha de cada archivo (ruta, título, autor, categoría, etiquetas...)
- Tabla `fragmentos`  : índice FTS5 con el texto página por página

FTS5 con `unicode61 remove_diacritics 2` => busca "informacion" y encuentra
"información"; "Busqueda" encuentra "búsqueda". Todo local, sin internet.
"""


import datetime as _dt
import json
import os
import re
import shutil
import sqlite3
import threading

ESQUEMA = """
CREATE TABLE IF NOT EXISTS documentos (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    ruta        TEXT NOT NULL UNIQUE,
    carpeta     TEXT DEFAULT '',
    nombre      TEXT NOT NULL,
    extension   TEXT DEFAULT '',
    tipo        TEXT DEFAULT '',
    tamano      INTEGER DEFAULT 0,
    modificado  REAL DEFAULT 0,
    md5         TEXT DEFAULT '',
    titulo      TEXT DEFAULT '',
    autor       TEXT DEFAULT '',
    categoria   TEXT DEFAULT '',
    carpeta1    TEXT DEFAULT '',
    etiquetas   TEXT DEFAULT '',
    anio        TEXT DEFAULT '',
    paginas     INTEGER DEFAULT 0,
    caracteres  INTEGER DEFAULT 0,
    estado      TEXT DEFAULT 'pendiente',
    nota        TEXT DEFAULT '',
    favorito    INTEGER DEFAULT 0,
    categoria_manual INTEGER DEFAULT 0,
    agregado    TEXT DEFAULT '',
    indexado    TEXT DEFAULT ''
);

CREATE VIRTUAL TABLE IF NOT EXISTS fragmentos USING fts5(
    texto,
    doc_id UNINDEXED,
    pagina UNINDEXED,
    tokenize = 'unicode61 remove_diacritics 2'
);

CREATE TABLE IF NOT EXISTS historial (
    id      INTEGER PRIMARY KEY AUTOINCREMENT,
    cuando  TEXT,
    texto   TEXT,
    n       INTEGER DEFAULT 0
);
"""

# Los ÍNDICES van APARTE y se crean DESPUÉS de asegurar las columnas: si no, al
# abrir una base de datos creada por una versión anterior (sin la columna
# carpeta1) fallaba con «no such column: carpeta1» y la aplicación no arrancaba.
ESQUEMA_INDICES = [
    "CREATE INDEX IF NOT EXISTS idx_doc_categoria ON documentos(categoria)",
    "CREATE INDEX IF NOT EXISTS idx_doc_carpeta1 ON documentos(carpeta1)",
    "CREATE INDEX IF NOT EXISTS idx_doc_tipo ON documentos(tipo)",
    "CREATE INDEX IF NOT EXISTS idx_doc_md5 ON documentos(md5)",
]

# Todas las columnas que debe tener la tabla, con su definición. Al abrir una
# base vieja se agregan las que falten (una por una) antes de crear los índices.
COLUMNAS_DOCUMENTOS = (
    ("carpeta", "TEXT DEFAULT ''"),
    ("nombre", "TEXT DEFAULT ''"),
    ("extension", "TEXT DEFAULT ''"),
    ("tipo", "TEXT DEFAULT ''"),
    ("tamano", "INTEGER DEFAULT 0"),
    ("modificado", "REAL DEFAULT 0"),
    ("md5", "TEXT DEFAULT ''"),
    ("titulo", "TEXT DEFAULT ''"),
    ("encabezado", "TEXT DEFAULT ''"),        # r28-d · el título que trae el PDF arriba
    ("autor", "TEXT DEFAULT ''"),
    ("categoria", "TEXT DEFAULT ''"),
    ("carpeta1", "TEXT DEFAULT ''"),
    ("etiquetas", "TEXT DEFAULT ''"),
    ("anio", "TEXT DEFAULT ''"),
    ("paginas", "INTEGER DEFAULT 0"),
    ("caracteres", "INTEGER DEFAULT 0"),
    ("estado", "TEXT DEFAULT 'pendiente'"),
    ("nota", "TEXT DEFAULT ''"),
    ("favorito", "INTEGER DEFAULT 0"),
    ("categoria_manual", "INTEGER DEFAULT 0"),
    ("agregado", "TEXT DEFAULT ''"),
    ("indexado", "TEXT DEFAULT ''"),
)

MARCA_INI = "\x01"
MARCA_FIN = "\x02"


def texto_para_like(consulta: str) -> str:
    """
    Deja la consulta en texto pelado (sin comillas, asteriscos ni OR/AND/NOT),
    para poder buscar con LIKE en el título cuando no da tiempo a más.
    """
    limpio = re.sub(r'[",()]', " ", str(consulta))
    limpio = limpio.replace("*", "")
    limpio = re.sub(r"\b(OR|AND|NOT)\b", " ", limpio, flags=re.IGNORECASE)
    return re.sub(r"\s+", " ", limpio).strip()[:80]


def ahora() -> str:
    return _dt.datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def groups_ordenados(grupos, orden):
    """Devuelve {doc_id: {"paginas": [...]}} respetando el orden de `orden`."""
    salida = {}
    for doc_id in orden:
        salida[doc_id] = {"paginas": grupos.get(doc_id, [])}
    return salida


def sin_acentos(texto: str) -> str:
    """Texto en minúsculas, sin acentos y con los espacios de más quitados.
    Se usa para comparar lo que escribe el usuario con lo que dice el documento."""
    t = str(texto or "").lower()
    for acentos, plano in (("áàäâã", "a"), ("éèëê", "e"), ("íìïî", "i"),
                           ("óòöôõ", "o"), ("úùüû", "u"), ("ñ", "n"), ("ç", "c")):
        for ch in acentos:
            t = t.replace(ch, plano)
    return re.sub(r"\s+", " ", t).strip()


class Almacen:
    def cerrar(self):
        """Cierra el índice (se usa antes de reemplazarlo por otro archivo)."""
        try:
            self.con.commit()
        except Exception:
            pass
        try:
            self.con.close()
        except Exception:
            pass

    def __init__(self, ruta_db: str):
        self.ruta = ruta_db
        os.makedirs(os.path.dirname(os.path.abspath(ruta_db)), exist_ok=True)
        self._lock = threading.RLock()
        self.con = sqlite3.connect(ruta_db, check_same_thread=False, timeout=30)
        self.con.row_factory = sqlite3.Row
        self.con.execute("PRAGMA journal_mode=WAL")
        self.con.execute("PRAGMA synchronous=NORMAL")
        # Lecturas rápidas con bibliotecas grandes (esto se nota sobre todo la
        # primera vez, cuando el archivo todavía no está en la memoria del
        # sistema, y cuando la aplicación está indexando a la vez):
        for _p in ("PRAGMA cache_size=-80000",          # 80 MB de caché
                   "PRAGMA mmap_size=1073741824",       # 1 GB en memoria asignada
                   "PRAGMA temp_store=MEMORY",
                   "PRAGMA busy_timeout=60000"):
            try:
                self.con.execute(_p)
            except Exception:
                pass
        with self._lock:
            # 1) las TABLAS (CREATE TABLE IF NOT EXISTS, no toca lo que ya hay)
            self.con.executescript(ESQUEMA)
            # 2) las COLUMNAS que falten (bases de datos de versiones anteriores)
            agregadas = self._migrar()
            # 3) y por último los ÍNDICES, ya con todas las columnas en su sitio
            for sentencia in ESQUEMA_INDICES:
                try:
                    self.con.execute(sentencia)
                except sqlite3.OperationalError as e:
                    print(f"  ⚠ No se pudo crear un índice ({e}); la búsqueda funciona igual.")
            self.con.commit()
            if agregadas:
                print(f"  ✔ Base de datos al día: se agregaron {agregadas} columna(s) nueva(s) "
                      f"a su biblioteca (no hay que reindexar nada).")

    def _migrar(self) -> int:
        """
        Agrega a la base de datos las COLUMNAS nuevas de esta versión.

        Es lo que permite abrir una biblioteca creada con una versión anterior sin
        reindexar nada. Devuelve cuántas columnas se agregaron (0 = ya estaba al día).
        """
        existentes = {f["name"] for f in self.con.execute("PRAGMA table_info(documentos)")}
        if not existentes:
            return 0                     # la tabla acaba de crearse: ya nace completa
        faltan = [(n, d) for n, d in COLUMNAS_DOCUMENTOS if n not in existentes]
        if faltan:
            # Copia de seguridad UNA vez, antes de tocar la base del usuario
            try:
                respaldo = f"{self.ruta}.antes-de-actualizar"
                if not os.path.exists(respaldo):
                    shutil.copy2(self.ruta, respaldo)
                    print(f"  📦 Copia de seguridad de la base: {respaldo}")
            except Exception as e:
                print(f"  ⚠ No se pudo hacer la copia de seguridad: {e}")
        for nombre, definicion in faltan:
            self.con.execute(f"ALTER TABLE documentos ADD COLUMN {nombre} {definicion}")
        return len(faltan)

    # ------------------------------------------------------------- helpers
    # ------------------------------------------- la CARPETA PRINCIPAL (carpeta1)
    @staticmethod
    def _partes(ruta: str):
        """Trocea una ruta de Windows o de Linux sin depender del sistema operativo."""
        t = (ruta or "").replace("\\", "/").replace("//", "/")
        return [p for p in t.split("/") if p not in ("", ".")]

    @classmethod
    def carpeta_madre(cls, raices) -> str:
        r"""
        La carpeta que CONTIENE a todas las carpetas de la biblioteca: la raíz.

        Es la que manda para las casillas de arriba: si la biblioteca es
        ...\BibliotecaDigital\Estudios (una sola carpeta) o si el usuario eligió
        muchas subcarpetas suyas (...\Estudios\WSS\Aras, ...\Estudios\ENZ\Bib…),
        la raíz es la MISMA (…\Estudios) y las casillas son las 3 fuentes:
        WSS · ENZ · WMB.

        (Si las carpetas son de discos distintos, no hay raíz común: se
        devuelve "" y cada carpeta elegida es su propia casilla.)
        """
        limpias = []
        for r in (raices or []):
            r = os.path.normpath(os.path.abspath(os.path.expanduser(str(r))))
            if r and r not in limpias:
                limpias.append(r)
        if not limpias:
            return ""
        if len(limpias) == 1:
            return limpias[0]
        try:
            comun = os.path.normpath(os.path.commonpath(limpias))
        except ValueError:
            return ""
        return "" if comun in ("", os.sep) else comun

    @staticmethod
    def _ruta_de_partes(partes) -> str:
        """
        Vuelve de los trozos a una ruta de verdad, conservando si es absoluta:
        ['C:','BibliotecaDigital','Estudios']  ->  C:/BibliotecaDigital/Estudios
        ['tmp','x']                            ->  /tmp/x   (en Linux)
        """
        if not partes:
            return ""
        if partes[0].endswith(":"):                      # unidad de Windows
            return partes[0] + os.sep + os.sep.join(partes[1:])
        if partes[0].startswith(os.sep):
            return os.sep.join(partes)
        return os.sep + os.sep.join(partes)              # ruta absoluta de Linux

    def _filas_de_rutas(self, excluir=()):
        """Las rutas de los documentos, sin los que están dentro de «excluir»
        (las carpetas de EJEMPLO de la propia aplicación: no son su biblioteca)."""
        filas = self.todos("SELECT ruta FROM documentos")
        if not excluir:
            return filas
        fuera = [os.path.normcase(os.path.abspath(str(x))) for x in excluir if x]
        salida = []
        for f in filas:
            r = os.path.normcase(os.path.abspath(str(f["ruta"] or "")))
            if any(r == x or r.startswith(x + os.sep) for x in fuera):
                continue
            salida.append(f)
        return salida

    def _conteo_primer_nivel(self, raiz, excluir=()) -> dict:
        """carpeta de primer nivel dentro de «raiz» -> cuántos documentos tiene."""
        partes_raiz = self._partes(raiz)
        cuenta = {}
        for f in self._filas_de_rutas(excluir):
            partes = self._partes(os.path.dirname(os.path.abspath(str(f["ruta"]))))
            if len(partes) <= len(partes_raiz):
                continue
            if [p.lower() for p in partes[:len(partes_raiz)]] != [p.lower() for p in partes_raiz]:
                continue
            clave = self._ruta_de_partes(partes[:len(partes_raiz) + 1])
            cuenta[clave] = cuenta.get(clave, 0) + 1
        return cuenta

    def _subir_la_raiz(self, raiz, excluir=(), vueltas=3) -> str:
        r"""
        Si la raíz averiguada tiene UNA SOLA carpeta de primer nivel con
        documentos, pero su carpeta MADRE sí tiene varias, la raíz sube a la
        madre: es la carpeta que contiene sus fuentes de verdad.

        Caso real: C:\BibliotecaDigital\Estudios\DR WSS\… (casi todos los PDF)
        junto a ENZ\… y WMB\…  →  la raíz tiene que ser «Estudios» y las
        casillas «DR WSS · ENZ · WMB», no «DR WSS» sola.
        """
        for _ in range(max(0, int(vueltas))):
            if not raiz:
                return raiz
            if len(self._conteo_primer_nivel(raiz, excluir)) >= 2:
                return raiz
            madre = os.path.dirname(os.path.normpath(raiz))
            if not madre or madre == raiz or not self._partes(madre):
                return raiz
            madre = madre.rstrip("\\/")
            if len(self._conteo_primer_nivel(madre, excluir)) < 2:
                return raiz
            raiz = madre
        return raiz

    def raiz_por_documentos(self, minimo=0.9, profundidad_minima=2, excluir=()) -> str:
        r"""
        La RAÍZ de la biblioteca, averiguada por los DOCUMENTOS, no por la lista
        de carpetas de Ajustes (que puede tener carpetas de más o de sistema).

        Es la carpeta MÁS PROFUNDA que contiene al menos «minimo» (90 %) de los
        documentos indexados. Ejemplo: 21.199 documentos en
        C:\BibliotecaDigital\Estudios\WSS\…  ·  ENZ\…  ·  WMB\…
        devuelve  C:\BibliotecaDigital\Estudios  (y de ahí salen las 3 fuentes).

        Si la biblioteca tiene documentos en sitios distintos que no comparten
        una carpeta, devuelve "" y se usa el método de siempre.
        """
        try:
            filas = self._filas_de_rutas(excluir)
        except Exception:
            return ""
        total = len(filas)
        if total < 5:
            return ""
        cuenta = {}
        for f in filas:
            partes = self._partes(os.path.dirname(os.path.abspath(str(f["ruta"]))))
            for i in range(max(2, profundidad_minima), len(partes) + 1):
                clave = self._ruta_de_partes(partes[:i])
                cuenta[clave] = cuenta.get(clave, 0) + 1
        minimo_n = int(total * float(minimo)) + 1
        candidatos = [c for c, n in cuenta.items() if n >= minimo_n]
        if not candidatos:
            return ""
        mejor = max(candidatos, key=lambda c: (len(self._partes(c)), len(c)))
        if len(self._partes(mejor)) < profundidad_minima:
            return ""
        # y si quedó una raíz con UNA sola fuente, sube a la carpeta madre
        return self._subir_la_raiz(mejor, excluir)

    def fuentes_de(self, raiz=None, excluir=(), con_disco=False, limite=12) -> list:
        """
        Las FUENTES de la biblioteca: las carpetas de PRIMER NIVEL dentro de la
        raíz que tienen documentos (WSS · ENZ · WMB…), con su cuenta.

        Es lo que el usuario llama «las 3 fuentes»: los 3 directorios donde
        están los PDF, con todos sus folders y subfolders por dentro.

        Con «con_disco» también entran las carpetas que EXISTEN en la raíz y
        tienen archivos de la biblioteca aunque ahora mismo no tengan documentos
        indexados (así una fuente nunca se le desaparece de las casillas).
        """
        raiz = raiz or self.raiz_por_documentos(excluir=excluir)
        if not raiz:
            return []
        partes_raiz = self._partes(raiz)
        cuenta = {}
        for f in self._filas_de_rutas(excluir):
            partes = self._partes(os.path.dirname(os.path.abspath(str(f["ruta"]))))
            if [p.lower() for p in partes[:len(partes_raiz)]] != [p.lower() for p in partes_raiz]:
                continue
            if len(partes) <= len(partes_raiz):
                continue
            clave = self._ruta_de_partes(partes[:len(partes_raiz) + 1])
            cuenta[clave] = cuenta.get(clave, 0) + 1
        if con_disco:
            try:
                dentro = sorted(os.listdir(raiz))[:200]
            except OSError:
                dentro = []
            EXT = (".pdf", ".doc", ".docx", ".txt", ".rtf", ".xls", ".xlsx",
                   ".ppt", ".pptx", ".odt", ".ods", ".epub", ".md", ".csv")
            for nombre in dentro:
                ruta = os.path.join(raiz, nombre)
                if not os.path.isdir(ruta):
                    continue
                clave = self._ruta_de_partes(partes_raiz + [nombre])
                if clave in cuenta:
                    continue
                if len(cuenta) >= max(1, int(limite)) + 4:
                    break
                try:
                    for _, _, archivos in os.walk(ruta):
                        if any(a.lower().endswith(EXT) for a in archivos):
                            cuenta[clave] = 0
                            break
                except OSError:
                    continue
        salida = [{"carpeta": c, "nombre": os.path.basename(c), "documentos": n,
                   "solo_disco": n == 0}
                  for c, n in cuenta.items()]
        salida.sort(key=lambda v: (-v["documentos"], v["nombre"].lower()))
        return salida

    def fichas_sin_archivo(self, limite=25) -> dict:
        """
        Cuántas fichas apuntan a un archivo que ya NO está en su ruta, y en qué
        carpetas se concentran. Sirve para el informe y para la reparación
        automática al abrir.
        """
        total = faltan = 0
        por_carpeta = {}
        muestra = []
        for f in self.todos("SELECT id, nombre, ruta FROM documentos"):
            total += 1
            ruta = str(f["ruta"] or "")
            if ruta and os.path.exists(ruta):
                continue
            faltan += 1
            carpeta = os.path.dirname(ruta)
            por_carpeta[carpeta] = por_carpeta.get(carpeta, 0) + 1
            if len(muestra) < limite:
                muestra.append({"id": f["id"], "nombre": f["nombre"], "ruta": ruta})
        ordenadas = sorted(por_carpeta.items(), key=lambda v: -v[1])[:limite]
        return {"total": total, "faltan": faltan, "muestra": muestra,
                "carpetas": [{"carpeta": c, "cuantas": n} for c, n in ordenadas]}

    def carpetas_mas_pobladas(self, raiz, niveles=2, limite=12) -> list:
        """
        Las carpetas con más documentos DENTRO de la raíz, contando «niveles»
        carpetas hacia adentro (para el informe: así se ve de un vistazo dónde
        están de verdad los PDF del usuario).
        """
        partes_raiz = self._partes(raiz or "")
        if not partes_raiz:
            return []
        cuenta = {}
        for f in self._filas_de_rutas():
            partes = self._partes(os.path.dirname(os.path.abspath(str(f["ruta"]))))
            if [p.lower() for p in partes[:len(partes_raiz)]] != [p.lower() for p in partes_raiz]:
                continue
            clave = self._ruta_de_partes(partes[:len(partes_raiz) + max(1, int(niveles))])
            cuenta[clave] = cuenta.get(clave, 0) + 1
        salida = sorted(cuenta.items(), key=lambda x: -x[1])[:limite]
        return [(c, n) for c, n in salida]

    def hay_sueltos_en(self, raiz) -> int:
        """Cuántos documentos están directamente en la raíz (sin carpeta fuente)."""
        partes_raiz = self._partes(raiz)
        n = 0
        for f in self.todos("SELECT ruta FROM documentos"):
            partes = self._partes(os.path.dirname(os.path.abspath(f["ruta"])))
            if [p.lower() for p in partes] == [p.lower() for p in partes_raiz]:
                n += 1
        return n

    @classmethod
    def carpeta_principal(cls, ruta: str, raices=None, madre=None) -> str:
        r"""
        Nombre de la carpeta de PRIMER NIVEL dentro de la biblioteca. Es lo que usan
        las casillas de arriba («Buscar en: WSS · ENZ · WMB»).

          ...\Estudios\WSS\1981\libro.pdf   ->  "WSS"
          ...\Estudios\WSS\Aras\x.pdf        ->  "WSS"  (aunque se indexe Aras)
          ...\Estudios\libro.pdf             ->  ""  (directo en la carpeta raíz)
          ...\Otra\Carpeta\libro.pdf         ->  "Carpeta"  (fuera de la biblioteca)

        Se respeta el nombre EXACTO como está en el disco (WSS, no «Wss») y se
        comparan las rutas sin distinguir mayúsculas ni el tipo de barra.
        """
        partes = cls._partes(ruta)
        carpeta = partes[:-1]                     # sin el nombre del archivo

        # 1) LA RAÍZ MANDA. Las casillas de arriba («Buscar en: …») son las
        #    carpetas de PRIMER NIVEL dentro de la raíz de la biblioteca:
        #    WSS, ENZ, WMB… Así, si la biblioteca es …\Estudios\WSS\Aras y
        #    …\Estudios\ENZ\Bib (muchas subcarpetas elegidas), las casillas
        #    siguen siendo las 3 fuentes y no los nombres de dentro.
        madre = madre or cls.carpeta_madre(raices)
        if madre:
            mp = cls._partes(madre)
            if mp and [p.lower() for p in carpeta[:len(mp)]] == [p.lower() for p in mp]:
                resto = carpeta[len(mp):]
                return resto[0] if resto else ""      # "" = suelto en la raíz

        # 2) Si el documento está fuera de la raíz (o no hay raíz), se prueban
        #    las raíces de la MÁS CORTA a la más larga.
        ordenadas = sorted((raices or []), key=lambda r: len(cls._partes(r)))
        for raiz in ordenadas:
            rp = cls._partes(raiz)
            if not rp:
                continue
            if [p.lower() for p in carpeta[:len(rp)]] == [p.lower() for p in rp]:
                resto = carpeta[len(rp):]
                return resto[0] if resto else ""
        return carpeta[-1] if carpeta else ""

    def recalcular_carpetas(self, raices=None, arreglar_categorias=True, madre=None) -> int:
        """
        Rellena «carpeta1» en toda la biblioteca (se hace UNA vez, al actualizar de
        versión) y, de paso, deja los nombres de colección tal como están en el
        disco (antes se ponía «Wss» con mayúscula inicial).

        Se hace TODO dentro de una sola transacción: con 11.000 documentos tarda
        un segundo, no minutos.
        """
        # La raíz se averigua por los DOCUMENTOS (es la que manda de verdad);
        # si no se puede, se usa la de la lista de carpetas, como antes.
        # La raíz la puede traer quien llama (la aplicación sabe cuál es su
        # carpeta madre); si no, se averigua por los documentos.
        madre = madre or self.raiz_por_documentos() or None
        self.ultima_raiz = madre or self.carpeta_madre(raices)
        filas = self.todos("SELECT id, ruta, categoria, categoria_manual, "
                           "COALESCE(carpeta1,'') AS carpeta1 FROM documentos")
        cambios = []
        for f in filas:
            principal = self.carpeta_principal(f["ruta"], raices, madre=madre)
            categoria = f["categoria"]
            if arreglar_categorias and not f["categoria_manual"]:
                base = os.path.basename(os.path.dirname(os.path.abspath(f["ruta"])))
                if base:
                    categoria = base
            if principal == f["carpeta1"] and categoria == f["categoria"]:
                continue
            cambios.append((principal, categoria, f["id"]))
        if not cambios:
            return 0
        with self._lock:
            self.con.executemany(
                "UPDATE documentos SET carpeta1 = ?, categoria = ? WHERE id = ?", cambios)
            self.con.commit()
        return len(cambios)

    def carpetas_principales(self):
        """Las casillas de arriba: cada carpeta de primer nivel con cuántos documentos
        tiene (la vacía —archivos sueltos en la carpeta madre— va al final)."""
        return self.todos(
            """SELECT COALESCE(carpeta1,'') AS valor, COUNT(*) n FROM documentos
               GROUP BY COALESCE(carpeta1,'')
               ORDER BY (COALESCE(carpeta1,'') = ''), COALESCE(carpeta1,'') COLLATE NOCASE""")

    def _q(self, sql, params=()):
        with self._lock:
            return self.con.execute(sql, params)

    def _por_tiempo(self, sql, params, ms):
        """
        Como `todos()`, pero con PRESUPUESTO DE TIEMPO: si la consulta se pasa de
        `ms` milisegundos, se corta (SQLite lo permite con un «progress handler»)
        y devuelve None en vez de dejar al usuario mirando la pantalla.

        Con eso una búsqueda en un equipo lento (o con una biblioteca enorme y el
        disco frío) nunca se queda «pensando» un minuto: como mucho espera esos
        segundos, y quien llama decide qué hacer con lo que no dio tiempo.
        """
        import time as _t
        limite = _t.monotonic() + (ms / 1000.0)

        def _cortar():
            return _t.monotonic() > limite

        with self._lock:
            self.con.set_progress_handler(_cortar, 20000)
            try:
                return [dict(r) for r in self.con.execute(sql, params).fetchall()]
            except sqlite3.OperationalError as e:
                if "interrupt" in str(e).lower():
                    return None                     # se cortó por tiempo: no dio tiempo
                raise
            finally:
                self.con.set_progress_handler(None, 0)

    def ejecutar(self, sql, params=()):
        with self._lock:
            cur = self.con.execute(sql, params)
            self.con.commit()
            return cur

    def uno(self, sql, params=()):
        with self._lock:
            r = self.con.execute(sql, params).fetchone()
            return dict(r) if r else None

    def todos(self, sql, params=()):
        with self._lock:
            return [dict(r) for r in self.con.execute(sql, params).fetchall()]

    # ------------------------------------------------------------- documentos
    def documento_por_ruta(self, ruta):
        return self.uno("SELECT * FROM documentos WHERE ruta = ?", (ruta,))

    def documento(self, doc_id):
        return self.uno("SELECT * FROM documentos WHERE id = ?", (doc_id,))

    def crear_documento(self, datos: dict) -> int:
        campos = ["ruta", "carpeta", "nombre", "extension", "tipo", "tamano", "modificado", "md5",
                  "titulo", "autor", "categoria", "carpeta1", "etiquetas", "anio", "paginas",
                  "caracteres", "estado", "nota", "agregado", "indexado", "encabezado"]
        vals = [datos.get(c) for c in campos]
        vals[campos.index("agregado")] = datos.get("agregado") or ahora()
        vals[campos.index("indexado")] = datos.get("indexado") or ahora()
        with self._lock:
            cur = self.con.execute(
                f"INSERT INTO documentos ({','.join(campos)}) VALUES ({','.join('?' * len(campos))})", vals)
            self.con.commit()
            return cur.lastrowid

    def actualizar_documento(self, doc_id: int, campos: dict):
        permitidos = {"ruta", "carpeta", "nombre", "extension", "tipo", "tamano", "modificado",
                      "md5", "titulo", "autor", "categoria", "carpeta1", "etiquetas", "anio",
                      "paginas", "caracteres", "estado", "nota", "favorito", "indexado",
                      "categoria_manual", "encabezado"}
        campos = {k: v for k, v in campos.items() if k in permitidos}
        if not campos:
            return
        sets = ", ".join(f"{k} = ?" for k in campos)
        with self._lock:
            self.con.execute(f"UPDATE documentos SET {sets} WHERE id = ?", list(campos.values()) + [doc_id])
            self.con.commit()

    def borrar_documento(self, doc_id: int):
        with self._lock:
            self.con.execute("DELETE FROM fragmentos WHERE doc_id = ?", (doc_id,))
            self.con.execute("DELETE FROM documentos WHERE id = ?", (doc_id,))
            self.con.commit()

    def guardar_fragmentos(self, doc_id: int, paginas):
        with self._lock:
            self.con.execute("DELETE FROM fragmentos WHERE doc_id = ?", (doc_id,))
            filas = [(p["texto"], doc_id, p["pagina"]) for p in paginas if p.get("texto")]
            self.con.executemany("INSERT INTO fragmentos (texto, doc_id, pagina) VALUES (?, ?, ?)", filas)
            self.con.commit()

    # ------------------------------------------------------------- listado
    def contar_listado(self, tipo=None, categoria=None, etiqueta=None, anio=None, estado=None,
                       favorito=None, texto=None, carpetas=None):
        """Cuántos documentos hay con esos filtros (el total REAL, no lo que se muestra)."""
        cond, params = ["1=1"], []
        if tipo:
            cond.append("tipo = ?"); params.append(tipo)
        if categoria:
            cond.append("categoria = ?"); params.append(categoria)
        _c, _p = self._cond_carpetas(carpetas)
        if _c:
            cond.append(_c); params.extend(_p)
        if anio:
            cond.append("anio = ?"); params.append(anio)
        if estado:
            cond.append("estado = ?"); params.append(estado)
        if favorito:
            cond.append("favorito = 1")
        if etiqueta:
            cond.append("(',' || replace(lower(etiquetas), ', ', ',') || ',') LIKE ?")
            params.append(f"%,{etiqueta.lower()},%")
        if texto:
            cond.append("(lower(titulo) LIKE ? OR lower(nombre) LIKE ? OR lower(autor) LIKE ? OR lower(etiquetas) LIKE ?)")
            params += [f"%{texto.lower()}%"] * 4
        r = self.uno(f"SELECT COUNT(*) n FROM documentos WHERE {' AND '.join(cond)}", params)
        return r["n"] if r else 0

    def listar(self, tipo=None, categoria=None, etiqueta=None, anio=None, estado=None,
               favorito=None, texto=None, orden="titulo", limite=500, desplazamiento=0,
               solo_categoria_raiz=None, carpetas=None):
        cond, params = ["1=1"], []
        if tipo:
            cond.append("tipo = ?"); params.append(tipo)
        if categoria:
            cond.append("categoria = ?"); params.append(categoria)
        if anio:
            cond.append("anio = ?"); params.append(anio)
        if estado:
            cond.append("estado = ?"); params.append(estado)
        if favorito:
            cond.append("favorito = 1")
        _c, _p = self._cond_carpetas(carpetas)
        if _c:
            cond.append(_c); params.extend(_p)
        if etiqueta:
            cond.append("(',' || replace(lower(etiquetas), ', ', ',') || ',') LIKE ?")
            params.append(f"%,{etiqueta.lower()},%")
        if texto:
            cond.append("(lower(titulo) LIKE ? OR lower(nombre) LIKE ? OR lower(autor) LIKE ? OR lower(etiquetas) LIKE ?)")
            params += [f"%{texto.lower()}%"] * 4
        ordenes = {
            "titulo": "titulo COLLATE NOCASE ASC",
            "nombre": "nombre COLLATE NOCASE ASC",
            "fecha": "agregado DESC",
            "modificado": "modificado DESC",
            "tamano": "tamano DESC",
            "paginas": "paginas DESC",
        }
        sql = f"SELECT * FROM documentos WHERE {' AND '.join(cond)} ORDER BY {ordenes.get(orden, ordenes['titulo'])} LIMIT ? OFFSET ?"
        return self.todos(sql, params + [limite, desplazamiento])

    def contar(self):
        r = self.uno("SELECT COUNT(*) n, COALESCE(SUM(paginas),0) p, COALESCE(SUM(tamano),0) t, COALESCE(SUM(caracteres),0) c FROM documentos")
        return r

    @staticmethod
    def _cond_carpetas(carpetas):
        """
        Condición SQL para las casillas de arriba («Buscar en: WSS · ENZ · WMB»).
        `carpetas` es la lista de carpetas CON la casilla puesta; la cadena vacía
        quiere decir «los documentos sueltos en la carpeta madre».
        Devuelve (condición, parámetros), o (None, []) si no hay que filtrar nada.
        """
        if carpetas is None:
            return None, []                 # no se pidió filtrar: todas las carpetas
        if not carpetas:
            return "1 = 0", []              # ninguna casilla puesta: no se muestra nada
        reales = [c for c in carpetas if c]
        partes, params = [], []
        if reales:
            huecos = ",".join("?" * len(reales))
            # COLLATE NOCASE: si un día se renombra la carpeta con otras mayúsculas,
            # la casilla sigue funcionando
            partes.append(f"COALESCE(carpeta1,'') COLLATE NOCASE IN ({huecos})")
            params.extend(reales)
        if any(c == "" for c in carpetas):
            partes.append("COALESCE(carpeta1,'') = ''")
        return "(" + " OR ".join(partes) + ")", params

    def _ids_filtrados(self, ids, tipo=None, categoria=None, etiqueta=None, anio=None, estado=None,
                       carpetas=None):
        """De una lista de ids, devuelve los que pasan los filtros del panel lateral."""
        if not ids:
            return []
        if carpetas is None and not any((tipo, categoria, etiqueta, anio, estado)):
            return list(ids)
        salida = []
        # en bloques, para no armar consultas gigantes con bibliotecas de miles de documentos
        for i in range(0, len(ids), 900):
            bloque = ids[i:i + 900]
            marcadores = ",".join("?" * len(bloque))
            cond, params = [f"id IN ({marcadores})"], list(bloque)
            if tipo:
                cond.append("tipo = ?"); params.append(tipo)
            if categoria:
                cond.append("categoria = ?"); params.append(categoria)
            if anio:
                cond.append("anio = ?"); params.append(anio)
            if estado:
                cond.append("estado = ?"); params.append(estado)
            if etiqueta:
                cond.append("(',' || replace(lower(etiquetas), ', ', ',') || ',') LIKE ?")
                params.append(f"%,{etiqueta.lower()},%")
            _c, _p = self._cond_carpetas(carpetas)
            if _c:
                cond.append(_c); params.extend(_p)
            salida.extend(r["id"] for r in self.todos(
                f"SELECT id FROM documentos WHERE {' AND '.join(cond)}", params))
        permitidos = set(salida)
        return [i for i in ids if i in permitidos]        # se conserva el orden

    # Cuántos DOCUMENTOS se cuentan (y se ordenan) como mucho en una búsqueda.
    # Con esto, buscar una palabra que sale en TODA la biblioteca no se lleva
    # minutos: se cuentan los primeros y se avisa «más de N».
    # Cuando en ESTE equipo una búsqueda se pasa de lento (biblioteca enorme,
    # disco lento, memoria justa), las siguientes se hacen en «modo rápido»: se
    # cuentan menos documentos y se preparan menos extractos. La búsqueda sigue
    # siendo correcta y ordenada; solo se avisa de que el total es aproximado.
    LIMITE_DOCS_BUSQUEDA = 3000
    LIMITE_DOCS_BUSQUEDA_RAPIDO = 800
    BUSQUEDA_LENTA_MS = 2000     # a partir de aquí se considera lenta en este equipo
    BUSQUEDA_RAPIDA_MS = 600     # por debajo de aquí se considera ya cómoda

    # Caché de las últimas búsquedas (la misma búsqueda repetida sale al instante).
    _cache_busquedas = {}
    _cache_orden = []

    def modo_rapido(self) -> bool:
        """
        ¿Este equipo necesita el «modo rápido» de búsqueda? Se decide solo, con
        lo que tardó la última búsqueda de verdad (nunca con una adivinanza).
        """
        if os.environ.get("BIBLIOTECA_MODO_RAPIDO") == "1":
            return True
        if os.environ.get("BIBLIOTECA_MODO_RAPIDO") == "0":
            return False
        return bool(getattr(self, "_modo_rapido", False))

    def ultima_busqueda(self) -> dict:
        """Cómo fue la última búsqueda (para el informe de búsquedas lentas)."""
        return dict(getattr(self, "_ultima_busqueda", {}) or {})

    def analizar(self):
        """
        Pide a la base de datos que estudie sus índices (ANALYZE) y elija el
        plan más rápido para las búsquedas. Se hace al terminar de indexar, en
        segundo plano: el usuario no tiene que hacer nada.
        """
        try:
            self.ejecutar("ANALYZE")
            self.ejecutar("PRAGMA optimize")
            return True
        except Exception:
            return False

    def _cache_clave(self, consulta, tipo, categoria, etiqueta, anio, estado, limite_docs,
                     desplazamiento, por_doc, frase, carpetas, terminos=None):
        # ¡Ojo!: «todas las carpetas» (None) y «ninguna carpeta» (lista vacía) NO
        # son lo mismo: si se guardaran con la misma clave, una búsqueda sin
        # filtro devolvería documentos de carpetas que el usuario apagó.
        if carpetas is None:
            cual = "·todas·"
        elif len(carpetas) == 0:
            cual = "·ninguna·"
        else:
            cual = tuple(carpetas)
        # r32-p · las palabras sueltas entran en la clave: si no, una respuesta
        # ordenada «como antes» (sin cobertura ni proximidad) se serviría para
        # la búsqueda que sí las pide, y el orden nuevo no se vería nunca.
        return (consulta, tipo, categoria, etiqueta, anio, estado, limite_docs,
                desplazamiento, por_doc, frase, cual,
                tuple(terminos) if terminos else None)

    def _cache_guardar(self, clave, valor, tope=48, segundos=180):
        try:
            import time as _t
            self._cache_busquedas[clave] = (_t.time(), valor)
            self._cache_orden.append(clave)
            while len(self._cache_orden) > tope:
                viejo = self._cache_orden.pop(0)
                self._cache_busquedas.pop(viejo, None)
        except Exception:
            pass

    def _cache_leer(self, clave, segundos=180):
        try:
            import time as _t
            dato = self._cache_busquedas.get(clave)
            if dato and (_t.time() - dato[0]) <= segundos:
                return dato[1]
        except Exception:
            pass
        return None

    def olvidar_cache_busquedas(self):
        try:
            self._cache_busquedas.clear(); self._cache_orden.clear()
        except Exception:
            pass

    # ------------------------------------------------- r32-p · RELEVANCIA
    # CÓMO SE ORDENA UNA BÚSQUEDA DE VARIAS PALABRAS.
    # Hasta aquí mandaba «cuántas veces sale CUALQUIERA de las palabras»: con
    # cinco palabras o más, eso ponía arriba el libro que más repetía UNA de
    # ellas, aunque las demás no salieran por ninguna parte. Ahora se hace lo
    # que usan los buscadores de verdad (y lo que él ha pedido):
    #
    #   1) COBERTURA  · de las palabras buscadas, cuántas DISTINTAS salen en el
    #                   documento. Es el factor «coord» de Lucene / Elastic:
    #                   premia al documento que más palabras de la consulta
    #                   tiene, en vez de al que más veces repite una.
    #   2) PROXIMIDAD · entre los que empatan, gana el que las tiene más
    #                   JUNTAS. Se mide con la «ventana mínima»: el trozo más
    #                   corto de texto que contiene todas las palabras (lo más
    #                   parecido a «dentro de una misma oración»).
    #   3) VECES      · si aun así empatan, el que más coincidencias tiene.
    #
    # La FRASE EXACTA, cuando existe, sigue yendo lo primero (es lo más exacto).
    # Y todo esto se mide con presupuesto de tiempo: si la biblioteca es enorme
    # o el disco va lento, se ordena como antes pero se responde igual de rápido.

    @staticmethod
    def _ventana_minima(texto, terminos, tope_fichas=6000):
        """
        Mide un trozo de texto contra las palabras buscadas.

        Devuelve (cuántas de las palabras salen, ancho de la ventana, veces):
          · «cuántas»  -> de las palabras buscadas, cuántas DISTINTAS aparecen;
          · «ancho»    -> el trozo más corto (en palabras) que las contiene a
                          TODAS las que salieron: 1 si están pegadas, 8 si están
                          en la misma frase… 10000 si no se puede medir;
          · «veces»    -> cuántas coincidencias hay en total.
        """
        import re
        if not texto:
            return (0, 10000, 0)
        t = sin_acentos(texto[:60000])
        donde = {}
        veces = 0
        sitio = {}
        for k, term in enumerate(terminos):
            sitio[term] = k
        for i, f in enumerate(re.findall(r"\w+", t)):
            k = sitio.get(f)
            if k is None:
                continue
            donde.setdefault(k, []).append(i)
            veces += 1
            if len(donde) == len(terminos) and i > tope_fichas:
                pass
        cuantas = len(donde)
        if cuantas == 0:
            return (0, 10000, 0)
        if cuantas == 1:
            return (1, 1, veces)
        # ventana mínima: todas las posiciones ordenadas y una ventana que
        # se estira por la derecha y se encoge por la izquierda (clásico).
        todas = []
        for k, pos in donde.items():
            for q in pos:
                todas.append((q, k))
        todas.sort()
        mejor = 10000
        contados, dentro, izq = {}, 0, 0
        for der in range(len(todas)):
            k = todas[der][1]
            contados[k] = contados.get(k, 0) + 1
            if contados[k] == 1:
                dentro += 1
            while dentro == cuantas and izq <= der:
                ancho = todas[der][0] - todas[izq][0] + 1
                if ancho < mejor:
                    mejor = ancho
                k2 = todas[izq][1]
                contados[k2] -= 1
                if contados[k2] == 0:
                    dentro -= 1
                izq += 1
        return (cuantas, mejor or 10000, veces)

    def _nota_de_documentos(self, consulta, terminos, ids, conteo=None, ms=1500):
        """
        r32-p · Para cada documento candidato mide cuántas de las palabras
        salen (cobertura) y a qué distancia (ventana mínima).

        Devuelve (nota, mejor_pagina):
          nota         -> {doc_id: (cuántas palabras salen, ventana, veces)}
          mejor_pagina -> {doc_id: {'pagina': n, 'extracto': s}} la hoja donde
                          las palabras salen más juntas (para abrir el libro
                          justo ahí).
        Si no da tiempo, devuelve (None, None) y se ordena como se hacía antes.
        """
        import time as _t
        conteo = conteo or {}
        fin = _t.monotonic() + (ms / 1000.0)
        terminos = list(dict.fromkeys(
            [t for t in (sin_acentos(x) for x in (terminos or [])) if t and len(t) >= 2]))
        if len(terminos) < 2:
            return None, None
        ids = list(ids)
        if not ids:
            return None, None

        # ---- 1) cobertura: cuántas palabras DISTINTAS salen en cada documento
        cobertura = {i: 0 for i in ids}
        for t in terminos:
            falta = (fin - _t.monotonic()) * 1000
            if falta < 60:
                break
            filas = self._por_tiempo(
                "SELECT DISTINCT doc_id FROM fragmentos WHERE fragmentos MATCH ?",
                (f'"{t}"',), min(600, falta))
            if filas is None:
                break                     # no dio tiempo: se usa lo medido
            for f in filas:
                if f["doc_id"] in cobertura:
                    cobertura[f["doc_id"]] += 1

        # ---- 2) proximidad: sólo para los que más pintan (es lo que cuesta)
        nota, mejor = {}, {}
        derechos = sorted(ids, key=lambda i: (-cobertura.get(i, 0), -conteo.get(i, 0), i))
        cuantos_docs = int(os.environ.get("BIBLIOTECA_PROX_DOCS") or 60)
        derechos = derechos[:max(10, cuantos_docs)]
        if derechos:
            marc = ",".join("?" * len(derechos))
            sql = (f"SELECT doc_id, pagina, texto, snippet(fragmentos, 0, '"
                   f"{MARCA_INI}', '{MARCA_FIN}', ' … ', 60) AS extracto "
                   f"FROM fragmentos WHERE fragmentos MATCH ? AND doc_id IN ({marc}) "
                   f"LIMIT ?")
            params = [consulta, *derechos, min(1200, 30 * len(derechos))]
            filas = self._por_tiempo(sql, params,
                                     max(150, (fin - _t.monotonic()) * 1000)) or []
            por_doc = {}
            for f in filas:
                por_doc.setdefault(f["doc_id"], []).append(f)
            for doc_id, paginas in por_doc.items():
                mejor_nota = None
                for f in paginas[:12]:
                    if _t.monotonic() > fin:
                        break
                    c, ancho, veces = self._ventana_minima(f["texto"], terminos)
                    if mejor_nota is None or (c, -ancho, veces) > (mejor_nota[0], -mejor_nota[1], mejor_nota[2]):
                        mejor_nota = (c, ancho, veces)
                        mejor[doc_id] = {"pagina": f["pagina"], "extracto": f["extracto"]}
                if mejor_nota:
                    nota[doc_id] = mejor_nota
        salida = {}
        for i in ids:
            c, ancho, veces = nota.get(i, (cobertura.get(i, 0), 10000, 0))
            salida[i] = (max(c, cobertura.get(i, 0)), ancho, veces)
        return salida, mejor

    def _cond_documentos(self, tipo=None, categoria=None, etiqueta=None, anio=None,
                         estado=None, carpetas=None, alias="d"):
        """
        Las condiciones de los filtros (carpetas marcadas, colección, año,
        etiqueta…) armadas para ir DENTRO de la consulta que cuenta las
        coincidencias, contra la tabla `documentos` con el alias que se diga.

        r32-u · antes estos filtros se aplicaban DESPUÉS de contar, y contar se
        hacía sobre los 3.000 primeros documentos que coincidían (en el orden
        del índice). Resultado: lo que se indexó después —la Biblia, que se
        instala la última— se quedaba fuera del corte y, al marcar solo esa
        carpeta, salían «0 resultados» aunque SÍ tuviera coincidencias. Con la
        condición dentro de la consulta, el tope se aplica YA FILTRADO.
        """
        cond, params = [], []
        if tipo:
            cond.append(alias + ".tipo = ?"); params.append(tipo)
        if categoria:
            cond.append(alias + ".categoria = ?"); params.append(categoria)
        if anio:
            cond.append(alias + ".anio = ?"); params.append(anio)
        if estado:
            cond.append(alias + ".estado = ?"); params.append(estado)
        if etiqueta:
            cond.append("(',' || replace(lower(" + alias + ".etiquetas), ', ', ',') || ',') LIKE ?")
            params.append(f"%,{etiqueta.lower()},%")
        _c, _p = self._cond_carpetas(carpetas)
        if _c:
            cond.append(_c.replace("carpeta1", alias + ".carpeta1")); params.extend(_p)
        return (" AND ".join(cond) if cond else ""), params

    def buscar(self, consulta: str, tipo=None, categoria=None, etiqueta=None, anio=None,
               estado=None, limite_docs=50, desplazamiento=0, por_doc=4, frase=None, carpetas=None, terminos=None):
        """
        Busca en TODA la biblioteca.

        Devuelve (resultados, total_documentos, total_coincidencias,
        total_aproximado): los documentos que coinciden (ya paginados), cuántos
        son, cuántas coincidencias hay, y si el total es APROXIMADO porque la
        palabra sale en muchísimos documentos (entonces se cuentan solo los
        primeros LIMITE_DOCS_BUSQUEDA, para que la búsqueda responda igual de
        rápido con una biblioteca de miles de PDF).
          * resultados           -> la página pedida, con hasta `por_doc` extractos por documento
          * total_documentos     -> cuántos documentos coinciden (todos, no solo los mostrados)
          * total_coincidencias  -> cuántas coincidencias hay en total en esos documentos

        `consulta` debe venir ya construida en sintaxis FTS5.

        `frase` (opcional): la frase COMPLETA tal como la escribió el usuario
        (por ejemplo «huerto del eden»). Los documentos que la traen tal cual
        se devuelven PRIMERO, aunque tengan menos coincidencias sueltas: así la
        palabra exacta gana y los artículos comunes (del, el, la…) no estorban.
        """
        # ---- 0) ¿ya se buscó esto hace un momento? ----------------------------
        clave_cache = self._cache_clave(consulta, tipo, categoria, etiqueta, anio, estado,
                                        limite_docs, desplazamiento, por_doc, frase, carpetas,
                                        terminos)
        guardado = self._cache_leer(clave_cache)
        if guardado is not None:
            return guardado

        # ---- 1) los documentos que coinciden y cuántas veces -------------------
        # El tope evita que una palabra que sale en todo (o que se busca mientras
        # la aplicación está indexando) tarde minutos: se cuentan los primeros y
        # se avisa de que el total es «más de N». En un equipo lento (o con una
        # biblioteca enorme) el tope se baja solo: «modo rápido».
        import time as _time
        _t0 = _time.perf_counter()
        self._aviso_tiempo = ""                 # ¿hubo que recortar por tiempo?
        rapido = self.modo_rapido()
        tope = int(self.LIMITE_DOCS_BUSQUEDA_RAPIDO if rapido else self.LIMITE_DOCS_BUSQUEDA)
        # Se intenta contar los primeros `tope` documentos. Si la biblioteca es tan
        # grande (o el equipo tan lento) que eso no cabe en el presupuesto, se
        # vuelve a probar con menos… y así hasta dar una respuesta en segundos.
        # r32-u · los filtros (sobre todo las carpetas marcadas) entran en la
        # consulta que cuenta: así el tope se aplica a los documentos que YA
        # pasan el filtro. Si se contara primero y se filtrara después, las
        # carpetas que entraron tarde en el índice se quedarían fuera del corte
        # y saldrían a cero aunque tuvieran coincidencias.
        cond_doc, params_doc = self._cond_documentos(
            tipo=tipo, categoria=categoria, etiqueta=etiqueta, anio=anio,
            estado=estado, carpetas=carpetas)
        if cond_doc:
            sql_cuenta = ("SELECT fragmentos.doc_id, COUNT(*) n FROM fragmentos "
                          "JOIN documentos d ON d.id = fragmentos.doc_id "
                          "WHERE fragmentos MATCH ? AND " + cond_doc +
                          " GROUP BY fragmentos.doc_id LIMIT ?")
        else:
            sql_cuenta = ("SELECT doc_id, COUNT(*) n FROM fragmentos "
                          "WHERE fragmentos MATCH ? GROUP BY doc_id LIMIT ?")
        por_tiempo = False
        filas = None
        presupuesto = float(os.environ.get("BIBLIOTECA_CUENTA_MS") or 2500)
        for intento, ms in ((tope, presupuesto), (min(500, tope), presupuesto),
                            (150, presupuesto)):
            filas = self._por_tiempo(
                sql_cuenta, (consulta,) + tuple(params_doc) + (intento,), ms)
            if filas is not None:
                if intento != tope:
                    por_tiempo = True          # hubo que rebajar: se avisará
                tope = intento
                break
        if filas is not None and por_tiempo:
            # Se pudo contar, pero hubo que recortar por tiempo: se avisa claro.
            self._aviso_tiempo = (
                f"Para responder rápido se contaron solo los primeros {tope} documentos "
                "(el total es aproximado). Con una palabra más concreta sale exacto.")
        if filas is None:
            # Ni con 150 documentos dio tiempo: se responde con lo que se pueda del
            # título/nombre (instantáneo) y se avisa, en vez de dejar esperando.
            por_tiempo = True
            filas = []
            titulo_docs = self._por_tiempo(
                "SELECT id AS doc_id, 1 AS n FROM documentos "
                "WHERE titulo LIKE ? OR nombre LIKE ? LIMIT 200",
                (f"%{texto_para_like(consulta)}%", f"%{texto_para_like(consulta)}%"), 1500) or []
            filas = titulo_docs
            self._aviso_tiempo = (
                "La biblioteca es enorme y el disco no dio tiempo a leer el texto: "
                "se muestran solo los documentos cuyo TÍTULO contiene la palabra. "
                "Pruebe con una palabra más concreta o pulse «Indexar» para dejar el "
                "índice al día.")
        if not filas:
            # Sin coincidencias también se anota: así una racha de búsquedas que van
            # bien (aunque no encuentren nada) devuelve el modo normal.
            vacio = ([], 0, 0, False)
            _ahora = _time.perf_counter()
            self._anotar_busqueda(consulta, vacio, _t0, _ahora, _ahora, tope, rapido, por_tiempo)
            self._cache_guardar(clave_cache, vacio)
            return vacio
        aproximado = len(filas) >= tope or por_tiempo
        _t1 = _time.perf_counter()
        filas.sort(key=lambda r: (-r["n"], r["doc_id"]))
        conteo = {r["doc_id"]: r["n"] for r in filas}
        orden = [r["doc_id"] for r in filas]

        # ---- 1-bis) la FRASE COMPLETA primero ---------------------------------
        # Escribir «huerto del eden» debe traer arriba los documentos que dicen
        # «huerto del eden» seguido, no los que tienen «del» en cualquier parte.
        con_frase = set()
        if frase:
            try:
                con_frase = {f["doc_id"] for f in self.todos(
                    "SELECT DISTINCT doc_id FROM fragmentos WHERE fragmentos MATCH ? LIMIT ?",
                    (f'"{frase}"', tope))}
            except Exception:
                con_frase = set()
            if con_frase:
                orden.sort(key=lambda i: (0 if i in con_frase else 1,
                                          -conteo.get(i, 0), i))

        # ---- 2) filtros del panel lateral (tipo, colección, año, etiqueta…) ----
        orden = self._ids_filtrados(orden, tipo=tipo, categoria=categoria,
                                    etiqueta=etiqueta, anio=anio, estado=estado,
                                    carpetas=carpetas)
        # ---- 2-bis) r32-p · CON VARIAS PALABRAS, MANDA LA COINCIDENCIA -------
        # Se ordena por cuántas palabras DISTINTAS salen en el documento y por
        # lo JUNTAS que están (la ventana mínima), en vez de por cuántas veces
        # se repite una sola de ellas. La frase exacta sigue yendo primero.
        # Si no da tiempo a medir, se deja el orden de siempre: en un equipo
        # lento es mejor responder rápido que responder perfecto.
        mejores_paginas = {}
        if terminos and len(terminos) >= 2 and len(orden) > 1:
            # El presupuesto se reparte: en un equipo lento (modo rápido) se
            # mide la mitad de tiempo, para que ordenar mejor no le cueste
            # esperar más (él ya se quejó de las búsquedas de 4 minutos).
            try:
                nota, mejores_paginas = self._nota_de_documentos(
                    consulta, terminos, orden, conteo, ms=(600 if rapido else 1200))
            except Exception:
                nota, mejores_paginas = None, {}
            if nota:
                orden.sort(key=lambda i: (
                    0 if i in con_frase else 1,
                    -nota.get(i, (0, 10000, 0))[0],
                    nota.get(i, (0, 10000, 0))[1],
                    -nota.get(i, (0, 10000, 0))[2],
                    -conteo.get(i, 0), i))
        total_documentos = len(orden)
        total_coincidencias = sum(conteo.get(i, 0) for i in orden)
        _t2 = _time.perf_counter()
        if not orden:
            vacio = ([], 0, 0, False)
            self._anotar_busqueda(consulta, vacio, _t0, _t1, _t2, tope, rapido, por_tiempo)
            self._cache_guardar(clave_cache, vacio)
            return vacio

        # ---- 3) solo la página pedida: fichas y extractos ---------------------
        desde = max(0, int(desplazamiento or 0))
        cuantos = max(1, int(limite_docs or 50))
        if rapido:
            cuantos = min(cuantos, 120)
        pagina_ids = orden[desde:desde + cuantos]
        if not pagina_ids:
            salida = ([], total_documentos, total_coincidencias, aproximado)
            self._cache_guardar(clave_cache, salida)
            return salida

        marcadores = ",".join("?" * len(pagina_ids))
        fichas = {d["id"]: d for d in self.todos(
            f"SELECT * FROM documentos WHERE id IN ({marcadores})", list(pagina_ids))}

        agrupado = self._extractos_de(consulta, pagina_ids, por_doc)

        resultados = []
        for doc_id in pagina_ids:                       # se respeta el orden por coincidencias
            d = fichas.get(doc_id)
            if not d:
                continue
            r = agrupado.get(doc_id) or {"paginas": []}
            paginas = list(r["paginas"])
            # r32-p · la hoja donde las palabras salen más JUNTAS va la primera:
            # es la que se abre al pulsar en la tarjeta.
            mp = (mejores_paginas or {}).get(doc_id)
            if mp and mp.get("pagina") is not None:
                puestas = [x for x in paginas if x.get("pagina") == mp["pagina"]]
                if puestas:
                    paginas.remove(puestas[0])
                    paginas.insert(0, puestas[0])
                elif mp.get("extracto"):
                    paginas.insert(0, {"pagina": mp["pagina"],
                                       "extracto": mp["extracto"]})
                    del paginas[max(1, int(por_doc)):]
            resultados.append({"documento": d, "paginas": paginas,
                               "coincidencias": conteo.get(doc_id, 0)})
        salida = (resultados, total_documentos, total_coincidencias, aproximado)
        self._anotar_busqueda(consulta, salida, _t0, _t1, _t2, tope, rapido, por_tiempo)
        self._cache_guardar(clave_cache, salida)
        return salida

    def _anotar_busqueda(self, consulta, salida, t0, t1, t2, tope, rapido, por_tiempo=False):
        """
        Guarda cómo fue esta búsqueda (cuánto tardó cada parte) y decide si este
        equipo necesita el «modo rápido» la próxima vez. Con eso, una búsqueda
        lenta deja de repetirse: el programa se adapta solo.
        """
        import time as _time
        ms_total = (_time.perf_counter() - t0) * 1000
        self._ultima_busqueda = {
            "por_tiempo": bool(por_tiempo),
            "consulta": consulta, "ms_total": round(ms_total),
            "ms_cuenta": round((t1 - t0) * 1000), "ms_filtros": round((t2 - t1) * 1000),
            "ms_extractos": round((_time.perf_counter() - t2) * 1000),
            "documentos": salida[1], "coincidencias": salida[2], "tope": tope,
            "aproximado": bool(salida[3]), "modo_rapido": bool(rapido),
            "cuando": ahora(),
            "aviso_tiempo": getattr(self, "_aviso_tiempo", ""),
        }
        lenta = float(os.environ.get("BIBLIOTECA_LENTA_MS") or self.BUSQUEDA_LENTA_MS)
        if ms_total > lenta:
            # Este equipo (o esta biblioteca) va lento: la próxima se hace en modo
            # rápido. Se necesitan varias búsquedas seguidas ya cómodas para volver
            # al modo normal: así no se anda cambiando de uno a otro.
            self._modo_rapido = True
            self._rapidas_seguidas = 0
        elif getattr(self, "_modo_rapido", False) and ms_total < self.BUSQUEDA_RAPIDA_MS:
            self._rapidas_seguidas = int(getattr(self, "_rapidas_seguidas", 0)) + 1
            if self._rapidas_seguidas >= 5:
                self._modo_rapido = False
                self._rapidas_seguidas = 0
        else:
            self._rapidas_seguidas = 0

    def coincidencias_por_carpeta(self, consulta: str, tipo=None, categoria=None, etiqueta=None,
                                  anio=None, estado=None):
        """
        Para la búsqueda que se está haciendo ahora: cuántas COINCIDENCIAS y
        cuántos documentos salen de CADA carpeta (WSS, ENZ, WMB, sueltos…).

        Se cuenta sobre TODA la biblioteca, sin mirar las casillas de arriba:
        así, cuando el usuario le quita la marca a una carpeta, el número que
        queda a la vista le dice cuántas palabras está dejando fuera (y
        cuántas recupera si la vuelve a marcar).

        r32-u · y se cuenta ENTERO: ni se recortan los documentos (antes solo
        los 3.000 primeros del índice, con lo que lo último instalado —la
        Biblia— salía a cero) ni se cuenta con otra consulta que la que él
        escribió (eso lo decide quien llama, no esto).

        Devuelve [{'valor': 'WSS', 'documentos': 4, 'coincidencias': 11}, …]
        ordenado por coincidencias (y de último los documentos sueltos).
        """
        clave = ("x", consulta, tipo, categoria, etiqueta, anio, estado,
                 self.LIMITE_DOCS_BUSQUEDA)
        guardado = self._cache_leer(clave)
        if guardado is not None:
            return guardado
        # r32-u · ANTES había un «LIMIT 3000» aquí (LIMITE_DOCS_BUSQUEDA). Ese
        # tope contaba solo los 3.000 PRIMEROS documentos que coincidían, EN EL
        # ORDEN EN QUE ENTRARON EN EL ÍNDICE: lo que se indexó después (la
        # Biblia, que se instaló la última) se quedaba fuera del corte y salía
        # «0» aunque SÍ tuviera coincidencias. Contar entero no cuesta nada de
        # más (medido: 5 ms con 4.400 documentos, contra 4 ms con el tope).
        filas = self.todos(
            "SELECT doc_id, COUNT(*) n FROM fragmentos WHERE fragmentos MATCH ? "
            "GROUP BY doc_id", (consulta,))
        if not filas:
            self._cache_guardar(clave, [])
            return []
        conteo = {r["doc_id"]: r["n"] for r in filas}
        ids = self._ids_filtrados([r["doc_id"] for r in filas], tipo=tipo, categoria=categoria,
                                  etiqueta=etiqueta, anio=anio, estado=estado, carpetas=None)
        if not ids:
            return []
        acumulado = {}
        for i in range(0, len(ids), 900):                    # en bloques: bibliotecas de miles
            bloque = ids[i:i + 900]
            marcadores = ",".join("?" * len(bloque))
            for d in self.todos(
                    f"SELECT id, COALESCE(carpeta1,'') c FROM documentos WHERE id IN ({marcadores})", bloque):
                a = acumulado.setdefault(d["c"], {"valor": d["c"], "documentos": 0, "coincidencias": 0})
                a["documentos"] += 1
                a["coincidencias"] += conteo.get(d["id"], 0)
        salida = sorted(acumulado.values(),
                        key=lambda x: (x["valor"] == "", -x["coincidencias"], x["valor"].upper()))
        self._cache_guardar(clave, salida)
        return salida

    def exportar_todo(self, carpetas=None):
        """Índice completo (o solo las carpetas marcadas, si se piden)."""
        cond, params = self._cond_carpetas(carpetas)
        sql = "SELECT * FROM documentos"
        if cond:
            sql += f" WHERE {cond}"
        return self.todos(sql + " ORDER BY titulo COLLATE NOCASE", params)

    def _extractos_de(self, consulta, ids, por_doc=4):
        """
        Extractos (con la palabra resaltada) para los documentos indicados.

        Se traen los fragmentos más relevantes de esos documentos y, si alguno se
        quedara sin extractos (porque otros acaparan el cupo), se hace un repaso
        solo para él. Así TODAS las tarjetas de la página muestran extractos.
        """
        por_doc = max(1, int(por_doc or 4))
        grupos = {}
        # Los extractos (que leen el texto de cada página) son lo más caro de una
        # búsqueda: si el equipo es lento, se prefiere la LISTA de documentos en
        # segundos antes que la lista con extractos en un minuto.
        import time as _t
        fin = _t.monotonic() + (float(os.environ.get("BIBLIOTECA_EXTRACTOS_MS") or 2500) / 1000.0)

        def traer(ids_q, limite):
            if not ids_q or limite <= 0:
                return []
            marc = ",".join("?" * len(ids_q))
            sql = f"""
                SELECT doc_id, pagina,
                       snippet(fragmentos, 0, '{MARCA_INI}', '{MARCA_FIN}', ' … ', 60) AS extracto,
                       bm25(fragmentos) AS rango
                FROM fragmentos
                WHERE fragmentos MATCH ? AND doc_id IN ({marc})
                ORDER BY rango
                LIMIT ?
            """
            falta = max(300, int((fin - _t.monotonic()) * 1000))
            if falta <= 300 and grupos:
                return []                       # ya no queda tiempo para más extractos
            return self._por_tiempo(sql, [consulta, *ids_q, limite], falta) or []

        def agrupar(filas):
            for f in filas:
                paginas = grupos.setdefault(f["doc_id"], [])
                if len(paginas) < por_doc:
                    paginas.append({"pagina": f["pagina"], "extracto": f["extracto"]})

        agrupar(traer(ids, min(600, max(160, len(ids) * por_doc * 2))))

        # Repaso: documentos de la página que se quedaron sin extractos
        for intento in range(3 if _t.monotonic() < fin else 0):
            faltan = [i for i in ids if not grupos.get(i)]
            if not faltan:
                break
            limite = max(por_doc * 4, len(faltan) * por_doc * (4 ** (intento + 1)))
            filas = traer(faltan, limite)
            if not filas:
                break
            agrupar(filas)

        return groups_ordenados(grupos, ids)

    def buscar_metadatos(self, q: str, limite=50, carpetas=None):
        """
        Busca en título, autor, etiquetas, categoría, nombre...

        Respeta las casillas de carpetas de arriba: si el usuario apagó una
        carpeta, sus documentos NO deben volver a aparecer por la ficha.
        """
        con = self._acentos(q)
        like = f"%{con}%"
        cond, params = [f"""({self._sin_acentos('titulo')} LIKE ?
                   OR {self._sin_acentos('autor')} LIKE ?
                   OR {self._sin_acentos('etiquetas')} LIKE ?
                   OR {self._sin_acentos('categoria')} LIKE ?
                   OR {self._sin_acentos('nombre')} LIKE ?)"""], [like, like, like, like, like]
        _c, _p = self._cond_carpetas(carpetas)
        if _c:
            cond.append(_c); params.extend(_p)
        params.append(limite)
        return self.todos(
            f"""SELECT *, 0 AS coincidencias FROM documentos
                WHERE {' AND '.join(cond)}
                ORDER BY titulo COLLATE NOCASE LIMIT ?""", params)

    @staticmethod
    def _acentos(t: str) -> str:
        tabla = str.maketrans("áéíóúüñÁÉÍÓÚÜÑ", "aeiouunAEIOUUN")
        return (t or "").translate(tabla).lower()

    def _sin_acentos(self, columna: str) -> str:
        expr = f"lower({columna})"
        for a, b in [("á", "a"), ("é", "e"), ("í", "i"), ("ó", "o"), ("ú", "u"), ("ü", "u"), ("ñ", "n")]:
            expr = f"replace({expr}, '{a}', '{b}')"
        return expr

    def texto_pagina(self, doc_id: int, pagina: int = 1) -> dict:
        """
        Texto COMPLETO de una página, para la vista previa de los resultados.

        Devuelve {'texto', 'pagina', 'paginas'} — `paginas` es el total del
        documento, para poder seguir leyendo página a página desde la búsqueda.
        """
        pagina = max(1, int(pagina or 1))
        d = self.documento(doc_id) or {}
        fila = self.uno("SELECT texto FROM fragmentos WHERE doc_id = ? AND pagina = ? LIMIT 1",
                        (doc_id, pagina))
        texto = (fila or {}).get("texto") or ""
        if not texto:                      # por si el número de página no existe: la más cercana
            vecina = self.uno("SELECT pagina, texto FROM fragmentos WHERE doc_id = ? "
                              "ORDER BY ABS(pagina - ?) LIMIT 1", (doc_id, pagina))
            if vecina:
                texto, pagina = vecina["texto"] or "", vecina["pagina"]
        return {"texto": texto, "pagina": pagina,
                "paginas": int(d.get("paginas") or 0),
                "titulo": d.get("titulo") or d.get("nombre") or "",
                "tipo": d.get("tipo") or ""}

    def paginas_documento(self, doc_id: int):
        return self.todos("SELECT pagina, texto FROM fragmentos WHERE doc_id = ? ORDER BY pagina", (doc_id,))

    def paginas_con_texto(self, doc_id: int, termino: str):
        """Páginas del documento donde aparece el término (para ir de coincidencia
        en coincidencia dentro del visor). Compara sin acentos ni mayúsculas."""
        if not termino or not termino.strip():
            return []
        objetivo = sin_acentos(termino)
        if not objetivo:
            return []
        salida = []
        for p in self.paginas_documento(doc_id):
            if objetivo in sin_acentos(p["texto"] or ""):
                salida.append(p["pagina"])
        return salida

    # ------------------------------------------------------------- facetas / estadísticas
    def facetas(self):
        def agrupar(col, orden="n DESC"):
            return self.todos(
                f"SELECT {col} AS valor, COUNT(*) n FROM documentos WHERE COALESCE({col},'') <> '' GROUP BY {col} ORDER BY {orden}")
        etiquetas = {}
        for d in self.todos("SELECT etiquetas FROM documentos WHERE COALESCE(etiquetas,'') <> ''"):
            for e in re.split(r"[,;]", d["etiquetas"]):
                e = e.strip()
                if e:
                    etiquetas[e] = etiquetas.get(e, 0) + 1
        return {
            "carpetas": self.carpetas_principales(),
            "tipos": agrupar("tipo", "n DESC"),
            "categorias": agrupar("categoria", "valor COLLATE NOCASE"),
            "anios": agrupar("anio", "valor DESC"),
            "estados": agrupar("estado", "n DESC"),
            "etiquetas": sorted([{"valor": k, "n": v} for k, v in etiquetas.items()], key=lambda x: -x["n"]),
        }

    def estadisticas(self):
        base = self.uno("""SELECT COUNT(*) total,
                                  COALESCE(SUM(paginas),0) paginas,
                                  COALESCE(SUM(caracteres),0) caracteres,
                                  COALESCE(SUM(tamano),0) bytes,
                                  SUM(CASE WHEN estado='ok' THEN 1 ELSE 0 END) ok,
                                  SUM(CASE WHEN estado='sin_texto' THEN 1 ELSE 0 END) sin_texto,
                                  SUM(CASE WHEN estado='error' THEN 1 ELSE 0 END) error,
                                  SUM(CASE WHEN estado='desaparecido' THEN 1 ELSE 0 END) desaparecido,
                                  SUM(favorito) favoritos
                           FROM documentos""")
        f = self.facetas()
        duplicados = self.todos("""SELECT md5, COUNT(*) n, GROUP_CONCAT(nombre, ' | ') nombres
                                   FROM documentos WHERE md5 <> '' GROUP BY md5 HAVING n > 1 ORDER BY n DESC LIMIT 20""")
        palabras = {}
        for fila in self.todos("SELECT texto FROM fragmentos LIMIT 4000"):
            for p in re.findall(r"[a-záéíóúüñ]{6,}", (fila["texto"] or "").lower()):
                palabras[p] = palabras.get(p, 0) + 1
        vacias = {"porque", "cuando", "donde", "tambien", "puede", "deberá", "debera", "según", "segun",
                  "mediante", "durante", "aunque", "mismo", "objeto", "presente", "artículo", "articulo",
                  "cláusula", "clausula", "contrato", "manera", "manera", "entre", "sobre", "través",
                  "traves", "acuerdo", "documento", "empresa", "servicio", "partes", "así", "hacia"}
        comunes = sorted([(k, v) for k, v in palabras.items() if k not in vacias], key=lambda x: -x[1])[:40]
        base.update({
            "tipos": f["tipos"], "categorias": f["categorias"], "anios": f["anios"],
            "etiquetas": f["etiquetas"][:30], "estados": f["estados"],
            "duplicados": duplicados, "palabras_frecuentes": [{"palabra": k, "n": v} for k, v in comunes],
        })
        return base

    # ------------------------------------------------------------- historial
    def registrar_busqueda(self, texto: str, n: int):
        if not texto.strip():
            return
        with self._lock:
            self.con.execute("INSERT INTO historial (cuando, texto, n) VALUES (?,?,?)", (ahora(), texto.strip(), n))
            self.con.execute("""DELETE FROM historial WHERE id NOT IN
                                (SELECT id FROM historial ORDER BY id DESC LIMIT 60)""")
            self.con.commit()

    def historial(self, limite=12):
        return self.todos("SELECT texto, MAX(cuando) cuando, COUNT(*) veces, MAX(n) n FROM historial "
                          "GROUP BY lower(texto) ORDER BY veces DESC, cuando DESC LIMIT ?", (limite,))

    # ------------------------------------------------------------- mantenimiento
    def compactar(self):
        with self._lock:
            # 'optimize' fusiona los índices internos de FTS5 y VACUUM reduce el archivo.
            # VACUUM no puede ejecutarse dentro de una transacción: de ahí el commit previo.
            self.con.execute("INSERT INTO fragmentos(fragmentos) VALUES('optimize')")
            self.con.commit()
            self.con.execute("VACUUM")
            self.con.commit()

    def reindexar_fts(self):
        """Reconstruye el índice FTS desde la tabla de páginas guardada (por si se corrompe)."""
        with self._lock:
            self.con.execute("INSERT INTO fragmentos(fragmentos) VALUES('rebuild')")
            self.con.commit()

    def vaciar(self, tambien_paginas=True):
        with self._lock:
            self.con.execute("DELETE FROM documentos")
            if tambien_paginas:
                self.con.execute("DELETE FROM fragmentos")
            self.con.commit()



# ================================================================================
#  MÓDULO EMBEBIDO: motor/indexador.py
# ================================================================================

"""
Indexador: recorre las carpetas del usuario, extrae el texto de cada PDF/Word
y lo guarda en la base de datos.

Pensado para 3.000+ archivos:

 * VARIOS NÚCLEOS: los archivos se leen en procesos paralelos (varios a la vez).
   Es lo que hace que una biblioteca grande tarde minutos en vez de horas.
 * Revisión incremental: si el archivo no cambió (tamaño + fecha) no se vuelve a
   leer. Al reiniciar la aplicación continúa donde quedó.
 * Una sola indexación a la vez: la revisión automática nunca se monta encima de
   una indexación en curso.
 * Nunca se detiene por un archivo dañado: lo anota y sigue; los archivos con
   error se saltan en las revisiones siguientes (Mayús+clic en Indexar los reintenta).
 * Progreso en tiempo real con tiempo restante estimado (lo usa la interfaz).
"""


import hashlib
import os
import re
import threading
import time
import unicodedata


# Cuando el usuario está buscando, la indexación se aparta un momento para no
# quitarle la memoria ni el disco: con bibliotecas grandes eso es la diferencia
# entre una búsqueda de 1 segundo y una de un minuto.
PAUSA_BUSQUEDA = threading.Event()

def tamano_legible(n):
    for u in ("B", "KB", "MB", "GB"):
        if n < 1024:
            return f"{n:.0f} {u}" if u == "B" else f"{n:.1f} {u}"
        n /= 1024
    return f"{n:.1f} TB"


IGNORAR_CARPETAS = {"$RECYCLE.BIN", "System Volume Information", "__MACOSX", ".git", "node_modules"}

# Carpetas que no tiene sentido revisar al buscar documentos (sistema, programas…)
CARPETAS_DEL_SISTEMA = {
    "windows", "program files", "program files (x86)", "programdata", "appdata",
    "recovery", "perflogs", "$winreagent", "windows.old", "onedrivetemp", "intel",
    "amd", "nvidia", "msocache", "drivers", "temp", "tmp", "proc", "sys", "dev",
    "usr", "var", "etc", "boot", "lib", "lib64", "bin", "sbin", "opt", "run",
    "mnt", "media", "snap", "lost+found", "site-packages", "python*",
}

# Por debajo de este número de archivos no vale la pena repartir el trabajo
# entre procesos (arrancarlos cuesta más que leer los archivos).
MINIMO_PARA_PROCESOS = 8

# Cuántos archivos se leen antes de renovar el grupo de procesos. El grupo se
# renueva desde aquí (NO con max_tasks_per_child: esa opción colgaba el reparto en
# algunas versiones de Python y dejaba la indexación a medias para siempre).
TAREAS_POR_TANDA = 400

# Si ningún archivo termina en este tiempo, se deja de esperar y se sigue leyendo
# de uno en uno: la indexación nunca se queda pegada.
SEGUNDOS_SIN_RESPUESTA = 300


def _slug(t: str) -> str:
    t = unicodedata.normalize("NFKD", t or "").encode("ascii", "ignore").decode()
    return re.sub(r"[^a-zA-Z0-9]+", "_", t).strip("_").lower() or "general"


def md5_archivo(ruta: str, bloque: int = 1 << 20) -> str:
    h = hashlib.md5()
    with open(ruta, "rb") as f:
        while True:
            datos = f.read(bloque)
            if not datos:
                break
            h.update(datos)
    return h.hexdigest()


def limpiar_titulo(t: str) -> str:
    t = re.sub(r"\s+", " ", t or "").strip()
    t = re.sub(r"\.(pdf|docx?|odt|txt|rtf)$", "", t, flags=re.I)
    return t


def nucleos_recomendados(pedido=0) -> int:
    """Cuántos procesos usar. 0 (automático) = hasta 8, según el procesador."""
    try:
        pedido = int(pedido or 0)
    except Exception:
        pedido = 0
    if pedido > 0:
        return max(1, min(pedido, 32))
    return max(1, min(8, os.cpu_count() or 1))


class Progreso:
    """Estado del indexado que consulta la interfaz web."""

    def __init__(self):
        self._d = {
            "activo": False, "fase": "en espera", "total": 0, "hechos": 0,
            "actual": "", "errores": [], "inicio": None, "fin": None,
            "nuevos": 0, "actualizados": 0, "omitidos": 0, "fallidos": 0,
            "caracteres": 0, "log": [],
            "sin_cambios": 0, "revisados": 0, "nucleos": 1, "restante_segundos": 0,
            "velocidad": 0, "inicio_trabajo": None, "aviso": "",
            "marca": time.time(), "carpetas_ilegibles": 0,
        }
        self._lock = threading.Lock()

    def reset(self, total=0):
        with self._lock:
            self._d.update({"activo": True, "fase": "preparando", "total": total, "hechos": 0,
                            "actual": "", "errores": [], "inicio": time.time(), "fin": None,
                            "nuevos": 0, "actualizados": 0, "omitidos": 0, "fallidos": 0,
                            "caracteres": 0, "log": [], "sin_cambios": 0, "revisados": 0,
                            "restante_segundos": 0, "velocidad": 0, "inicio_trabajo": None,
                            "aviso": ""})

    def set(self, **kw):
        with self._lock:
            self._d["marca"] = time.time()      # latido: sirve para saber si algo se atasca
            self._d.update(kw)

    def suma(self, campo, cuanto=1):
        with self._lock:
            self._d[campo] = self._d.get(campo, 0) + cuanto

    def error(self, mensaje: str):
        with self._lock:
            self._d["errores"].append(mensaje)
            self._d["errores"] = self._d["errores"][-150:]

    def vigilar(self, limite=90, cada=15):
        """
        Vigilante: si el indexado lleva más de `limite` segundos sin avanzar, lo dice
        en voz alta (con la carpeta donde se atascó Windows) en vez de parecer colgado.
        No cancela nada: solo informa. Sigue mientras el indexado esté activo.
        """
        ultimo = 0.0
        while True:
            time.sleep(cada)
            with self._lock:
                d = dict(self._d)
            if not d.get("activo"):
                return
            atascado = time.time() - d.get("marca", time.time()) > limite
            if atascado and time.time() - ultimo > 60:
                ultimo = time.time()
                donde = (d.get("actual") or d.get("fase") or "").strip()
                self.log(f"⏳ Sigo trabajando… Windows está tardando en responder por «{donde}». "
                         "La aplicación NO está trabada: no la cierres, sigue sola.")
                self.set(aviso=f"Windows está tardando en: {donde}")
            elif not atascado and d.get("aviso"):
                self.set(aviso="")

    def log(self, msg: str):
        with self._lock:
            self._d["log"].append(f"{time.strftime('%H:%M:%S')}  {msg}")
            self._d["log"] = self._d["log"][-200:]

    def leer(self):
        with self._lock:
            d = dict(self._d)
        if d["activo"] and d["inicio"]:
            d["segundos"] = round(time.time() - d["inicio"], 1)
        elif d["inicio"] and d["fin"]:
            d["segundos"] = round(d["fin"] - d["inicio"], 1)
        else:
            d["segundos"] = 0
        if d["total"]:
            d["porcentaje"] = min(100, round(d["hechos"] * 100 / d["total"], 1))
        else:
            d["porcentaje"] = 0
        # Tiempo restante estimado y velocidad (archivos por minuto)
        base = d.get("inicio_trabajo") or d["inicio"]
        if d["activo"] and base and d["hechos"] > 0 and d["total"] > d["hechos"]:
            transcurrido = time.time() - base
            por_archivo = transcurrido / d["hechos"]
            d["restante_segundos"] = int(por_archivo * (d["total"] - d["hechos"]))
            d["velocidad"] = round(60.0 / por_archivo, 1) if por_archivo > 0 else 0
        else:
            d["restante_segundos"] = 0
            d["velocidad"] = 0
        return d


class Indexador:
    def __init__(self, almacen, progreso: Progreso, carpetas_excluidas=()):
        self._repetir = None
        self._notas_inicio = []
        self._candado_pedidos = threading.Lock()
        self.db = almacen
        self.prog = progreso
        self._hilo = None
        self._candado = threading.Lock()          # una sola indexación a la vez
        # carpetas que nunca se indexan (los datos internos de la aplicación)
        self.excluidas = {os.path.abspath(c) for c in carpetas_excluidas}

    # ---------------------------------------------------------------- escaneo
    def listar_archivos(self, carpetas):
        """
        Recorre las carpetas (incluidas todas las subcarpetas) y devuelve:
            (lista de (ruta, tamaño, fecha), lista de carpetas no legibles)

        Se usa os.scandir en una sola pasada: ya trae el tamaño y la fecha, así que
        después no hay que volver a consultarlos (mucho más rápido, sobre todo en
        OneDrive). Si una carpeta no se puede leer (permisos, ruta demasiado larga en
        Windows…), se ANOTA y se avisa: antes se saltaba en silencio y sus PDF no
        aparecían nunca en la biblioteca.
        """
        encontrados = {}
        no_leidas = []
        enlaces = []          # accesos directos/uniones seguidos
        reales = set()        # rutas reales ya vistas (evita bucles)
        total_carpetas = 0
        for carpeta in carpetas:
            carpeta = os.path.abspath(os.path.expanduser(carpeta))
            if not os.path.isdir(carpeta):
                self.prog.log(f"⚠ Carpeta no encontrada: {carpeta}")
                no_leidas.append((carpeta, "la carpeta no existe o no está disponible"))
                continue
            pila = [carpeta]
            try:
                reales.add(os.path.normcase(os.path.realpath(carpeta)))
            except OSError:
                pass
            while pila:
                actual = pila.pop()
                total_carpetas += 1
                self.prog.set(fase=f"buscando archivos… {len(encontrados)} encontrados "
                                   f"({total_carpetas} carpetas revisadas)",
                              actual=f"carpeta: …{actual[-78:]}")
                try:
                    with os.scandir(ruta_io(actual)) as it:
                        for entrada in it:
                            try:
                                nombre = entrada.name
                                if nombre.startswith("."):
                                    continue
                                if entrada.is_dir(follow_symlinks=True):
                                    if nombre in IGNORAR_CARPETAS:
                                        continue
                                    if os.path.abspath(entrada.path) in self.excluidas:
                                        continue
                                    # accesos directos/uniones (OneDrive, discos externos…):
                                    # se siguen, pero solo una vez por ruta real
                                    try:
                                        real = os.path.normcase(os.path.realpath(entrada.path))
                                    except OSError:
                                        continue
                                    if real in reales:
                                        continue
                                    reales.add(real)
                                    try:
                                        if os.path.islink(entrada.path) or os.path.realpath(entrada.path) != os.path.abspath(entrada.path):
                                            enlaces.append(entrada.path)
                                    except OSError:
                                        pass
                                    pila.append(entrada.path)
                                elif entrada.is_file(follow_symlinks=False):
                                    if nombre.startswith("~$") or not es_soportado(nombre):
                                        continue
                                    try:
                                        st = entrada.stat()
                                        tam, fecha = st.st_size, st.st_mtime
                                    except OSError:
                                        tam, fecha = 0, 0
                                    clave = os.path.normcase(os.path.abspath(entrada.path))
                                    encontrados[clave] = (entrada.path, tam, fecha)
                            except OSError:
                                continue
                except PermissionError as e:
                    no_leidas.append((actual, f"sin permiso para leerla ({e.strerror or e})"))
                except OSError as e:
                    # incluye las rutas demasiado largas de Windows
                    no_leidas.append((actual, f"no se pudo leer ({e.strerror or e})"))
        if enlaces:
            self.prog.log(f"↪ Se siguieron {len(enlaces)} carpeta(s) con acceso directo "
                          f"(así sus documentos también entran).")
        if no_leidas:
            self.prog.log(f"⚠ {len(no_leidas)} carpeta(s) no se pudieron leer. "
                          "Revisa el informe en Ajustes → Comprobar qué ve la aplicación.")
            for c, motivo in no_leidas[:10]:
                self.prog.log(f"   · {c} — {motivo}")
        self.prog.set(fase=f"buscando archivos… {len(encontrados)} encontrados", actual="")
        return sorted(encontrados.values(), key=lambda x: x[0].lower()), no_leidas

    def _mapa_documentos(self):
        """Ficha de todos los documentos ya indexados, en una sola consulta."""
        mapa = {}
        for d in self.db.todos("SELECT id, ruta, tamano, modificado, estado FROM documentos"):
            try:
                mapa[os.path.normcase(os.path.abspath(d["ruta"]))] = d
            except Exception:
                continue
        return mapa

    def _clasificar(self, archivos, forzar):
        """
        Decide qué archivos hay que leer de verdad (comparando tamaño y fecha con lo
        ya guardado) y cuáles se pueden saltar. Ya no vuelve a consultar el disco:
        usa el tamaño y la fecha que trajo el escaneo (una sola pasada).
        """
        mapa = self._mapa_documentos()
        pendientes, omitidos, revisados = [], 0, 0
        total = len(archivos)
        carpeta_actual = ""
        for ruta, tam, fecha in archivos:
            revisados += 1
            if revisados % 200 == 0 or revisados == total:
                carpeta = os.path.basename(os.path.dirname(ruta))
                if carpeta != carpeta_actual:
                    carpeta_actual = carpeta
                self.prog.set(revisados=revisados, sin_cambios=omitidos, hechos=revisados, total=total,
                              fase=f"revisando cambios ({revisados} de {total})",
                              actual=f"{carpeta}/…  ·  {omitidos} sin cambios ({total - revisados} por revisar)")
            d = mapa.get(os.path.normcase(os.path.abspath(ruta)))
            if d and not forzar:
                # Los que quedaron en "error" SÍ se vuelven a intentar en cada revisión:
                # tras una mejora del lector, se arreglan solos sin que el usuario haga nada.
                if (d.get("estado") or "") != "error":
                    igual = (abs((d["tamano"] or 0) - tam) == 0
                             and abs((d["modificado"] or 0) - fecha) < 1)
                    if igual:
                        omitidos += 1
                        continue
            pendientes.append(ruta)
        self.prog.set(revisados=revisados, sin_cambios=omitidos, actual="")
        return pendientes, omitidos

    # ---------------------------------------------------------------- inventario completo
    def inventario_completo(self, carpetas, progreso=True):
        r"""
        Cuenta TODO lo que hay en las carpetas, sin límites de tiempo ni de cantidad.

        Cada carpeta elegida se cuenta POR SEPARADO (así, si tienes una carpeta y
        además una subcarpeta suya en la lista, la subcarpeta no aparece en cero):
        al final solo se avisa que una está incluida dentro de la otra para no
        sumar dos veces los mismos documentos.

        Devuelve el total, el detalle por carpeta, las carpetas que están VACÍAS de
        verdad, las que no se pudieron leer, los accesos directos seguidos, los
        documentos que están "solo en la nube" (OneDrive) y los tipos que no se leen.
        """
        def avisar(fase, actual="", **kw):
            if progreso:
                self.prog.set(fase=fase, actual=actual, **kw)

        en_indice = {os.path.normcase(os.path.abspath(d["ruta"]))
                     for d in self.db.todos("SELECT ruta FROM documentos")}

        resumen = {"total": 0, "por_carpeta": [], "vacios": [], "con_documentos": 0,
                   "carpetas_recorridas": 0, "no_leidas": [], "enlaces": [],
                   "otros": 0, "otros_tipos": {}, "sin_indexar": 0, "ignoradas": [],
                   "nube": 0, "duplicados": 0}
        configuradas = [os.path.abspath(os.path.expanduser(c)) for c in carpetas]
        vistos_totales = set()                 # solo para el TOTAL (no contar dos veces)
        vacios_vistos = set()                  # carpetas vacías sin repetir
        suma_por_carpeta = 0

        for carpeta in configuradas:
            entrada = {"carpeta": carpeta, "documentos": 0, "carpetas": 0, "vacios": 0,
                       "no_leidas": 0, "sin_indexar": 0, "otros": 0, "ejemplos_vacios": [],
                       "nube": 0, "incluida_en": ""}
            for otra in configuradas:          # ¿está dentro de otra que ya tienes?
                if otra != carpeta and (carpeta + os.sep).startswith(otra + os.sep):
                    entrada["incluida_en"] = otra
            if progreso:
                avisar("contando documentos…", f"carpeta: {carpeta}")
            if not os.path.isdir(carpeta):
                resumen["no_leidas"].append(
                    (carpeta, "la carpeta no existe ahora o Windows no la tiene disponible"))
                resumen["por_carpeta"].append(entrada)
                continue

            vistos_aqui = set()                # dedup dentro de ESTA carpeta
            reales = set()
            try:
                reales.add(os.path.normcase(os.path.realpath(carpeta)))
            except OSError:
                pass
            pila = [(carpeta, True)]
            while pila:
                actual, _ = pila.pop()
                if progreso and resumen["carpetas_recorridas"] % 50 == 0:
                    avisar("contando documentos…", f"carpeta: …{actual[-70:]}",
                           contados=resumen["total"], carpetas_contadas=resumen["carpetas_recorridas"])
                resumen["carpetas_recorridas"] += 1
                entrada["carpetas"] += 1
                tiene_algo = False
                try:
                    with os.scandir(ruta_io(actual)) as it:
                        for e in it:
                            try:
                                nombre = e.name
                                if nombre.startswith("."):
                                    continue
                                if e.is_dir(follow_symlinks=True):
                                    if nombre in IGNORAR_CARPETAS or nombre in CARPETAS_DEL_SISTEMA:
                                        resumen["ignoradas"].append(os.path.join(actual, nombre))
                                        continue
                                    try:
                                        real = os.path.normcase(os.path.realpath(e.path))
                                    except OSError:
                                        continue
                                    if real in reales:
                                        continue
                                    reales.add(real)
                                    try:
                                        if os.path.realpath(e.path) != os.path.abspath(e.path):
                                            resumen["enlaces"].append(e.path)
                                    except OSError:
                                        pass
                                    tiene_algo = True
                                    pila.append((e.path, False))
                                elif e.is_file(follow_symlinks=True):
                                    if not es_soportado(nombre):
                                        if not nombre.startswith("~$"):
                                            resumen["otros"] += 1
                                            entrada["otros"] += 1
                                            ext = os.path.splitext(nombre)[1].lower() or "(sin extensión)"
                                            resumen["otros_tipos"][ext] = resumen["otros_tipos"].get(ext, 0) + 1
                                        continue
                                    tiene_algo = True
                                    clave = os.path.normcase(os.path.abspath(e.path))
                                    if clave in vistos_aqui:       # mismo archivo por dos caminos
                                        continue
                                    vistos_aqui.add(clave)
                                    entrada["documentos"] += 1
                                    nube = solo_en_la_nube(e)
                                    if nube:
                                        entrada["nube"] += 1
                                    sin_leer = clave not in en_indice
                                    if sin_leer:
                                        entrada["sin_indexar"] += 1
                                    if clave not in vistos_totales:
                                        vistos_totales.add(clave)
                                        resumen["total"] += 1
                                        if nube:
                                            resumen["nube"] += 1
                                        if sin_leer:
                                            resumen["sin_indexar"] += 1
                            except OSError:
                                continue
                except OSError as e:
                    resumen["no_leidas"].append((actual, f"no se pudo leer ({e.strerror or e})"))
                    entrada["no_leidas"] += 1
                    continue
                if not tiene_algo:
                    # carpeta sin archivos legibles ni subcarpetas con nada
                    entrada["vacios"] += 1
                    if len(entrada["ejemplos_vacios"]) < 12:
                        entrada["ejemplos_vacios"].append(actual)
                    clave_vacia = os.path.normcase(actual)
                    if clave_vacia not in vacios_vistos:
                        vacios_vistos.add(clave_vacia)
                        if len(resumen["vacios"]) < 400:
                            resumen["vacios"].append(actual)
                else:
                    resumen["con_documentos"] += 1
            suma_por_carpeta += entrada["documentos"]
            resumen["por_carpeta"].append(entrada)
            if progreso:
                avisar("contando documentos…", f"{carpeta}",
                       contados=resumen["total"], carpetas_contadas=resumen["carpetas_recorridas"])

        resumen["duplicados"] = max(0, suma_por_carpeta - resumen["total"])
        resumen["por_carpeta"].sort(key=lambda x: -x["documentos"])
        resumen["otros_tipos"] = dict(sorted(resumen["otros_tipos"].items(),
                                             key=lambda x: -x[1])[:10])
        if progreso:
            avisar("conteo terminado", "", contados=resumen["total"],
                   carpetas_contadas=resumen["carpetas_recorridas"])
        return resumen

    def informe_inventario(self, inv, indexados):
        """Informe de texto, listo para leer o enviar por correo."""
        L = []
        L.append("=" * 74)
        L.append("   INFORME DE CARPETAS DE LA BIBLIOTECA DIGITAL")
        L.append(f"   {time.strftime('%d/%m/%Y %H:%M')}")
        L.append("=" * 74)
        L.append("")
        L.append(f"  Documentos PDF/Word encontrados en tus carpetas : {inv['total']}")
        L.append(f"  Documentos que ya están en la biblioteca        : {indexados}")
        L.append(f"  FALTAN POR INDEXAR                               : {max(0, inv['total'] - indexados)}")
        L.append(f"  Carpetas recorridas                              : {inv['carpetas_recorridas']}")
        L.append(f"  Carpetas con documentos                          : {inv['con_documentos']}")
        L.append(f"  Carpetas VACÍAS (sin documentos por dentro)      : {len(inv['vacios'])}")
        if inv["otros"]:
            tipos = ", ".join(f"{n} {e}" for e, n in inv["otros_tipos"].items())
            L.append(f"  Archivos de tipos que NO se leen                 : {inv['otros']}  ({tipos})")
        if inv["enlaces"]:
            L.append(f"  Carpetas con acceso directo (se siguieron)       : {len(inv['enlaces'])}")
        if inv.get("duplicados"):
            L.append(f"  (No se cuentan dos veces: {inv['duplicados']} documento(s) están en más "
                     "de una carpeta de tu lista.)")
        if inv.get("nube"):
            L.append(f"  Documentos que están SOLO EN LA NUBE (OneDrive)  : {inv['nube']}")
            L.append("      Windows no los tiene descargados: clic derecho sobre la carpeta en")
            L.append("      OneDrive → «Mantener siempre en este dispositivo» y volver a indexar.")
        L.append("")
        L.append("-" * 74)
        L.append("  DETALLE POR CARPETA (las que tú elegiste)")
        L.append("-" * 74)
        for c in inv["por_carpeta"]:
            L.append(f"  {c['carpeta']}")
            L.append(f"      {c['documentos']} documento(s) · {c['carpetas']} carpeta(s) por dentro"
                     f" · {c['vacios']} vacía(s) · {c['sin_indexar']} sin indexar"
                     + (f" · {c['otros']} de otros tipos" if c["otros"] else ""))
            if c.get("incluida_en"):
                L.append(f"      (Esta carpeta está DENTRO de {c['incluida_en']}: sus documentos ya "
                         "se cuentan allí, aquí no se repiten.)")
            if c.get("nube"):
                L.append(f"      {c['nube']} documento(s) de esta carpeta están solo en la nube "
                         "(OneDrive, sin descargar).")
            if c["ejemplos_vacios"]:
                L.append("      carpetas vacías, por ejemplo:")
                for v in c["ejemplos_vacios"][:6]:
                    L.append(f"         · {v}")
        if inv["no_leidas"]:
            L.append("")
            L.append("-" * 74)
            L.append("  CARPETAS QUE NO SE PUDIERON LEER (sus documentos NO entran)")
            L.append("-" * 74)
            for c, motivo in inv["no_leidas"][:40]:
                L.append(f"  · {c}  —  {motivo}")
        if inv["enlaces"]:
            L.append("")
            L.append("-" * 74)
            L.append("  CARPETAS CON ACCESO DIRECTO (unión/symlink) QUE SE SIGUIERON")
            L.append("-" * 74)
            for c in inv["enlaces"][:40]:
                L.append(f"  · {c}")
        if inv["ignoradas"]:
            L.append("")
            L.append(f"  (Se ignoraron {len(inv['ignoradas'])} carpeta(s) de sistema o temporales, "
                     "como $RECYCLE.BIN o node_modules.)")
        L.append("")
        L.append("=" * 74)
        return chr(10).join(L)

    # ---------------------------------------------------------------- toda la PC
    def _raices_del_equipo(self):
        """Unidades donde buscar: en Windows, todos los discos; en otros, la raíz."""
        if os.name != "nt":
            return ["/"]
        raices = []
        for letra in "CDEFGHIJKLMNOPQRSTUVWXYZ":
            if os.path.exists(f"{letra}:\\"):
                raices.append(f"{letra}:\\")
        return raices or ["C:\\"]

    def rastrear_documentos_en_la_pc(self, progreso=True, presupuesto=300.0,
                                     max_carpetas=500000, raices=None):
        r"""
        Recorre TODA la PC (todos los discos) y busca las carpetas que tienen
        documentos PDF/Word, sin necesidad de que estén en la lista.

        Devuelve el total de documentos del equipo y una lista de las carpetas
        más grandes (con cuántos documentos tiene cada una), para poder agregarlas
        a la biblioteca con un clic. Se salta las carpetas de sistema y avisa de
        las que no se pudieron leer y de los documentos que están "solo en la nube".
        """
        import string  # noqa: F401
        def avisar(fase, actual="", **kw):
            if progreso:
                self.prog.set(fase=fase, actual=actual, **kw)

        raices = raices or self._raices_del_equipo()
        t0 = time.time()
        directos, arbol = {}, {}          # documentos directos / en todo el árbol
        no_leidas, ignoradas = [], []
        nube, revisadas, total = 0, 0, 0
        completo = True

        reales = set()                    # anti-bucle: un acceso directo no se sigue dos veces
        for raiz in raices:
            raiz = os.path.abspath(raiz)
            try:
                reales.add(os.path.normcase(os.path.realpath(raiz)))
            except OSError:
                pass
            pila = [(raiz, 0)]
            while pila:
                if time.time() - t0 > presupuesto or revisadas > max_carpetas:
                    completo = False
                    break
                actual, estado = pila.pop()
                if estado:                                     # saliendo: suma al padre
                    arbol[os.path.dirname(actual)] = (arbol.get(os.path.dirname(actual), 0)
                                                      + arbol.get(actual, 0))
                    continue
                revisadas += 1
                if revisadas % 200 == 0:
                    avisar("buscando documentos en tu PC…", f"carpeta: …{actual[-70:]}",
                           contados=total, carpetas_contadas=revisadas)
                pila.append((actual, 1))                        # volver a pasar al salir
                aqui = 0
                try:
                    with os.scandir(ruta_io(actual)) as it:
                        for e in it:
                            try:
                                nombre = e.name
                                if nombre.startswith(".") or nombre in IGNORAR_CARPETAS:
                                    continue
                                if e.is_dir(follow_symlinks=True):
                                    if nombre.lower() in CARPETAS_DEL_SISTEMA:
                                        ignoradas.append(e.path)
                                        continue
                                    if os.name == "nt":
                                        try:
                                            a = e.stat(follow_symlinks=False).st_file_attributes
                                            if a & 0x2 or a & 0x4:      # oculta o de sistema
                                                ignoradas.append(e.path)
                                                continue
                                        except OSError:
                                            pass
                                    try:
                                        real = os.path.normcase(os.path.realpath(e.path))
                                    except OSError:
                                        continue
                                    if real in reales:
                                        continue
                                    reales.add(real)
                                    pila.append((e.path, 0))
                                elif e.is_file(follow_symlinks=True):
                                    if not es_soportado(nombre) or nombre.startswith("~$"):
                                        continue
                                    aqui += 1
                                    total += 1
                                    if solo_en_la_nube(e):
                                        nube += 1
                            except OSError:
                                continue
                except OSError as e:
                    no_leidas.append((actual, f"no se pudo leer ({e.strerror or e})"))
                    continue
                directos[actual] = directos.get(actual, 0) + aqui
                arbol[actual] = arbol.get(actual, 0) + aqui

        avisar("buscando documentos en tu PC…", contados=total, carpetas_contadas=revisadas)

        # --- lista de carpetas: las más grandes primero, sin repetir las que ya
        #     están dentro de otra que también se muestra
        en_tu_lista = [os.path.abspath(os.path.expanduser(c))
                       for c in (getattr(self, "ajustes", {}).get("carpetas") or [])]
        # Se muestran las carpetas donde los documentos VIVEN (tienen archivos
        # dentro), empezando por las que más documentos tienen por dentro. Así,
        # si tus PDF están en C:\BibliotecaDigital\Estudios, esa carpeta aparece
        # arriba aunque nunca la hayas agregado a la lista.
        candidatos = []
        for ruta, propios in directos.items():
            if propios <= 0:
                continue
            if len(os.path.normpath(ruta)) <= 3:               # la raíz de un disco
                continue
            if os.path.basename(ruta).lower() in CARPETAS_DEL_SISTEMA:
                continue
            candidatos.append((arbol.get(ruta, propios), propios, ruta))
        candidatos.sort(key=lambda x: (-x[0], len(x[2])))
        elegidas, usadas = [], []
        for cuantos, propios, ruta in candidatos:
            if len(elegidas) >= 40:
                break
            if any((ruta + os.sep).startswith(u + os.sep) for u in usadas):
                continue                                       # ya está dentro de otra mostrada
            usadas.append(ruta)
            ya = any(ruta == c or (ruta + os.sep).startswith(c + os.sep) for c in en_tu_lista)
            elegidas.append({"carpeta": ruta, "documentos": cuantos,
                             "directos": propios, "en_tu_lista": ya})

        if progreso:
            avisar("búsqueda terminada", "", contados=total, carpetas_contadas=revisadas)
        return {"total": total, "carpetas": elegidas, "carpetas_revisadas": revisadas,
                "carpetas_con_documentos": sum(1 for v in arbol.values() if v > 0),
                "no_leidas": no_leidas, "ignoradas": len(ignoradas), "nube": nube,
                "completo": completo, "segundos": round(time.time() - t0, 1),
                "raices": raices, "en_tu_lista": en_tu_lista}

    def informe_rastreo(self, r, indexados):
        """Informe de la búsqueda en toda la PC (para leer o enviar)."""
        L = []
        L.append("=" * 74)
        L.append("   BÚSQUEDA EN TODA LA PC — BIBLIOTECA DIGITAL")
        L.append(f"   {time.strftime('%d/%m/%Y %H:%M')}")
        L.append("=" * 74)
        L.append("")
        L.append(f"  Documentos PDF/Word que hay en tu PC  : {r['total']}")
        L.append(f"  Documentos que ya están en la biblioteca : {indexados}")
        L.append(f"  Carpetas revisadas                     : {r['carpetas_revisadas']}")
        L.append(f"  Carpetas con documentos                : {r['carpetas_con_documentos']}")
        L.append(f"  Discos/unidades revisados              : {', '.join(r['raices'])}")
        L.append(f"  Tiempo                                 : {r['segundos']} segundos")
        if not r["completo"]:
            L.append("  (La búsqueda se cortó por tiempo antes de terminar toda la PC:")
            L.append("   vuelve a pulsar el botón para seguir buscando.)")
        if r["nube"]:
            L.append(f"  Documentos que están SOLO EN LA NUBE (OneDrive) : {r['nube']}")
            L.append("      Windows no los tiene descargados: hay que hacer clic derecho")
            L.append("      sobre la carpeta en OneDrive y elegir «Mantener siempre en este")
            L.append("      dispositivo», y volver a indexar.")
        L.append("")
        L.append("-" * 74)
        L.append("  CARPETAS CON DOCUMENTOS (las más grandes primero)")
        L.append("-" * 74)
        for c in r["carpetas"]:
            marca = "  [ya está en tu lista]" if c["en_tu_lista"] else ""
            L.append(f"  {c['documentos']:>7} documento(s) por dentro ({c['directos']} aquí mismo)"
                     f"  {c['carpeta']}{marca}")
        L.append("")
        L.append("  Para agregar una: Ajustes → «📁 Buscar la CARPETA MADRE en mi PC…»")
        L.append("  (o pulsa «➕ Agregar a la biblioteca» en la ventana de la aplicación).")
        if r["no_leidas"]:
            L.append("")
            L.append("-" * 74)
            L.append("  CARPETAS QUE WINDOWS NO DEJÓ LEER")
            L.append("-" * 74)
            for c, motivo in r["no_leidas"][:40]:
                L.append(f"  · {c}  —  {motivo}")
        L.append("")
        L.append("=" * 74)
        return chr(10).join(L)

    # ---------------------------------------------------------------- carpetas vecinas
    def _contar_soportados(self, carpeta, limite=6000):
        """Cuenta rápido los documentos que la biblioteca puede leer dentro de una carpeta."""
        n, vistos = 0, 0
        pila = [carpeta]
        while pila and vistos < limite:
            actual = pila.pop()
            try:
                with os.scandir(ruta_io(actual)) as it:
                    for e in it:
                        vistos += 1
                        try:
                            if e.is_dir(follow_symlinks=False):
                                if not e.name.startswith(".") and e.name not in IGNORAR_CARPETAS:
                                    pila.append(e.path)
                            elif e.is_file(follow_symlinks=False):
                                if not e.name.startswith("~$") and es_soportado(e.name):
                                    n += 1
                        except OSError:
                            continue
            except OSError:
                continue
            if vistos >= limite:
                break
        return n

    def _parece_carpeta_de_la_app(self, carpeta):
        """¿Esta carpeta es (o contiene) la propia aplicación? (entonces no se toca)."""
        for nombre in ("BibliotecaDigital.py", "biblioteca.py", "ABRIR_BIBLIOTECA.bat",
                       "Iniciar_Biblioteca.bat", "diagnostico.bat"):
            if os.path.exists(os.path.join(carpeta, nombre)):
                return True
        datos = os.path.join(carpeta, "datos")
        return os.path.isdir(datos) and os.path.exists(os.path.join(datos, "ajustes.json"))

    def carpetas_vecinas(self, carpetas, tope_hermanas=60, minimo_iguales=1):
        """
        Carpetas que están AL LADO de las configuradas (misma carpeta madre) y que
        tienen documentos sin indexar.

        Es lo que resuelve el caso típico: el usuario ya eligió sus carpetas una vez y
        después guarda documentos nuevos en una carpeta nueva al lado de aquellas.
        """
        def cubierta(ruta):
            r = os.path.normcase(os.path.abspath(ruta))
            for c in carpetas:
                k = os.path.normcase(os.path.abspath(c))
                if r == k or r.startswith(k + os.sep):
                    return True
            return False

        casa = os.path.normcase(os.path.expanduser("~"))
        padres = {}
        for c in carpetas:
            c = os.path.abspath(c)
            p = os.path.dirname(c.rstrip(os.sep))
            if not p or p == c:                       # es una raíz de unidad (C:\)
                continue
            if len(p) <= 3:                           # "C:\" o "\\"
                continue
            if os.path.normcase(p) == casa:           # no meter la carpeta del usuario entera
                continue
            if cubierta(p):                           # el padre ya se indexa: nada que buscar
                continue
            if self._parece_carpeta_de_la_app(p):     # el padre es la carpeta de la aplicación
                continue
            # cuántas carpetas configuradas son hijas directas de este padre
            iguales = sum(1 for o in carpetas
                          if os.path.normcase(os.path.dirname(os.path.abspath(o).rstrip(os.sep)))
                          == os.path.normcase(p))
            if iguales < minimo_iguales:
                continue
            if os.path.normcase(p) not in padres:
                padres[os.path.normcase(p)] = (p, iguales)

        resultado = []
        for p, iguales in padres.values():
            try:
                with os.scandir(ruta_io(p)) as it:
                    hijos = [e for e in it
                             if e.is_dir(follow_symlinks=False)
                             and not e.name.startswith(".")
                             and e.name not in IGNORAR_CARPETAS
                             and e.name.lower() not in ("datos", "biblioteca", "node_modules",
                                                        "windows", "appdata", "$recycle.bin")]
            except OSError:
                continue
            if len(hijos) > tope_hermanas:            # carpeta madre enorme: mejor no adivinar
                continue
            for e in hijos:
                if cubierta(e.path) or self._parece_carpeta_de_la_app(e.path):
                    continue
                n = self._contar_soportados(e.path)
                if n:
                    resultado.append({"carpeta": os.path.abspath(e.path), "documentos": n,
                                      "en": p, "iguales": iguales})
        # primero las que son hermanas de una carpeta madre de verdad (varias carpetas
        # configuradas al mismo nivel), y entre esas, las que más documentos tienen
        resultado.sort(key=lambda v: (-v.get("iguales", 0), -v["documentos"]))
        return resultado

    # ---------------------------------------------------------------- carpetas sin indexar
    def _contar_con_presupuesto(self, carpeta, segundos=0.4, tope=4000):
        """Cuenta documentos con un límite de tiempo (para no quedarse pegado)."""
        fin = time.monotonic() + segundos
        n = vistos = 0
        pila = [carpeta]
        while pila and vistos < tope and time.monotonic() < fin:
            actual = pila.pop()
            try:
                with os.scandir(ruta_io(actual)) as it:
                    for e in it:
                        vistos += 1
                        try:
                            if e.is_dir(follow_symlinks=False):
                                if not e.name.startswith(".") and e.name not in IGNORAR_CARPETAS \
                                        and e.name.lower() not in CARPETAS_DEL_SISTEMA:
                                    pila.append(e.path)
                            elif e.is_file(follow_symlinks=False):
                                if not e.name.startswith("~$") and es_soportado(e.name):
                                    n += 1
                        except OSError:
                            continue
                        if vistos >= tope or time.monotonic() > fin:
                            break
            except OSError:
                continue
        return n

    def carpetas_no_indexadas_cerca(self, carpetas, lugares, presupuesto=8.0, minimo=5):
        r"""
        Busca carpetas CON documentos que no están en la lista que se indexa.

        Mira en los sitios habituales (la unidad del equipo, la carpeta del usuario,
        Documentos, Escritorio, Descargas, OneDrive y las carpetas de arriba de las
        configuradas) hasta 2 niveles de profundidad. Sirve para el caso típico:
        el usuario guardó sus documentos en una carpeta nueva que la aplicación no
        conoce (por ejemplo C:\BibliotecaDigital\Estudios).
        """
        def cubierta(ruta):
            r = os.path.normcase(os.path.abspath(ruta))
            for c in carpetas:
                k = os.path.normcase(os.path.abspath(c))
                if r == k or r.startswith(k + os.sep):
                    return True
            return False

        fin = time.monotonic() + presupuesto
        encontradas = {}
        revisadas = 0
        for lugar, niveles in lugares:
            if time.monotonic() > fin:
                break
            if not os.path.isdir(lugar):
                continue
            pendientes = [(os.path.abspath(lugar), 0)]
            while pendientes and time.monotonic() < fin:
                actual, nivel = pendientes.pop()
                if nivel >= niveles:
                    continue
                try:
                    with os.scandir(ruta_io(actual)) as it:
                        hijos = []
                        for e in it:
                            try:
                                if not e.is_dir(follow_symlinks=False):
                                    continue
                                if e.name.startswith(".") or e.name in IGNORAR_CARPETAS:
                                    continue
                                if e.name.lower() in CARPETAS_DEL_SISTEMA or "*" in e.name.lower():
                                    continue
                                hijos.append(e.path)
                            except OSError:
                                continue
                except OSError:
                    continue
                if len(hijos) > 300:          # carpeta enorme: no perder tiempo aquí
                    continue
                for hijo in hijos:
                    if time.monotonic() > fin:
                        break
                    revisadas += 1
                    if cubierta(hijo) or self._parece_carpeta_de_la_app(hijo):
                        continue
                    n = self._contar_con_presupuesto(hijo, segundos=0.35)
                    if n >= minimo:
                        clave = os.path.normcase(os.path.abspath(hijo))
                        if clave not in encontradas or n > encontradas[clave]["documentos"]:
                            encontradas[clave] = {"carpeta": os.path.abspath(hijo),
                                                  "documentos": n, "en": actual}
                        continue                  # ya tiene documentos: no hace falta bajar más
                    if nivel + 1 < niveles:
                        pendientes.append((hijo, nivel + 1))
        # se queda con la carpeta MÁS ARRIBA de cada grupo: si encontró
        # "...\Estudios" y también "...\Estudios\DR WSS", solo sirve la primera
        configuradas = [os.path.normcase(os.path.abspath(c)) for c in carpetas]
        resultado = sorted(encontradas.values(), key=lambda v: -v["documentos"])
        elegidas = []
        for v in resultado:
            r = os.path.normcase(os.path.abspath(v["carpeta"]))
            if any(r == os.path.normcase(e["carpeta"]) or
                   r.startswith(os.path.normcase(e["carpeta"]) + os.sep) for e in elegidas):
                continue
            # si ya indexa parte de esa carpeta, no se propone (sería repetir trabajo)
            if any(c.startswith(r + os.sep) for c in configuradas):
                continue
            elegidas.append(v)
        return elegidas[:12]

    # ---------------------------------------------------------------- diagnóstico
    def diagnostico(self, carpetas):
        """
        Informe de lo que la aplicación VE en cada carpeta configurada: cuántos
        PDF/Word hay, cuántos de ellos YA están en el índice y cuántos faltan,
        qué tipos de archivo no se pueden leer (zip, rar…) y qué carpetas no se
        pudieron abrir. Es la radiografía para saber dónde están los documentos
        que no aparecen en la biblioteca.
        """
        en_indice = {os.path.normcase(os.path.abspath(d["ruta"]))
                     for d in self.db.todos("SELECT ruta FROM documentos")}
        informe = []
        for carpeta in carpetas:
            carpeta = os.path.abspath(os.path.expanduser(carpeta))
            info = {"carpeta": carpeta, "existe": os.path.isdir(carpeta), "archivos": 0,
                    "peso": 0, "subcarpetas": 0, "por_tipo": {}, "recientes": [],
                    "problemas": [], "sin_indexar": 0, "sin_indexar_peso": 0,
                    "ejemplos_sin_indexar": [], "otros": 0, "otros_tipos": {},
                    "ignoradas": []}
            if not info["existe"]:
                info["problemas"].append("La carpeta no existe o no está disponible ahora mismo.")
                informe.append(info)
                continue
            pila = [carpeta]
            recientes = []
            faltantes = []
            while pila:
                actual = pila.pop()
                info["subcarpetas"] += 1
                try:
                    with os.scandir(ruta_io(actual)) as it:
                        for entrada in it:
                            try:
                                nombre = entrada.name
                                if nombre.startswith("."):
                                    if nombre not in (".", ".."):
                                        info["ignoradas"].append(os.path.join(actual, nombre))
                                    continue
                                if entrada.is_dir(follow_symlinks=False):
                                    if nombre in IGNORAR_CARPETAS:
                                        info["ignoradas"].append(os.path.join(actual, nombre))
                                        continue
                                    pila.append(entrada.path)
                                elif entrada.is_file(follow_symlinks=False):
                                    if not es_soportado(nombre):
                                        if not nombre.startswith("~$"):
                                            info["otros"] += 1
                                            e2 = (os.path.splitext(nombre)[1].lower() or "(sin extensión)")
                                            info["otros_tipos"][e2] = info["otros_tipos"].get(e2, 0) + 1
                                        continue
                                    ext = os.path.splitext(nombre)[1].lower()
                                    info["por_tipo"][ext] = info["por_tipo"].get(ext, 0) + 1
                                    info["archivos"] += 1
                                    try:
                                        st = entrada.stat()
                                    except OSError:
                                        st = None
                                    if st is not None:
                                        info["peso"] += st.st_size
                                        recientes.append((st.st_mtime, tamano_legible(st.st_size),
                                                          entrada.path, st.st_size))
                                    if os.path.normcase(os.path.abspath(entrada.path)) not in en_indice:
                                        info["sin_indexar"] += 1
                                        if st is not None:
                                            info["sin_indexar_peso"] += st.st_size
                                            faltantes.append((st.st_mtime,
                                                              tamano_legible(st.st_size),
                                                              entrada.path))
                            except OSError:
                                continue
                except OSError as e:
                    info["problemas"].append(f"No se pudo leer esta subcarpeta: {actual} "
                                             f"({e.strerror or e})")
            recientes.sort(reverse=True)
            faltantes.sort(reverse=True)
            info["recientes"] = [{"fecha": time.strftime("%d/%m/%Y %H:%M", time.localtime(f)),
                                  "peso": p, "ruta": r} for f, p, r, _ in recientes[:8]]
            info["ejemplos_sin_indexar"] = [
                {"fecha": time.strftime("%d/%m/%Y %H:%M", time.localtime(f)), "peso": p,
                 "ruta": r, "nombre": os.path.basename(r)} for f, p, r in faltantes[:10]]
            informe.append(info)
        return informe

    # ---------------------------------------------------------------- indexación
    def indexar(self, carpetas, forzar=False, borrar_desaparecidos=False,
                coleccion_por="carpeta", nucleos=0):
        if not self._candado.acquire(blocking=False):
            with self._candado_pedidos:
                self._repetir = {"carpetas": carpetas, "forzar": forzar,
                                 "borrar_desaparecidos": borrar_desaparecidos,
                                 "coleccion_por": coleccion_por, "nucleos": nucleos}
            self.prog.log("⏳ Ya hay una indexación en curso: se repetirá sola al terminar.")
            return False
        try:
            hecho = self._indexar_todo(carpetas, forzar, borrar_desaparecidos, coleccion_por, nucleos)
        finally:
            self._candado.release()
        # Lo que se buscó antes de indexar ya puede estar viejo: se olvida la
        # memoria de búsquedas para que la próxima traiga lo nuevo. Y se le pide
        # a la base de datos que estudie sus índices (ANALYZE): con la biblioteca
        # recién indexada, las búsquedas eligen el plan más rápido.
        try:
            self.db.olvidar_cache_busquedas()
        except Exception:
            pass
        try:
            self.db.analizar()
        except Exception:
            pass
        # Al terminar se avisa (la aplicación aprovecha para guardar una copia
        # de seguridad del índice, sin que el usuario tenga que hacer nada).
        if hecho:
            try:
                avisar = getattr(self, "al_terminar", None)
                if avisar:
                    avisar()
            except Exception:
                pass
        return hecho

    def _indexar_todo(self, carpetas, forzar, borrar_desaparecidos, coleccion_por, nucleos):
        t0 = time.time()
        self.prog.reset()
        self.prog.set(activo=True, fase="buscando archivos", inicio=t0, fin=None, aviso="")
        notas, self._notas_inicio = self._notas_inicio, []
        for nota in notas:
            self.prog.log(nota)
        threading.Thread(target=self.prog.vigilar, daemon=True).start()
        self.prog.log(f"Explorando {len(carpetas)} carpeta(s) (se incluyen todas las subcarpetas)…")
        archivos, no_leidas = self.listar_archivos(carpetas)
        raices = [os.path.abspath(os.path.expanduser(c)) for c in carpetas]
        self.raices = list(raices)          # se recuerdan para clasificar por carpeta
        self.prog.set(total=len(archivos), carpetas_ilegibles=len(no_leidas))
        self.prog.log(f"Se encontraron {len(archivos)} documentos PDF/Word compatibles "
                      f"en {len(carpetas)} carpeta(s).")
        if no_leidas:
            self.prog.log("⚠ Hay carpetas que no se pudieron leer (sus archivos NO entran):")
            for c, motivo in no_leidas[:10]:
                self.prog.log(f"   · {c} — {motivo}")

        # ---- 1) ¿qué cambió? (solo mira tamaño y fecha: es inmediato) ----------
        self.prog.set(fase="revisando cambios", inicio_trabajo=time.time())
        pendientes, omitidos = self._clasificar(archivos, forzar)
        self.prog.log(f"{omitidos} documento(s) sin cambios (no se vuelven a leer). "
                      f"{len(pendientes)} por leer.")
        if forzar:
            self.prog.log("Reindexación completa pedida: se leen todos los archivos.")

        # ---- 2) lectura del texto (aquí está el trabajo pesado) ---------------
        cuantos = nucleos_recomendados(nucleos)
        if len(pendientes) < MINIMO_PARA_PROCESOS or cuantos <= 1:
            cuantos = 1
        self.prog.set(total=len(pendientes), hechos=0, fase="indexando",
                      inicio_trabajo=time.time(), nucleos=cuantos)
        if pendientes:
            if cuantos > 1:
                self.prog.log(f"Usando {cuantos} núcleos del procesador: se leen {cuantos} archivos a la vez.")
            else:
                self.prog.log("Usando 1 núcleo del procesador.")

        vistos = {os.path.normcase(os.path.abspath(r)) for r, _, _ in archivos}
        hechos = 0
        # Si falta el lector de PDF no se puede leer NINGÚN PDF: mejor detenerse con un
        # aviso claro que llenar la biblioteca de tarjetas "error".
        if pendientes and not estado_lector_pdf()["disponible"]:
            pdfs = sum(1 for r in pendientes if falta_lector_pdf(r))
            if pdfs:
                self.prog.set(aviso=estado_lector_pdf()["mensaje"])
                self.prog.log("✖ NO SE PUEDE LEER PDF: falta el lector (pypdf).")
                self.prog.log(f"   Hay {pdfs} PDF pendientes; NO se marcaron con error: se leerán "
                              "en cuanto el lector esté instalado.")
                self.prog.log("   Solución: cierra la aplicación, ábrela otra vez (lo intenta "
                              "instalar sola) o ejecuta:  python -m pip install pypdf")
                pendientes = [r for r in pendientes if not falta_lector_pdf(r)]
        if pendientes:
            generador = (self._leer_en_procesos(pendientes, cuantos) if cuantos > 1
                         else self._leer_uno_por_uno(pendientes))
            for ruta, datos in generador:
                if PAUSA_BUSQUEDA.is_set():         # el usuario está buscando: le dejamos paso
                    limite = time.monotonic() + 8.0
                    while PAUSA_BUSQUEDA.is_set() and time.monotonic() < limite:
                        time.sleep(0.08)
                vistos.add(os.path.normcase(os.path.abspath(ruta)))
                hechos += 1
                self.prog.set(actual=os.path.basename(ruta), hechos=hechos)
                if datos.get("ok"):
                    self._guardar(ruta, datos, raices, coleccion_por)
                    if datos.get("aviso"):
                        self.prog.log(f"⚠ {os.path.basename(ruta)}: {datos['aviso'][:110]}")
                else:
                    self._guardar_error(ruta, datos.get("error") or "error desconocido",
                                        datos.get("tamano"), datos.get("modificado"))
        self.prog.set(actual="", hechos=len(pendientes))

        # ---- 3) archivos que ya no están en disco -----------------------------
        # PROTECCIÓN: nunca se marca en masa. Si de golpe "faltan" muchísimos
        # documentos (por ejemplo porque la lista de carpetas quedó corta), NO se
        # toca nada: se avisa y se deja que el usuario arregle las carpetas.
        if borrar_desaparecidos:
            candidatos = []
            for d in self.db.todos("SELECT id, ruta FROM documentos"):
                if os.path.normcase(os.path.abspath(d["ruta"])) in vistos:
                    continue
                try:
                    if os.path.exists(d["ruta"]):
                        continue
                except OSError:
                    continue
                candidatos.append(d)
            total_en_base = (self.db.contar() or {}).get("n") or 0
            limite = max(25, int(total_en_base * 0.02))
            if candidatos and len(candidatos) > limite:
                self.prog.log(f"🛡 No marqué nada como 'desaparecido': faltan {len(candidatos)} "
                              f"documento(s) de golpe y eso casi siempre significa que en Ajustes "
                              f"falta alguna carpeta. Revisa la lista de carpetas y vuelve a pulsar "
                              f"Indexar (nada se ha borrado).")
                self.prog.set(desaparecidos_grandes=len(candidatos))
            else:
                n = 0
                for d in candidatos:
                    self.db.actualizar_documento(d["id"], {"estado": "desaparecido"})
                    n += 1
                if n:
                    self.prog.log(f"⚠ {n} documento(s) ya no están en su carpeta: marcados como "
                                  f"'desaparecido' (vuelven solos si el archivo reaparece).")

        # ---- 3b) los que volvieron -------------------------------------------
        try:
            devueltos = 0
            for d in self.db.todos("SELECT id, ruta FROM documentos WHERE estado='desaparecido'"):
                try:
                    if os.path.exists(d["ruta"]) and os.path.getsize(d["ruta"]) > 0:
                        self.db.actualizar_documento(d["id"], {"estado": "ok"})
                        devueltos += 1
                except OSError:
                    continue
            if devueltos:
                self.prog.log(f"↩ {devueltos} documento(s) que estaban fuera volvieron a la "
                              f"biblioteca (su archivo ya está en su carpeta).")
        except Exception:
            pass

        # ---- 4) comprobación final: ¿quedó algo del disco fuera de la biblioteca? ---
        try:
            guardados = {os.path.normcase(os.path.abspath(d["ruta"]))
                         for d in self.db.todos("SELECT ruta FROM documentos")}
            faltan = len(vistos - guardados)
            self.prog.set(faltan_del_disco=faltan)
            if faltan:
                self.prog.log(f"⚠ {faltan} archivo(s) del disco NO entraron a la biblioteca "
                              "(los que están en rojo tienen error). Pulsa Indexar otra vez; "
                              "si siguen faltando, Ajustes → Comprobar qué ve la aplicación.")
            else:
                self.prog.log("Comprobado: TODO lo que hay en las carpetas está en la biblioteca ✔")
        except Exception as e:
            self.prog.log(f"(no se pudo hacer la comprobación final: {e})")

        p = self.prog.leer()
        self.prog.log(f"✔ Terminado en {self._duracion(time.time() - t0)} — "
                      f"{p['nuevos']} nuevos, {p['actualizados']} actualizados, "
                      f"{p['omitidos']} sin cambios, {p['fallidos']} con error.")
        if p["fallidos"]:
            self.prog.log("Los archivos que dieron error se vuelven a intentar solos en la próxima "
                          "revisión (así, cuando el lector mejora, se arreglan sin hacer nada).")
        self.prog.set(activo=False, fase="listo", fin=time.time())
        return True

    # ------------------------------------------------- lectura del texto
    def _leer_uno_por_uno(self, pendientes):
        for ruta in pendientes:
            yield ruta, self._preparar_uno(ruta)

    def _preparar_uno(self, ruta):
        # preparar_archivo viene del módulo de trabajadores (arriba)
        return preparar_archivo((ruta, True))

    def _leer_en_procesos(self, pendientes, cuantos):
        """
        Lee varios archivos a la vez, en tandas.

        El grupo de procesos se renueva cada TAREAS_POR_TANDA archivos (así la
        memoria se mantiene baja). Si el sistema no permite crear procesos, o si
        alguna vez se queda sin responder, se continúa de uno en uno: NUNCA se cuelga.
        """
        try:
            import multiprocessing as mp
            from concurrent.futures import ProcessPoolExecutor, wait, FIRST_COMPLETED
            contexto = mp.get_context("spawn")     # igual en Windows, Linux y Mac
        except Exception as e:
            self.prog.log(f"⚠ No se pudieron usar varios núcleos ({e}); sigo con uno solo.")
            yield from self._leer_uno_por_uno(pendientes)
            return

        hechos = set()

        def leer_lo_que_falte(motivo=""):
            if motivo:
                self.prog.log(motivo)
            for ruta in pendientes:
                if os.path.normcase(os.path.abspath(ruta)) in hechos:
                    continue
                datos = self._preparar_uno(ruta)
                hechos.add(os.path.normcase(os.path.abspath(ruta)))
                yield ruta, datos

        i = 0
        try:
            while i < len(pendientes):
                tanda = pendientes[i:i + TAREAS_POR_TANDA]
                i += len(tanda)
                with ProcessPoolExecutor(max_workers=cuantos, mp_context=contexto) as pool:
                    futuros = {pool.submit(preparar_archivo, (ruta, True)): ruta for ruta in tanda}
                    en_curso = set(futuros)
                    ultimo = time.time()
                    avisado = False
                    while en_curso:
                        listos, en_curso = wait(en_curso, timeout=20, return_when=FIRST_COMPLETED)
                        if not listos:
                            espera = time.time() - ultimo
                            if espera > 120 and not avisado:
                                avisado = True
                                self.prog.log("⏳ Algún archivo está tardando mucho (PDF muy grande o dañado). "
                                              "Sigo con los demás; no hay que hacer nada.")
                            if espera > SEGUNDOS_SIN_RESPUESTA:
                                raise TimeoutError(f"{cuantos} archivo(s) sin responder después de "
                                                   f"{int(SEGUNDOS_SIN_RESPUESTA)} s")
                            continue
                        ultimo = time.time()
                        avisado = False
                        for fut in listos:
                            ruta = futuros[fut]
                            try:
                                datos = fut.result()
                            except Exception as e:
                                datos = {"ruta": ruta, "ok": False, "tamano": 0, "modificado": 0,
                                         "md5": "", "caracteres": 0, "paginas": [],
                                         "error": f"{type(e).__name__}: {e}"}
                            hechos.add(os.path.normcase(os.path.abspath(ruta)))
                            yield ruta, datos
        except Exception as e:
            # Nunca se abandona el trabajo: se termina lo que falte de uno en uno.
            yield from leer_lo_que_falte(
                f"⚠ Se interrumpió el trabajo en varios núcleos ({type(e).__name__}). "
                "Continúo con lo que falta, de uno en uno.")

    @staticmethod
    def _duracion(seg):
        seg = int(seg)
        if seg < 60:
            return f"{seg} s"
        if seg < 3600:
            return f"{seg // 60} min {seg % 60} s"
        return f"{seg // 3600} h {(seg % 3600) // 60} min"

    def _coleccion(self, ruta: str, raices, modo: str) -> str:
        """Nombre de la colección:
             'carpeta' -> la subcarpeta inmediata donde vive el archivo (Contratos, Facturas…)
             'ruta'    -> la ruta relativa completa desde la carpeta raíz (2024/Contratos)
        """
        carpeta = os.path.dirname(os.path.abspath(ruta))
        if modo == "ruta":
            for raiz in raices:
                try:
                    rel = os.path.relpath(carpeta, raiz)
                except Exception:
                    continue
                if not rel.startswith(".."):
                    if rel == ".":
                        return os.path.basename(raiz)
                    return rel.replace("\\", "/")
        # se respeta el nombre EXACTO de la carpeta (WSS, ENZ, WMB…), sin forzar
        # mayúscula inicial: así las casillas de arriba y las colecciones coinciden
        base = os.path.basename(carpeta)
        return base if base else "General"

    def _guardar(self, ruta: str, datos: dict, raices, coleccion_por: str):
        """Guarda (o actualiza) en la base de datos el resultado de un archivo."""
        ruta_abs = os.path.abspath(ruta)
        doc = self.db.documento_por_ruta(ruta_abs)
        paginas = [p for p in datos["paginas"] if p["texto"].strip()]
        caracteres = datos.get("caracteres", 0)

        # --- colección: la decide la carpeta (o la ruta) -----------------------
        automatica = self._coleccion(ruta_abs, raices, coleccion_por)
        # la carpeta de PRIMER NIVEL (WSS, ENZ, WMB…): la usan las casillas de arriba
        # La carpeta madre de la biblioteca manda (la pone la aplicación al
        # arrancar la indexación): así «carpeta1» sale ENZ · WSS · WMB aunque en
        # Ajustes haya muchas subcarpetas (años, meses, DOCWPE…).
        principal = Almacen.carpeta_principal(ruta_abs, raices,
                                              madre=getattr(self, "madre", None))
        if doc and doc.get("categoria_manual"):
            categoria = doc["categoria"]            # la escribió el usuario: se respeta
        else:
            categoria = automatica

        titulo = datos.get("titulo") or titulo_aparente(datos["paginas"], os.path.basename(ruta_abs))
        titulo = limpiar_titulo(titulo)[:180]
        if doc and doc.get("titulo") and doc.get("estado") in ("ok", "sin_texto"):
            titulo = doc["titulo"]          # se respeta el título que escribió el usuario

        etiquetas = doc["etiquetas"] if doc else ""
        nota = datos.get("aviso") or (doc["nota"] if doc else "") or ""
        estado = "ok" if paginas else "sin_texto"

        campos = {
            "carpeta": os.path.dirname(ruta_abs),
            "nombre": os.path.basename(ruta_abs),
            "extension": os.path.splitext(ruta_abs)[1].lower(),
            "tipo": tipo_archivo(ruta_abs),
            "tamano": datos.get("tamano") or 0,
            "modificado": datos.get("modificado") or 0,
            "md5": datos.get("md5") or (doc["md5"] if doc else ""),
            "titulo": titulo,
            # r28-d · el encabezado del propio PDF («Tomo 14 Digital», etc.): lo que
            # el usuario ve arriba del documento y quiere ver en la previsualización.
            "encabezado": (encabezado_de(datos.get("paginas") or []) or "")[:200],
            "autor": (doc["autor"] if (doc and doc.get("autor")) else None) or datos.get("autor") or "",
            "etiquetas": etiquetas,
            "anio": (doc["anio"] if (doc and doc.get("anio")) else None) or datos.get("anio") or "",
            "paginas": datos.get("paginas_total", len(datos["paginas"])),
            "caracteres": caracteres,
            "estado": estado,
            "nota": nota,
            "indexado": ahora(),
        }
        campos["categoria"] = categoria
        campos["carpeta1"] = principal          # la carpeta de primer nivel (WSS, ENZ…)

        if doc:
            self.db.actualizar_documento(doc["id"], campos)
            doc_id = doc["id"]
            self.prog.suma("actualizados")
        else:
            campos["ruta"] = ruta_abs
            doc_id = self.db.crear_documento(campos)
            self.prog.suma("nuevos")

        self.db.guardar_fragmentos(doc_id, paginas)
        self.prog.suma("caracteres", caracteres)

    def _raices_actuales(self):
        """Las carpetas madre de la corrida en curso (o las guardadas en Ajustes)."""
        return list(getattr(self, "raices", None) or [])

    def _guardar_error(self, ruta: str, mensaje: str, tamano=0, modificado=0):
        """
        Anota el archivo que no se pudo leer, CON su tamaño y fecha, para que las
        revisiones siguientes no lo vuelvan a intentar (se reintenta con
        Mayús+clic en Indexar).
        """
        ruta_abs = os.path.abspath(ruta)
        nombre = os.path.basename(ruta_abs)
        self.prog.suma("fallidos")
        self.prog.error(f"{nombre}: {mensaje}")
        self.prog.log(f"✖ {nombre}: {mensaje}")
        try:
            doc = self.db.documento_por_ruta(ruta_abs)
            campos = {
                "carpeta": os.path.dirname(ruta_abs), "nombre": nombre,
                "extension": os.path.splitext(ruta_abs)[1].lower(),
                "tipo": tipo_archivo(ruta_abs),
                "tamano": tamano or 0, "modificado": modificado or 0,
                "titulo": limpiar_titulo(nombre)[:180],
                "paginas": 0, "caracteres": 0,
                "estado": "error", "nota": str(mensaje)[:300], "indexado": ahora(),
            }
            if doc:
                self.db.actualizar_documento(doc["id"], campos)
                self.db.guardar_fragmentos(doc["id"], [])
            else:
                campos["ruta"] = ruta_abs
                campos["categoria"] = self._coleccion(ruta_abs, (), "carpeta")
                campos["carpeta1"] = Almacen.carpeta_principal(
                    ruta_abs, self._raices_actuales(), madre=getattr(self, "madre", None))
                campos["etiquetas"] = ""
                campos["autor"] = ""
                campos["anio"] = ""
                campos["md5"] = ""
                self.db.crear_documento(campos)
        except Exception as e:
            self.prog.log(f"⚠ No se pudo anotar el error de {nombre}: {e}")

    # ---------------------------------------------------------------- hilo
    def anotar(self, mensaje: str):
        """Mensaje que se mostrará al empezar el próximo indexado (el registro se limpia)."""
        self._notas_inicio.append(mensaje)

    def indexar_en_segundo_plano(self, carpetas, forzar=False, borrar_desaparecidos=False,
                                 coleccion_por="carpeta", nucleos=0):
        """
        Lanza el indexado sin bloquear la interfaz. Si ya hay uno en curso, NO se
        pierde el pedido: se anota y se repite automáticamente al terminar el actual
        (antes, pulsar Indexar durante una corrida larga no hacía nada y parecía que
        "no agregaba los archivos nuevos").
        """
        if self.prog.leer()["activo"]:
            with self._candado_pedidos:
                self._repetir = {"carpetas": carpetas, "forzar": forzar,
                                 "borrar_desaparecidos": borrar_desaparecidos,
                                 "coleccion_por": coleccion_por, "nucleos": nucleos}
            self.prog.log("⏳ Ya hay una indexación en curso: se repetirá sola al terminar.")
            return False
        with self._candado_pedidos:
            self._repetir = None
        self._hilo = threading.Thread(
            target=self._indexar_encadenado,
            args=(carpetas, forzar, borrar_desaparecidos, coleccion_por, nucleos),
            daemon=True)
        self._hilo.start()
        return True

    def _indexar_encadenado(self, carpetas, forzar, borrar_desaparecidos, coleccion_por, nucleos):
        """Corre el indexado y, si quedó un pedido pendiente, lo repite al terminar."""
        try:
            self.indexar(carpetas, forzar, borrar_desaparecidos, coleccion_por, nucleos)
        finally:
            with self._candado_pedidos:
                repetir, self._repetir = self._repetir, None
            if repetir:
                # se anota ANTES de arrancar (el nuevo indexado limpia el registro)
                self.anotar("↻ Había otra pulsación de Indexar esperando: "
                            "se repite ahora para no perderla.")
                self._indexar_encadenado(repetir["carpetas"], repetir["forzar"],
                                         repetir["borrar_desaparecidos"],
                                         repetir["coleccion_por"], repetir["nucleos"])



# ================================================================================
#  MÓDULO EMBEBIDO: motor/copiloto.py
# ================================================================================

r"""
COPILOTO · el ayudante de las búsquedas.

Qué hace (y qué NO hace):

  · AYUDA A BUSCAR: mirando lo que hay escrito en SUS documentos, propone
    búsquedas mejores (añadir una palabra para afinar, cambiar a otra parecida
    cuando no hay resultados, buscar solo en una carpeta…). Cada propuesta sale
    con su botón «Aceptar»: hasta que el usuario no lo pulse, la pantalla NO
    cambia — ni el texto del buscador, ni los filtros, ni los resultados.
  · APRENDE SOLA: va leyendo sus documentos por su cuenta (de a pocos, cuando la
    aplicación está tranquila) y se queda con las palabras y con las que suelen
    aparecer juntas. Cuanto más lee, mejores son sus propuestas. Eso solo guarda
    lo aprendido en su propio archivo (datos\copiloto.db): no cambia ni una ficha
    de la biblioteca, ni un archivo del disco.
  · DEJA RASTRO: todo queda apuntado en datos\COPILOTO.txt (qué aprendió, qué
    propuso, qué aceptó y qué descartó), para poder revisarlo.

Funciona sin internet, como el resto de la aplicación.
"""
import os
import re
import sqlite3
import threading
import time
import unicodedata

# Palabras que no vale la pena aprender (artículos, preposiciones, verbos muy comunes…).
PARADAS = {
    "para", "porque", "pero", "como", "cuando", "donde", "quien", "quienes", "esta", "este",
    "esto", "estos", "estas", "esos", "esas", "aquel", "aquella", "muy", "mas", "menos",
    "todo", "toda", "todos", "todas", "otro", "otra", "otros", "otras", "mismo", "misma",
    "ser", "son", "era", "eran", "fue", "fueron", "sea", "sean", "sido", "siendo", "esta",
    "estan", "estaba", "estaban", "hay", "habia", "habian", "haber", "hace", "hacen", "hizo",
    "hacia", "desde", "hasta", "entre", "sobre", "bajo", "ante", "tras", "sino", "tambien",
    "tampoco", "solo", "sola", "solos", "solas", "aqui", "alli", "entonces", "ahora", "luego",
    "despues", "antes", "siempre", "nunca", "jamas", "cada", "cual", "cuales", "nada", "nadie",
    "algo", "alguien", "algun", "alguna", "algunos", "algunas", "ningun", "ninguna", "pues",
    "porque", "puesto", "ademas", "aunque", "mientras", "segun", "contra", "mediante", "dice",
    "dijo", "dicen", "decir", "hacer", "hizo", "hacen", "puede", "pueden", "podia", "podian",
    "debe", "deben", "debia", "tiene", "tienen", "tenia", "tenian", "vamos", "van", "ver",
    "visto", "dado", "dicha", "dicho", "parte", "cosas", "cosa", "modo", "forma", "manera",
    "caso", "casos", "ejemplo", "veces", "vez", "año", "años", "mes", "meses", "dia", "dias",
    "hora", "horas", "semana", "semanas", "siglo", "siglos", "numero", "numeros", "pagina",
    "paginas", "texto", "linea", "lineas", "capitulo", "libro", "libros", "obra", "obras",
    "usted", "ustedes", "nosotros", "ellos", "ellas", "ustedes", "senor", "senora", "don",
    "dona", "santo", "santa", "reverendo", "hermano", "hermanos", "hermana", "hermanas",
    "amigo", "amigos", "pueblo", "pueblos", "gente", "persona", "personas", "hombre",
    "hombres", "mujer", "mujeres", "hijo", "hijos", "hija", "hijas", "padre", "madre",
    "tierra", "cielo", "mundo", "vida", "muerte", "nombre", "nombres", "palabra", "palabras",
}

_LETRAS = re.compile(r"^[a-z][a-z0-9]{2,23}$")


def _sin_acentos(t: str) -> str:
    t = unicodedata.normalize("NFKD", (t or "").lower())
    return "".join(c for c in t if not unicodedata.combining(c))


def palabras_de(texto: str, minimo: int = 4) -> list:
    """Las palabras «de verdad» de un texto: sin acentos, sin repetir, en orden."""
    salida, vistas = [], set()
    for bruta in re.findall(r"[A-Za-zÁÉÍÓÚÜÑáéíóúüñ0-9]{3,24}", texto or ""):
        p = _sin_acentos(bruta)
        if not _LETRAS.match(p) or p in PARADAS or p in vistas:
            continue
        if len(p) < minimo or p.isdigit():
            continue
        vistas.add(p)
        salida.append(p)
    return salida


def _contar_palabras(texto: str) -> dict:
    cuenta = {}
    for p in palabras_de(texto):
        cuenta[p] = cuenta.get(p, 0) + 1
    return cuenta


def frase_fts(palabras) -> str:
    """Arma la consulta FTS5 segura para una o varias palabras (frase exacta)."""
    partes = []
    for p in ([palabras] if isinstance(palabras, str) else list(palabras)):
        p = (p or "").strip().replace('"', " ").strip()
        if p:
            partes.append('"' + p + '"')
    return " AND ".join(partes)


class Copiloto:
    """El asistente. Lee la biblioteca (solo lectura) y guarda lo aprendido aparte."""

    MAXIMO_RELACIONES = 400000        # tope, para que la base no crezca sin freno
    MAXIMO_TERMINOS_POR_DOC = 28      # las palabras que se guardan de cada documento
    TOPE_CARACTERES_DOC = 60000       # de cada documento se lee como mucho esto

    def __init__(self, datos_dir: str, db=None, ocupado=None, avisar=None):
        self.datos = datos_dir
        self.ruta = os.path.join(datos_dir, "copiloto.db")
        self.ruta_informe = os.path.join(datos_dir, "COPILOTO.txt")
        self.db = db                       # la base de la biblioteca: SOLO se lee
        self.ocupado = ocupado             # función que dice si la app está trabajando
        self.avisar = avisar or (lambda _m: None)
        self._candado = threading.Lock()
        self._parar = threading.Event()
        self._hilo = None
        self._estado = {"activo": False, "fase": "", "leidos": 0, "total": 0,
                        "terminos": 0, "relaciones": 0, "auto": True}
        try:
            os.makedirs(datos_dir, exist_ok=True)
        except OSError:
            pass
        self._crear_tablas()

    # ------------------------------------------------------------------ base propia
    def _con(self):
        c = sqlite3.connect(self.ruta, timeout=15)
        c.row_factory = sqlite3.Row
        try:
            c.execute("PRAGMA journal_mode=WAL")
        except sqlite3.Error:
            pass
        return c

    def _crear_tablas(self):
        try:
            with self._con() as c:
                c.executescript("""
CREATE TABLE IF NOT EXISTS terminos (
    t        TEXT PRIMARY KEY,
    veces    INTEGER DEFAULT 0,
    docs     INTEGER DEFAULT 0,
    ultima   TEXT DEFAULT ''
);
CREATE TABLE IF NOT EXISTS relaciones (
    a        TEXT NOT NULL,
    b        TEXT NOT NULL,
    peso     REAL DEFAULT 0,
    PRIMARY KEY (a, b)
);
CREATE INDEX IF NOT EXISTS idx_rel_a ON relaciones(a);
CREATE TABLE IF NOT EXISTS doc_terminos (
    doc_id   INTEGER NOT NULL,
    t        TEXT NOT NULL,
    n        INTEGER DEFAULT 1,
    PRIMARY KEY (doc_id, t)
);
CREATE INDEX IF NOT EXISTS idx_dt_doc ON doc_terminos(doc_id);
CREATE TABLE IF NOT EXISTS leidos (
    doc_id   INTEGER PRIMARY KEY,
    cuando   TEXT DEFAULT ''
);
CREATE TABLE IF NOT EXISTS diario (
    id       INTEGER PRIMARY KEY AUTOINCREMENT,
    cuando   TEXT,
    tipo     TEXT,
    detalle  TEXT
);
CREATE TABLE IF NOT EXISTS ajustes (clave TEXT PRIMARY KEY, valor TEXT);
-- r28-d · LAS «FORMAS» DE BUSCAR: cómo suele buscar el usuario (una palabra,
-- una frase, varias palabras, en qué modo…). De aquí salen las propuestas de
-- «esto lo haces siempre igual: ¿te dejo un botón?».
CREATE TABLE IF NOT EXISTS formas (
    forma  TEXT PRIMARY KEY, veces INTEGER DEFAULT 0,
    ultima TEXT DEFAULT '', ejemplo TEXT DEFAULT '');
-- lo que el usuario REPITE (contador de búsquedas iguales) …
CREATE TABLE IF NOT EXISTS repes (
    q TEXT PRIMARY KEY, veces INTEGER DEFAULT 0,
    ultima TEXT DEFAULT '', modo TEXT DEFAULT '');
-- … y los BOTONES de búsqueda que ha ACEPTADO (nada se guarda sin aceptar)
CREATE TABLE IF NOT EXISTS botones (
    q TEXT PRIMARY KEY, veces INTEGER DEFAULT 0,
    creado TEXT DEFAULT '', modo TEXT DEFAULT '');
""")
        except sqlite3.Error as e:
            self.avisar(f"⚠ El copiloto no pudo preparar su archivo: {e}")

    def _ajuste(self, clave, valor=None):
        with self._con() as c:
            if valor is None:
                f = c.execute("SELECT valor FROM ajustes WHERE clave=?", (clave,)).fetchone()
                return f["valor"] if f else ""
            c.execute("INSERT INTO ajustes(clave, valor) VALUES(?,?) "
                      "ON CONFLICT(clave) DO UPDATE SET valor=excluded.valor", (clave, str(valor)))
            return valor

    def _anotar(self, tipo: str, detalle: str):
        """Apunta en el diario del copiloto (y en datos\\COPILOTO.txt)."""
        cuando = time.strftime("%Y-%m-%d %H:%M:%S")
        try:
            with self._con() as c:
                c.execute("INSERT INTO diario(cuando, tipo, detalle) VALUES(?,?,?)",
                          (cuando, tipo, str(detalle)[:600]))
        except sqlite3.Error:
            pass
        try:
            nuevo = not os.path.exists(self.ruta_informe)
            with open(self.ruta_informe, "a", encoding="utf-8") as f:
                if nuevo:
                    f.write("COPILOTO · lo que aprende y lo que propone\n")
                    f.write("==========================================\n\n")
                    f.write("El copiloto NO cambia nada solo: aprende leyendo sus documentos\n")
                    f.write("y propone búsquedas; se aplica lo que usted acepte.\n\n")
                f.write(f"[{cuando}] {tipo}: {str(detalle)[:600]}\n")
            # que el archivo no crezca sin fin
            if os.path.getsize(self.ruta_informe) > 400_000:
                with open(self.ruta_informe, encoding="utf-8", errors="replace") as f:
                    lineas = f.readlines()
                with open(self.ruta_informe, "w", encoding="utf-8") as f:
                    f.write("COPILOTO · (últimas líneas)\n\n")
                    f.writelines(lineas[-1500:])
        except OSError:
            pass

    # ------------------------------------------------------------------ lo aprendido
    def cuantos(self) -> dict:
        try:
            with self._con() as c:
                t = c.execute("SELECT COUNT(*) n FROM terminos").fetchone()["n"]
                r = c.execute("SELECT COUNT(*) n FROM relaciones").fetchone()["n"]
                d = c.execute("SELECT COUNT(*) n FROM doc_terminos").fetchone()["n"]
                le = c.execute("SELECT COUNT(*) n FROM leidos").fetchone()["n"]
                ult = c.execute("SELECT MAX(cuando) u FROM leidos").fetchone()["u"] or ""
            return {"terminos": t, "relaciones": r, "doc_terminos": d, "documentos_leidos": le,
                    "ultima": ult}
        except sqlite3.Error:
            return {"terminos": 0, "relaciones": 0, "doc_terminos": 0, "documentos_leidos": 0,
                    "ultima": ""}

    def total_documentos(self) -> int:
        try:
            f = self.db.todos("SELECT COUNT(*) n FROM documentos") if self.db else []
            return int(f[0]["n"]) if f else 0
        except Exception:
            return 0

    def resumen(self) -> dict:
        d = self.cuantos()
        d.update({"formas": self.formas(5), "botones": self.botones(),
                  "modo_por_defecto": self._ajuste("modo_por_defecto") or "",
                  "activo": bool(self._estado.get("activo")),
                  "fase": self._estado.get("fase", ""),
                  "auto": str(self._ajuste("auto") or "1") == "1",
                  "total_documentos": self.total_documentos(),
                  "informe": self.ruta_informe})
        return d

    # ------------------------------------------------------------------ aprender
    def _documentos_por_leer(self, cuantos: int) -> list:
        """
        Los documentos que todavía no ha leído.

        OJO (fallo que tuvo y se arregló): la lista de los ya leídos vive en el
        archivo PROPIO del copiloto (datos/copiloto.db), no en el de la
        biblioteca: si se pregunta por ella con la conexión de la biblioteca, la
        consulta falla y el copiloto cree que ya leyó todo (y no aprende nada).
        Por eso se leen aquí los identificadores ya vistos y se descartan después.
        """
        if not self.db:
            return []
        try:
            with self._con() as c:
                ya = {int(f["doc_id"]) for f in c.execute("SELECT doc_id FROM leidos")}
        except sqlite3.Error:
            ya = set()
        try:
            filas = self.db.todos("SELECT id, titulo, nombre FROM documentos ORDER BY id")
        except Exception as e:
            self.avisar(f"(el copiloto no pudo leer la lista de documentos: {e})")
            return []
        pendientes = []
        for f in filas:
            try:
                if int(f["id"]) in ya:
                    continue
            except (TypeError, ValueError):
                continue
            pendientes.append(f)
            if len(pendientes) >= int(cuantos):
                break
        return pendientes

    def _texto_de(self, doc_id: int) -> str:
        try:
            trozos = self.db.todos("SELECT texto FROM fragmentos WHERE doc_id=? LIMIT 20",
                                   (int(doc_id),))
        except Exception:
            return ""
        return "\n".join(str(t["texto"] or "") for t in trozos)[:self.TOPE_CARACTERES_DOC]

    def aprender(self, cuantos: int = 20, quien: str = "sola") -> dict:
        """
        Lee un puñado de documentos y se queda con sus palabras y con las que van
        juntas. Devuelve lo que aprendió. NO toca la biblioteca ni el disco.
        """
        if not self.db:
            return {"ok": False, "error": "el copiloto no tiene la biblioteca a mano"}
        cuantos = max(1, min(int(cuantos or 20), 200))
        pendientes = self._documentos_por_leer(cuantos)
        if not pendientes:
            self._anotar("aprendizaje", "ya había leído todo lo que hay indexado")
            return {"ok": True, "leidos": 0, "terminos_nuevos": 0, "relaciones_nuevas": 0,
                    "nota": "ya había leído todo"}
        leidos, terminos_nuevos, relaciones_nuevas = 0, 0, 0
        cuando = time.strftime("%Y-%m-%d %H:%M")
        for fila in pendientes:
            doc_id = int(fila["id"])
            texto = self._texto_de(doc_id)
            cuenta = _contar_palabras(texto) if texto else {}
            if cuenta:
                # las palabras de más peso de ESTE documento (para las relaciones)
                mejores = sorted(cuenta.items(), key=lambda x: (-x[1], x[0]))[:self.MAXIMO_TERMINOS_POR_DOC]
                try:
                    with self._con() as c:
                        for p, n in cuenta.items():
                            c.execute("INSERT INTO terminos(t, veces, docs, ultima) VALUES(?,?,1,?) "
                                      "ON CONFLICT(t) DO UPDATE SET veces=veces+excluded.veces, "
                                      "docs=docs+1, ultima=excluded.ultima", (p, n, cuando))
                        for p, n in mejores:
                            c.execute("INSERT INTO doc_terminos(doc_id, t, n) VALUES(?,?,?) "
                                      "ON CONFLICT(doc_id, t) DO UPDATE SET n=excluded.n",
                                      (doc_id, p, n))
                        for i in range(len(mejores)):
                            for j in range(i + 1, len(mejores)):
                                a, b = mejores[i][0], mejores[j][0]
                                c.execute("INSERT INTO relaciones(a, b, peso) VALUES(?,?,1) "
                                          "ON CONFLICT(a, b) DO UPDATE SET peso=peso+1", (a, b))
                                c.execute("INSERT INTO relaciones(a, b, peso) VALUES(?,?,1) "
                                          "ON CONFLICT(a, b) DO UPDATE SET peso=peso+1", (b, a))
                        c.execute("INSERT INTO leidos(doc_id, cuando) VALUES(?,?) "
                                  "ON CONFLICT(doc_id) DO NOTHING", (doc_id, cuando))
                except sqlite3.Error as e:
                    self.avisar(f"(el copiloto no pudo guardar lo del documento {doc_id}: {e})")
                    continue
                terminos_nuevos += len(cuenta)
                relaciones_nuevas += len(mejores) * max(0, len(mejores) - 1)
            else:
                try:
                    with self._con() as c:
                        c.execute("INSERT INTO leidos(doc_id, cuando) VALUES(?,?) "
                                  "ON CONFLICT(doc_id) DO NOTHING", (doc_id, cuando))
                except sqlite3.Error:
                    pass
            leidos += 1
        self._recortar_si_hace_falta()
        d = self.cuantos()
        self._estado.update({"leidos": d["documentos_leidos"], "terminos": d["terminos"],
                             "relaciones": d["relaciones"]})
        self._anotar("aprendizaje",
                     f"leyó {leidos} documento(s) ({quien}); ya sabe {d['terminos']:,} palabras "
                     f"y {d['relaciones']:,} relaciones; lleva {d['documentos_leidos']:,} "
                     f"de {self.total_documentos():,} documento(s)".replace(",", "."))
        return {"ok": True, "leidos": leidos, "terminos_nuevos": terminos_nuevos,
                "relaciones_nuevas": relaciones_nuevas, **d}

    def _recortar_si_hace_falta(self):
        """Si hay demasiadas relaciones, se quedan las más fuertes (no crece sin freno)."""
        try:
            with self._con() as c:
                n = c.execute("SELECT COUNT(*) n FROM relaciones").fetchone()["n"]
                if n <= self.MAXIMO_RELACIONES:
                    return
                c.execute("DELETE FROM relaciones WHERE rowid IN ("
                          "SELECT rowid FROM relaciones ORDER BY peso ASC LIMIT ?)",
                          (int(n - self.MAXIMO_RELACIONES * 0.8),))
                self._anotar("limpieza", f"se quedó con las relaciones más fuertes ({n} → "
                                         f"{self.MAXIMO_RELACIONES})")
        except sqlite3.Error:
            pass

    # ------------------------------------------------------------------ aprender sola
    def arrancar(self):
        """El hilo que la hace crecer sola (lee de a poquito cuando no se usa la app)."""
        if self._hilo and self._hilo.is_alive():
            return
        self._parar.clear()
        self._hilo = threading.Thread(target=self._bucle, daemon=True,
                                      name="copiloto-aprende")
        self._hilo.start()
        self._anotar("arranque", "el copiloto se pone a aprender solo (de a poquito)")

    def parar(self):
        self._parar.set()

    def _bucle(self):
        primera = True
        while not self._parar.is_set():
            espera = 8 if primera else 45
            primera = False
            for _ in range(int(espera * 2)):
                if self._parar.is_set():
                    return
                time.sleep(0.5)
            try:
                # OJO: si todavía no hay nada guardado, _ajuste devuelve "" y eso
                # significa «sí» (viene encendido de fábrica). Comparar con "1" a
                # secas hacía que el copiloto NO aprendiera nunca solo.
                if str(self._ajuste("auto") or "1") != "1":
                    continue
                if self.ocupado and self.ocupado():
                    continue                     # indexando o buscando: no molestar
                d = self.cuantos()
                if d["documentos_leidos"] >= self.total_documentos() > 0:
                    time.sleep(240)              # ya está al día: se repasa de vez en cuando
                    continue
                self._estado["activo"] = True
                self._estado["fase"] = "aprendiendo de sus documentos…"
                try:
                    self.aprender(20, quien="sola")
                finally:
                    self._estado["activo"] = False
                    self._estado["fase"] = ""
            except Exception as e:                # nunca puede tumbar la aplicación
                self._estado["activo"] = False
                self.avisar(f"(el copiloto se tropezó aprendiendo: {e})")
                time.sleep(30)

    def auto(self, encender: bool) -> dict:
        self._ajuste("auto", "1" if encender else "0")
        self._anotar("ajuste", f"aprender sola: {'SÍ' if encender else 'NO'}")
        return {"ok": True, "auto": bool(encender)}

    # ------------------------------------------------------------------ contar en la biblioteca
    def contar(self, palabras, carpeta: str = "") -> int:
        """Documentos de la biblioteca que traen esas palabras (rápido y con tope)."""
        if not self.db:
            return 0
        consulta = frase_fts(palabras)
        if not consulta:
            return 0
        try:
            filas = self.db.todos(
                "SELECT COUNT(*) n FROM (SELECT doc_id FROM fragmentos WHERE fragmentos MATCH ? "
                "LIMIT 500)", (consulta,))
            return int(filas[0]["n"]) if filas else 0
        except Exception:
            return 0

    # ------------------------------------------------------------------ sugerir
    def _parientes(self, palabras, cuantos: int = 8) -> list:
        """Las palabras que suelen salir junto a estas, en SUS documentos."""
        if not palabras:
            return []
        marcas = ",".join("?" * len(palabras))
        try:
            with self._con() as c:
                filas = c.execute(
                    f"SELECT b, SUM(peso) p FROM relaciones WHERE a IN ({marcas}) "
                    f"GROUP BY b ORDER BY p DESC LIMIT ?", (*palabras, int(cuantos))).fetchall()
            return [(f["b"], float(f["p"])) for f in filas]
        except sqlite3.Error:
            return []

    def _palabras_de_los_resultados(self, palabras, cuantos: int = 6) -> list:
        """
        Mira los documentos que MEJOR responden a la búsqueda y saca las palabras
        que MÁS se repiten dentro de ellos: son buenas candidatas para afinar.
        """
        if not self.db:
            return []
        consulta = frase_fts(palabras)
        if not consulta:
            return []
        try:
            filas = self.db.todos(
                "SELECT doc_id, COUNT(*) n FROM fragmentos WHERE fragmentos MATCH ? "
                "GROUP BY doc_id ORDER BY n DESC LIMIT 40", (consulta,))
        except Exception:
            return []
        ids = [int(f["doc_id"]) for f in filas]
        if not ids:
            return []
        marcas = ",".join("?" * len(ids))
        try:
            with self._con() as c:
                suyos = c.execute(
                    f"SELECT t, SUM(n) n FROM doc_terminos WHERE doc_id IN ({marcas}) "
                    f"GROUP BY t ORDER BY n DESC LIMIT 60", tuple(ids)).fetchall()
        except sqlite3.Error:
            return []
        ya = set(palabras)
        salida = []
        for f in suyos:
            if f["t"] in ya:
                continue
            salida.append((f["t"], int(f["n"])))
            if len(salida) >= cuantos:
                break
        return salida

    def _mejor_documento(self, palabras):
        """El documento que MÁS veces trae esas palabras (con su nombre)."""
        if not self.db:
            return None
        consulta = frase_fts(palabras)
        if not consulta:
            return None
        try:
            filas = self.db.todos(
                "SELECT doc_id, COUNT(*) n FROM fragmentos WHERE fragmentos MATCH ? "
                "GROUP BY doc_id ORDER BY n DESC LIMIT 1", (consulta,))
        except Exception:
            return None
        if not filas:
            return None
        try:
            doc = self.db.todos("SELECT id, nombre, titulo, paginas FROM documentos WHERE id=?",
                                (int(filas[0]["doc_id"]),))
        except Exception:
            return None
        if not doc:
            return None
        d = doc[0]
        return {"id": int(d["id"]), "nombre": str(d["nombre"] or ""),
                "titulo": str(d["titulo"] or d["nombre"] or ""),
                "n": int(filas[0]["n"])}

    def parecidas(self, palabra: str, cuantas: int = 5) -> list:
        """
        Palabras de SUS documentos que se parecen a esta (por si está mal escrita).

        Se buscan en lo que el copiloto ya aprendió las que empiezan igual o
        acaban igual, y se ordenan por parecido de verdad (difflib). Así, escribir
        «investimxnto» ofrece «investimento» — que es lo que el usuario quería.
        """
        palabra = _sin_acentos(palabra or "")
        if len(palabra) < 4:
            return []
        candidatos = {}
        try:
            with self._con() as c:
                for largo in (7, 6, 5, 4):
                    if len(palabra) <= largo:
                        continue
                    for f in c.execute("SELECT t, veces FROM terminos WHERE t LIKE ? "
                                       "ORDER BY veces DESC LIMIT 60",
                                       (palabra[:largo] + "%",)):
                        candidatos[f["t"]] = candidatos.get(f["t"], 0) + int(f["veces"] or 1)
                if len(palabra) >= 5:
                    for f in c.execute("SELECT t, veces FROM terminos WHERE t LIKE ? "
                                       "ORDER BY veces DESC LIMIT 60",
                                       ("%" + palabra[-4:],)):
                        candidatos[f["t"]] = candidatos.get(f["t"], 0) + int(f["veces"] or 1)
        except sqlite3.Error:
            return []
        import difflib
        salida = []
        for t in candidatos:
            if t == palabra:
                continue
            r = difflib.SequenceMatcher(None, palabra, t).ratio()
            if r >= 0.6:
                salida.append((t, r, candidatos[t]))
        salida.sort(key=lambda x: (-x[1], -x[2]))
        return [t for t, _r, _v in salida[:cuantas]]

    def _variantes(self, palabras) -> list:
        """Otras formas de escribir lo mismo que SÍ podrían estar en sus documentos."""
        salida = []
        for p in palabras:
            if len(p) < 4:
                continue
            if p.endswith("s"):
                salida.append(p[:-1])
            else:
                salida.append(p + "s")
            # la «h» muda y la «b/v» y «c/z/s» cambian mucho en textos viejos
            if p.startswith("h"):
                salida.append(p[1:])
            else:
                salida.append("h" + p)
            if "v" in p:
                salida.append(p.replace("v", "b", 1))
            if "b" in p:
                salida.append(p.replace("b", "v", 1))
            if "z" in p:
                salida.append(p.replace("z", "c", 1))
            if "c" in p:
                salida.append(p.replace("c", "s", 1))
            if "i" in p and "y" not in p:
                salida.append(p.replace("i", "y", 1))
            if "y" in p:
                salida.append(p.replace("y", "i", 1))
        vistas, limpias = set(), []
        for v in salida:
            if v and v not in vistas and len(v) >= 4 and not v.isdigit():
                vistas.add(v)
                limpias.append(v)
        return limpias[:10]

    def sugerir(self, q: str, resultados: int = -1, carpetas=None, modo: str = "todas",
                limite: int = 4) -> list:
        """
        Las propuestas del copiloto para esta búsqueda. NO se aplica nada: cada una
        lleva su «Aceptar» en la pantalla.
        """
        palabras = palabras_de(q, minimo=3)
        if not palabras:
            return []
        propuestas = []
        n_resultados = int(resultados) if resultados is not None and int(resultados) >= 0 else -1

        def _propia(tipo, titulo, porque, accion, **extra):
            p = {"tipo": tipo, "titulo": titulo, "porque": porque, "accion": accion}
            p.update(extra)
            propuestas.append(p)

        # 1) NO HAY RESULTADOS (o no lo sabe): palabras parecidas que sí salen
        if n_resultados == 0:
            candidatas = [v for v, _peso in self._parientes(palabras, 10)] + self._variantes(palabras)
            for mala in palabras:                       # «investimxnto» -> «investimento»
                candidatas = self.parecidas(mala, 4) + candidatas
            vistas = set()
            for v in candidatas:
                v = _sin_acentos(v)
                if not v or v in vistas or v in palabras:
                    continue
                vistas.add(v)
                n = self.contar(v)
                if n:
                    _propia("buscar", f"Buscar «{v}»",
                            f"no aparece «{q}», pero «{v}» sí sale en {n} documento(s) de su "
                            f"biblioteca", {"clase": "buscar", "q": v}, cuantos=n)
                if len(propuestas) >= limite:
                    break

        # 2) HAY RESULTADOS: afinar con una palabra que sale DENTRO de esos documentos
        if n_resultados != 0:
            dentro = self._palabras_de_los_resultados(palabras, 8)
            for palabra, _n in dentro:
                n = self.contar(list(palabras) + [palabra])
                if 0 < n < (n_resultados if n_resultados > 0 else 10 ** 9):
                    _propia("afinar", f"Añadir «{palabra}»",
                            f"es una de las palabras que más sale en esos documentos: dejaría "
                            f"{n} de {n_resultados if n_resultados > 0 else 'los'} documento(s)",
                            {"clase": "afinar", "q": q, "palabra": palabra}, cuantos=n)
                if len(propuestas) >= limite:
                    break

        # 3) POQUITOS RESULTADOS: probar «cualquier palabra» o quitar una
        if 0 < n_resultados <= 6 and modo == "todas" and len(palabras) > 1:
            n_sueltas = self.contar(palabras[0])
            if n_sueltas > n_resultados:
                _propia("modo", "Buscar «cualquier palabra»",
                        f"con TODAS las palabras salen {n_resultados} documento(s); con "
                        f"«cualquier palabra» saldrían más",
                        {"clase": "modo", "modo": "algunas"})
        if 0 < n_resultados <= 6 and len(palabras) > 1:
            for fuera in palabras:
                otras = [p for p in palabras if p != fuera]
                n = self.contar(otras)
                if n > n_resultados:
                    _propia("quitar", f"Buscar sin «{fuera}»",
                            f"sin esa palabra saldrían {n} documento(s) en vez de {n_resultados}",
                            {"clase": "buscar", "q": " ".join(otras)}, cuantos=n)
                    break

        # 4) ¿TODOS LOS RESULTADOS ESTÁN EN UNA CARPETA? Entonces se puede filtrar
        try:
            if carpetas and n_resultados > 4:
                por_carpeta = {}
                for c in carpetas:
                    valor, n = (c.get("valor"), int(c.get("coincidencias") or c.get("n") or 0)) \
                        if isinstance(c, dict) else (c, 0)
                    if valor and n:
                        por_carpeta[valor] = por_carpeta.get(valor, 0) + n
                if por_carpeta:
                    mejor, n = max(por_carpeta.items(), key=lambda x: x[1])
                    if n >= 0.8 * sum(por_carpeta.values()) and len(por_carpeta) > 1:
                        _propia("filtro", f"Buscar solo en «{mejor}»",
                                f"casi todo lo que sale ({n} de {sum(por_carpeta.values())}) está "
                                f"en esa carpeta", {"clase": "filtro", "carpeta": mejor})
        except Exception:
            pass

        # 4b) ABIERTO CON LA PROPUESTA: ver el texto completo del que MÁS coincide
        #     (es la comodidad de siempre, pero ofrecida por el copiloto).
        if n_resultados != 0 and not propuestas:
            mejor = self._mejor_documento(palabras)
            if mejor:
                _propia("abrir", f"Ver el texto de «{mejor['titulo'][:44]}»",
                        f"es el documento que más veces trae «{q}» ({mejor['n']} veces)",
                        {"clase": "abrir", "id": mejor["id"], "q": q})

        # 4c) LO REPETITIVO: «usted esto lo hace siempre igual».
        #     Se propone un BOTÓN FIJO (para no volver a escribirlo) y, si busca
        #     siempre con la misma forma, dejar ese modo puesto de una vez.
        #     Nada se guarda ni se cambia hasta que el usuario pulse «Aceptar».
        try:
            repetida = self.boton_mas_repetido()
            ya_es_boton = any(b["q"] == (repetida or {}).get("q") for b in self.botones())
            if repetida and not ya_es_boton and len(propuestas) < limite:
                _propia("boton", f"Dejar «{repetida['q'][:34]}» como botón fijo",
                        f"es la búsqueda que más repite ({repetida['veces']} veces): "
                        f"quedaría arriba a la izquierda, a un clic",
                        {"clase": "guardar-boton", "q": repetida["q"], "veces": repetida["veces"]})
        except Exception:
            pass
        try:
            formas = self.formas(3)
            if formas and len(propuestas) < limite:
                mejor = formas[0]
                usa_igual = self.forma_de(q, modo) == mejor["forma"]
                if mejor["veces"] >= 4 and usa_igual:
                    _propia("forma", f"Siempre busca «{mejor['forma']}»",
                            f"lo ha hecho así {mejor['veces']} veces: se puede dejar un "
                            f"botón «buscar así» para no elegir nada cada vez",
                            {"clase": "forma", "forma": mejor["forma"], "modo": modo})
        except Exception:
            pass

        # 5) Si todavía no sabe nada de esas palabras, lo dice (y sigue aprendiendo)
        if not propuestas:
            cuantos = self.cuantos()
            if cuantos["documentos_leidos"] < self.total_documentos():
                _propia("aprender", "Seguir leyendo sus documentos",
                        f"lleva {cuantos['documentos_leidos']:,} de "
                        f"{self.total_documentos():,} documento(s); cuanto más lea, mejores "
                        f"propuestas le hará".replace(",", "."),
                        {"clase": "aprender"})
        return propuestas[:limite]

    # ------------------------------------------------------------------ lo que el usuario decide
    def aceptar(self, propuesta: dict) -> dict:
        p = propuesta or {}
        self._anotar("aceptó", f"{p.get('tipo', '?')}: {p.get('titulo', '')} "
                               f"({p.get('porque', '')})")
        # r28-d · lo repetitivo que el usuario aceptó: botón fijo o forma guardada
        try:
            accion0 = p.get("accion") or {}
            clase = accion0.get("clase") or ""
            if clase == "guardar-boton" and accion0.get("q"):
                clave = _sin_acentos(str(accion0["q"]).lower().strip())
                with self._con() as c:
                    c.execute("INSERT INTO botones(q, veces, creado, modo) VALUES(?,?,?,?) "
                              "ON CONFLICT(q) DO UPDATE SET veces=MAX(veces,?)",
                              (clave, int(accion0.get("veces") or 1),
                               time.strftime("%Y-%m-%d %H:%M"), "", int(accion0.get("veces") or 1)))
                self._anotar("botón fijo", f"«{accion0['q']}» queda como botón en la pantalla")
            elif clase == "forma" and accion0.get("modo"):
                self._ajuste("modo_por_defecto", accion0["modo"])
                self._anotar("forma", f"modo «{accion0['modo']}» guardado como el de siempre")
            # si acepta el botón, ya no se le vuelve a proponer esa búsqueda
            if clase == "guardar-boton" and accion0.get("q"):
                with self._con() as c:
                    c.execute("DELETE FROM repes WHERE q = ?",
                              (_sin_acentos(str(accion0["q"]).lower().strip()),))
        except sqlite3.Error:
            pass
        # refuerza lo que sirvió, para acertar más la próxima vez
        try:
            accion = p.get("accion") or {}
            palabra = accion.get("palabra") or accion.get("q") or ""
            for p0 in palabras_de(palabra, minimo=4):
                with self._con() as c:
                    c.execute("INSERT INTO terminos(t, veces, docs, ultima) VALUES(?,?,0,?) "
                              "ON CONFLICT(t) DO UPDATE SET veces=veces+3", (p0, 3,
                              time.strftime("%Y-%m-%d %H:%M")))
        except sqlite3.Error:
            pass
        return {"ok": True}

    def descartar(self, propuesta: dict) -> dict:
        p = propuesta or {}
        self._anotar("descartó", f"{p.get('tipo', '?')}: {p.get('titulo', '')}")
        try:                                   # lo descartado pesa menos la próxima vez
            accion = p.get("accion") or {}
            palabra = accion.get("palabra") or ""
            if palabra:
                with self._con() as c:
                    c.execute("UPDATE relaciones SET peso=MAX(0.0, peso-2) WHERE b=?", (palabra,))
        except sqlite3.Error:
            pass
        return {"ok": True}

    # ---------------------------------------------------------------- formas de buscar
    @staticmethod
    def forma_de(q: str, modo: str = "") -> str:
        """
        La «forma» de una búsqueda: cómo la escribió el usuario, no qué buscó.
        Así el copiloto puede decir «usted siempre busca igual» y ofrecer un atajo.
        """
        t = (q or "").strip()
        if not t:
            return ""
        n_palabras = len(t.split())
        if t.startswith('"') and t.endswith('"'):
            clase = "una frase exacta"
        elif n_palabras == 1:
            clase = "una sola palabra"
        elif n_palabras == 2:
            clase = "dos palabras"
        else:
            clase = f"{n_palabras} palabras"
        if modo and modo != "todas":
            clase += f" · modo «{'cualquier palabra' if modo == 'algunas' else modo}»"
        return clase

    def anotar_busqueda(self, q: str, resultados: int = 0, modo: str = "") -> dict:
        """
        El usuario buscó algo: se apunta, y lo que abra después reforzará el saber.
        Además se aprende la FORMA (una palabra / frase / varias) y cuántas veces
        repite la misma búsqueda: de ahí salen las propuestas de acciones repetitivas.
        """
        if not q:
            return {"ok": True}
        self._anotar("búsqueda", f"«{q}» → {resultados} documento(s)")
        self._ajuste("ultima_busqueda", q)
        try:
            forma = self.forma_de(q, modo)
            cuando = time.strftime("%Y-%m-%d %H:%M")
            with self._con() as c:
                if forma:
                    c.execute("INSERT INTO formas(forma, veces, ultima, ejemplo) VALUES(?,1,?,?) "
                              "ON CONFLICT(forma) DO UPDATE SET veces=veces+1, ultima=?, "
                              "ejemplo=excluded.ejemplo",
                              (forma, cuando, q[:80], cuando))
                clave = _sin_acentos(q.lower().strip()) or q.strip()
                c.execute("INSERT INTO repes(q, veces, ultima, modo) VALUES(?,1,?,?) "
                          "ON CONFLICT(q) DO UPDATE SET veces=veces+1, ultima=?",
                          (clave, cuando, modo or "", cuando))
        except sqlite3.Error:
            pass
        return {"ok": True}

    def formas(self, cuantas: int = 5) -> list:
        """Las formas de buscar más repetidas (para proponer atajos)."""
        try:
            with self._con() as c:
                filas = c.execute("SELECT forma, veces, ultima, ejemplo FROM formas "
                                  "ORDER BY veces DESC LIMIT ?", (int(cuantas),)).fetchall()
            return [dict(f) for f in filas]
        except sqlite3.Error:
            return []

    def botones(self) -> list:
        """Los botones de búsqueda que el usuario ACEPTÓ (los que se pintan en la pantalla)."""
        try:
            with self._con() as c:
                filas = c.execute("SELECT q, veces, modo FROM botones ORDER BY veces DESC, q LIMIT 12"
                                  ).fetchall()
            return [dict(f) for f in filas]
        except sqlite3.Error:
            return []

    def boton_mas_repetido(self, minimo: int = 3):
        """
        La búsqueda que MÁS REPITE y que todavía no tiene botón: es la candidata a
        proponerle al usuario «¿te lo dejo como botón fijo?». (Si ya lo aceptó una
        vez, no se le vuelve a preguntar: para eso está la tabla de botones.)
        """
        try:
            with self._con() as c:
                f = c.execute("SELECT r.q AS q, r.veces AS veces, r.modo AS modo FROM repes r "
                              "WHERE r.veces >= ? AND NOT EXISTS "
                              "(SELECT 1 FROM botones b WHERE b.q = r.q) "
                              "ORDER BY r.veces DESC LIMIT 1", (int(minimo),)).fetchone()
            return dict(f) if f else None
        except sqlite3.Error:
            return None

    # ------------------------------------------------------------------ papel
    def informe_texto(self, limite_diario: int = 60) -> str:
        d = self.resumen()
        lineas = [
            "COPILOTO · INFORME",
            "==================",
            "",
            f"aprende sola          : {'SÍ' if d['auto'] else 'NO'}",
            f"palabras que sabe     : {d['terminos']:,}".replace(",", "."),
            f"relaciones aprendidas : {d['relaciones']:,}".replace(",", "."),
            f"documentos leídos     : {d['documentos_leidos']:,} de "
            f"{d['total_documentos']:,}".replace(",", "."),
            f"última lectura        : {d['ultima'] or '(todavía no)'}",
            "",
            "EL COPILOTO NO CAMBIA NADA SOLO:",
            "  · aprende leyendo sus documentos (no los toca, solo los lee);",
            "  · propone búsquedas y filtros, y solo se aplican si usted pulsa Aceptar.",
            "",
            "LO ÚLTIMO QUE PASÓ",
            "------------------",
        ]
        try:
            with self._con() as c:
                filas = c.execute("SELECT cuando, tipo, detalle FROM diario "
                                  "ORDER BY id DESC LIMIT ?", (int(limite_diario),)).fetchall()
            for f in filas:
                lineas.append(f"[{f['cuando']}] {f['tipo']}: {f['detalle']}")
        except sqlite3.Error:
            lineas.append("(todavía no hay nada apuntado)")
        return "\n".join(lineas) + "\n"



