MAXIMO_COPIAS = 3


def copiar_base_datos(origen, destino, con_permiso=False):
    """
    Copia CONSISTENTE del índice. Se usa la copia propia de SQLite, así entra
    también lo que todavía está en el archivo -wal (si la aplicación se cerró
    de golpe, una copia normal del .db dejaría documentos fuera).
    """
    if not con_permiso:
        try:
            con_o = sqlite3.connect(f"file:{origen}?mode=ro", uri=True, timeout=20)
            con_d = sqlite3.connect(destino)
            try:
                con_o.backup(con_d)
            finally:
                con_d.close()
                con_o.close()
            for sufijo in ("-wal", "-shm"):     # la copia queda como UN solo archivo
                resto = destino + sufijo
                if os.path.exists(resto):
                    try:
                        os.remove(resto)
                    except OSError:
                        pass
            return True
        except Exception:
            pass
    try:
        shutil.copy2(origen, destino)
        for sufijo in ("-wal", "-shm"):
            if os.path.exists(origen + sufijo):
                shutil.copy2(origen + sufijo, destino + sufijo)
        return True
    except OSError:
        return False


def cuantos_documentos(ruta_db):
    """Cuántos documentos tiene un índice (sin tocarlo). -1 si no se puede leer."""
    try:
        con = sqlite3.connect(f"file:{ruta_db}?mode=ro", uri=True, timeout=10)
        try:
            return con.execute("SELECT COUNT(*) FROM documentos").fetchone()[0] or 0
        finally:
            con.close()
    except Exception:
        return -1


def respaldar_base_datos(forzar=False):
    """
    Guarda una copia del índice (una por día, se conservan las últimas 3).

    Sirve para poder volver atrás si alguna vez la biblioteca quedara vacía.
    Nunca reemplaza una copia por otra más pobre: solo la mejora.
    """
    try:
        if not os.path.exists(RUTA_DB) or os.path.getsize(RUTA_DB) == 0:
            return ""
        if cuantos_documentos(RUTA_DB) <= 0:
            return ""
        os.makedirs(CARPETA_COPIAS, exist_ok=True)
        dia = time.strftime("%Y%m%d")
        destino = os.path.join(CARPETA_COPIAS, f"biblioteca-{dia}.db")
        mejora = (not os.path.exists(destino)
                  or cuantos_documentos(RUTA_DB) > max(0, cuantos_documentos(destino)))
        if forzar or mejora:
            copiar_base_datos(RUTA_DB, destino)
        copias = sorted([f for f in os.listdir(CARPETA_COPIAS)
                         if f.startswith("biblioteca-") and f.endswith(".db")],
                        reverse=True)
        for viejo in copias[MAXIMO_COPIAS:]:
            try:
                os.remove(os.path.join(CARPETA_COPIAS, viejo))
            except OSError:
                pass
        return destino
    except OSError:
        return ""


def guardar_marca():
    """Deja apuntada en la carpeta personal del usuario la biblioteca que está en uso."""
    return marca_guardar(DATOS, cuantos_documentos(RUTA_DB), carpetas_de())


