def escritorio_de() -> str:
    """La carpeta del Escritorio (donde él va a buscar el archivo)."""
    try:
        casa = os.path.expanduser("~")
    except Exception:
        casa = ""
    for nombre in ("Desktop", "Escritorio", "OneDrive/Desktop",
                   "OneDrive/Escritorio"):
        try:
            ruta = os.path.join(casa, *nombre.split("/"))
            if os.path.isdir(ruta):
                return ruta
        except Exception:
            continue
    return casa or os.getcwd()


