            consulta_del_usuario = consulta
            frase_buena = info["frase"] or None      # la frase completa va primero
            aviso = info["aviso"] or info2aviso(info, articulos)
            limite = max(1, min(int(p.get("limite", 300) or 300), 10000))   # hasta 10.000 documentos
            desplazamiento = max(0, int(p.get("desplazamiento", 0) or 0))
            carpetas = carpetas_pedidas(p)
            filtros = dict(tipo=p.get("tipo"), categoria=p.get("categoria"),
                           etiqueta=p.get("etiqueta"), anio=p.get("anio"), estado=p.get("estado"),
                           carpetas=carpetas, limite_docs=limite)
            resultados, total, total_docs, total_aproximado = ([], 0, 0, False)
            por_carpeta = []
            faltan_carpetas = False
